insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ''''لَوْلَا أَنْ أَشُقَّ عَلَى الْمُؤْمِنِينَ – وَفِي حَدِيثِ زُهَيْرٍ: عَلَى أُمَّتِي – لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاة''''. (م)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "സത്യവിശ്വാസികൾക്ക് - സുഹൈറിന്റെ നിവേദനത്തിൽ: എന്റെ സമുദായത്തിന് - ബുദ്ധിമുട്ടുണ്ടാകുമായിരുന്നില്ലെങ്കിൽ ഞാൻ അവരോട് ഓരോ നിസ്കാരത്തിന്റെയും മുമ്പായി ദന്തശുദ്ധി വരുത്താൻ കൽപ്പിക്കുമായിരുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 715, 715, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ طَلْحَةَ رَضِيَ اللهُ عَنْهُ عَنْ أَبِيهِ، قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: ''''إِذَا وَضَعَ أَحَدُكُمْ بَيْنَ يَدَيْهِ مِثْلَ مُؤْخِرَةِ الرَّحْلِ، فَلْيُصَلِّ وَلَا يُبَالِ مَنْ مَرَّ وَرَاءَ ذَلِكَ''''. (م,د,ت,جه)', 'ത്വൽഹ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളാരെങ്കിലും മുന്നിൽ വാഹനത്തിൽ ചാരിയിരിക്കുന്ന പലക പോലുള്ളത് വെച്ചാൽ അതിനപ്പുറത്തുകൂടെ ആളുകൾ നടക്കുന്നത് പരിഗണിക്കേണ്ടതില്ല." (മു,ദ,തു,ജ)', 'طَلْحَةَ', 'ത്വൽഹ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 715, 715, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَرَجَ يَوْمَ الْعِيدِ، أَمَرَ بِحَرْبَةٍ فَتُوضَعُ بَيْنَ يَدَيْهِ فَيُصَلِّي إِلَيْهَا وَالنَّاسُ وَرَاءَهُ، وَكَانَ يَفْعَلُ ذَلِكَ فِي السَّفَرِ، فَمِنْ ثَمَّ اتَّخَذَهَا الْأُمَرَاءُ. (ق,د,ن,جه)', 'അനസ്(റ): നബി(സ) പെരുന്നാൾ ദിവസം പുറപ്പെട്ടാൽ ഞങ്ങളോട് ഒരു വടി കൊണ്ടുവരാൻ കൽപിക്കുമായിരുന്നു. നബി(സ) അത് മുന്നിൽ വെച്ച് അതിലേക്ക് തിരിഞ്ഞു നിന്ന് നിസ്കരിക്കും, ജനങ്ങൾ നബി(സ)യുടെ പിന്നിലും. യാത്രാ വേളകളിലും അപ്രകാരം ചെയ്യാറുണ്ട്. അന്നു മുതൽ ഭരണാധികാരികളും അപ്രകാരം തുടർന്നു. (ബു,മു,ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'അനസ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 715, 715, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَوْنِ بْنِ أَبِي جُحَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى بِهِمْ بِالْبَطْحَاءِ وَبَيْنَ يَدَيْهِ عَنَزَةٌ الظُّهْرَ رَكْعَتَيْنِ، وَالْعَصْرَ رَكْعَتَيْنِ، تُمُرُّ بَيْنَ يَدَيْهِ الْمَرْأَةُ وَالْحِمَارُ. (ق,د)', 'അബൂജുഹൈഫ(റ): നിശ്ചയം, നബി(സ) ബത്ഹാഇൽവച്ച് അവരെ (അനുചരർ)യുമായി ളുഹ്റും അസ്വ്റും ഈരണ്ട് റക്അത്ത് നിസ്കരിച്ചു. നബി(സ)യുടെ മുന്നിൽ ഒരു വടി നാട്ടിയിരുന്നു. അതിനു മുന്നിലൂടെ സ്ത്രീകളും കഴുതകളും നടക്കുന്നുണ്ടായിരുന്നു. (ബു,മു,ദ)', 'عَوْنِ بْنِ أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 715, 715, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ سَهْلِ بْنِ سَعْدٍ قَالَ: كَانَ بَيْنَ مُصَلَّى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَبَيْنَ الْجِدَارِ مَمَرُّ الشَّاةِ. (ق)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): നബി(സ)യുടെ നിസ്കാര സ്ഥലത്തിന്റെയും ചുമരിന്റെയും ഇടയിൽ ആടുകൾ കടന്നുപോവുന്ന വഴിയുണ്ടായിരുന്നു. (ബു,മു)', 'سَهْلِ بْنِ سَعْدٍ قَالَ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 715, 715, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا خَرَجَ لِحَاجَتِهِ تَبِعْتُهُ أَنَا وَغُلَامٌ، وَمَعَنَا عُكَّازَةٌ – أَوْ عَصًا، أَوْ عَنَزَةٌ – وَمَعَنَا إِدَاوَةٌ، فَإِذَا فَرَغَ مِنْ حَاجَتِهِ نَاوَلْنَاهُ الْإِدَاوَةَ. (خ)', 'അനസ്(റ): നബി(സ) പ്രാഥമികാവശ്യങ്ങൾ നിർവ്വഹിക്കാൻ പുറപ്പെട്ടാൽ ഞാനും ഒരടിമയും കൂടെയുണ്ടാകുമായിരുന്നു. ഞങ്ങളുടെ കയ്യിൽ ഒരു ഊന്നു വടിയോ, വടിക്കഷ്ണമോ ഉണ്ടാകും. ഒരു പാത്രം വെള്ളവുമുണ്ടാകും. ആവശ്യം നിർവ്വഹിച്ചാൽ പാത്രത്തിൽ നിന്ന് ഞങ്ങൾ വെള്ളമൊഴിച്ചു കൊടുക്കും. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 715, 716, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ تَبُوكَ عَنْ سُتْرَةِ الْمُصَلِّي، فَقَالَ: ''''مِثْلَ مُؤْخِرَةِ الرَّحْلِ''''. (ن)', 'ആഇശ(റ): തബൂക്ക് യുദ്ധ വേളയിൽ നിസ്കാരത്തിലെ മറയെ കുറിച്ച് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "വാഹനക്കാരന് ചാരിയിരിക്കാനുള്ള പലക പോലുള്ളത് മതിയാകും." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 716, 716, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ كَانَ يُعَرِّضُ رَاحِلَتَهُ فَيُصَلِّي إِلَيْهَا، قُلْتُ لِنَافِعٍ أَفَرَأَيْتَ إِذَا هَبَّتِ الرِّكَابُ قَالَ: كَانَ يَأْخُذُ هَذَا الرَّحْلَ فَيُعَدِّلُهُ فَيُصَلِّي إِلَى آخِرَتِهِ أَوْ مُؤَخَّرِهِ، وَكَانَ ابْنُ عُمَرَ رَضِيَ اللهُ عَنْهُ يَفْعَلُهُ. (ق,ت,ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) തന്റെ വാഹനത്തെ വിലങ്ങനെ നിർത്തി അതിലേക്ക് തിരിഞ്ഞ് നിസ്കരിച്ചു. ഞാൻ നാഫിഇ(റ)നോട് ചോദിച്ചു: വാഹനം ഇളകുന്ന സന്ദർഭത്തിലോ?. അദ്ദേഹം പറഞ്ഞു: അത്തരം സന്ദർഭത്തിൽ പ്രവാചകൻ(സ) വാഹനത്തെ പിടിച്ച് അതിനെ കൃത്യമാക്കി നിർത്തുകയും, എന്നിട്ട് അതിന്റെ ചാരു പലകയിലേക്ക് തിരിഞ്ഞ് നിസ്കരിക്കുകയും ചെയ്യുമായിരുന്നു. ഇബ്നുഉമറും(റ) ഇപ്രകാരം ചെയ്തിരുന്നു. (ബു,മു,തു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 716, 716, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنِ ابْنِ عُمَرَ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي إِلَى بَعِيرٍ. (د)', 'ഇബ്നുഉമർ(റ): നബി(സ) ഒട്ടകത്തിലേക്കു തിരിഞ്ഞ് നിസ്കരിക്കാറുണ്ടായിരുന്നു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 716, 716, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ''''إِذَا صَلَّى أَحَدُكُمْ فَلْيَجْعَلْ تِلْقَاءَ وَجْهِهِ شَيْئًا، فَإِنْ لَمْ يَجِدْ فَلْيَنْصِبْ عَصًا، فَإِنْ لَمْ يَكُنْ مَعَهُ عَصًا فَلْيَخْطُطْ خَطًّا، ثُمَّ لَا يَضُرُّهُ مَا مَرَّ أَمَامَهُ''''. قَالَ أَبُو دَاوُدَ: وَسَمِعْتُ أَحْمَدَ بْنَ حَنْبَلٍ وَصَفَ الْخَطَّ غَيْرَ مَرَّةً فَقَالَ: هَكَذَا، يَعْنِي بِالْعَرْضِ حَوْرًا دَوْرًا مِثْلَ الْهِلَالِ، يَعْنِي مُنْقَطِعًا. (د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിസ്കരിക്കുമ്പോൾ മുമ്പിൽ വല്ല മറയും ഉണ്ടാക്കുക, ഇല്ലെങ്കിൽ ഒരു വടി നാട്ടി വെക്കുക. വടിയും ഇല്ലെങ്കിൽ ഒരു വര വരക്കട്ടെ. പിന്നെ അയാളുടെ മുന്നിലൂടെ നടക്കുന്നതൊന്നും അയാൾക്ക് ശല്യമാവില്ല."
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ سُفْيَانَ بْنِ عُيَيْنَةَ قَالَ: رَأَيْتُ شَرِيكًا صَلَّى بِنَا فِي جَنَازَةِ الْعَصْرِ، فَوَضَعَ قَلَنْسُوَتَهُ بَيْنَ يَدَيْهِ، يَعْنِي فِي فَرِيضَةٍ حَضَرَتْ. (د)', 'സുഫ്യാനുബ്നു ഉയൈന(റ): ഒരു ജനാസ പരിപാലനത്തിനിടയിൽ ശരീക്(റ) ഞങ്ങൾക്ക് ഇമാമായി അസ്വർ നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടു. ശരീക്(റ) തന്റെ തൊപ്പി മുന്നിൽ വെച്ചു. അഥവാ ഒരു ഫർള് നിസ്കാരത്തിലായിരുന്നു അത്. (ദ)', 'سُفْيَانَ بْنِ عُيَيْنَةَ قَالَ', 'സുഫ്യാനുബ്നു ഉയൈന(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 716, 717, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ بُسْرِ بْنِ سَعِيدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ زَيْدَ بْنَ خَالِدٍ الْجُهَنِيَّ أَرْسَلَهُ إِلَى أَبِي جُهَيْمٍ يَسْأَلُهُ: مَاذَا سَمِعَ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْمَارِّ بَيْنَ يَدَيِ الْمُصَلِّي؟ قَالَ أَبُو جُهَيْمٍ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: ''''لَوْ يَعْلَمُ الْمَارُّ بَيْنَ يَدَيِ الْمُصَلِّي مَاذَا عَلَيْهِ لَكَانَ أَنْ يَقِفَ أَرْبَعِينَ خَيْرًا لَهُ مِنْ أَنْ يَمُرَّ بَيْنَ يَدَيْهِ''''. قَالَ أَبُو النَّضْرِ: لَا أَدْرِي، قَالَ: ''''أَرْبَعِينَ يَوْمًا، أَوْ شَهْرًا، أَوْ سَنَةً''''. (ق,د,ت,ن,جه)', 'ബുസ്റുബ്നു സഈദ്(റ): സൈദുബ്നു ഖാലിദ്(റ) അദ്ദേഹത്തെ അബൂജുഹൈമി(റ)ന്റെ അടുത്തേക്ക് പറഞ്ഞയച്ചു. നിസ്കരിക്കുന്നവന്റെ മുന്നിലൂടെ നടക്കുന്നതിനെ കുറിച്ച് റസൂൽ(സ) എന്ത് പറയുന്നതാണ് അദ്ദേഹം കേട്ടതെന്ന് അറിയാൻ വേണ്ടിയായിരുന്നു അത്. അബൂജുഹൈം(റ) പറഞ്ഞു; പ്രവാചകൻ(സ) ഇപ്രകാരം പറഞ്ഞു: "നിസ്കരിക്കുന്നവന്റെ മുന്നിലൂടെ നടക്കുന്നവൻ അവന്റെ ശിക്ഷയെ കുറിച്ച് അറിഞ്ഞിരുന്നെങ്കിൽ! അവനെ നാൽപത് ദിവസം (ദിവസം എന്നാണോ, മാസം എന്നാണോ, അതോ വർഷം എന്നാണോ അവിടുന്ന് പറഞ്ഞതെന്ന് എനിക്കറിയില്ല.) അവിടെ കാത്തു നിൽക്കുന്നതാണ് മുന്നിലൂടെ കടന്നു പോകുന്നതിനേക്കാൾ അയാൾക്ക് ഉത്തമമായത്." (ബു,മു,ദ,തു,ന,ജ)', 'بُسْرِ بْنِ سَعِيدٍ', 'ബുസ്റുബ്നു സഈദ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 717, 717, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: ''''لَوْ يَعْلَمُ أَحَدُكُمْ مَا لَهُ فِي أَنْ يَمُرَّ بَيْنَ يَدَيْ أَخِيهِ مُعْتَرِضًا فِي الصَّلَاةِ – كَانَ لَأَنْ يُقِيمَ مِائَةَ عَامٍ خَيْرٌ لَهُ مِنَ الْخَطْوَةِ الَّتِي خَطَاهَا''''. (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ നിസ്കരിക്കുന്നവന്റെ മുന്നിലൂടെ കടന്നു പോകുന്നവന്റെ ശിക്ഷയെക്കുറിച്ച് അറിഞ്ഞിരുന്നെങ്കിൽ നൂറു വർഷം അവിടെത്തന്നെ കാത്തു നിൽക്കുന്നതായിരിക്കും അയാളുടെ ആ ചുവടിനേക്കാൾ ഉത്തമമായത്." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 717, 717, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي صَالِحٍ السَّمَّانِ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ أَبَا سَعِيدٍ الْخُدْرِيَّ فِي يَوْمِ جُمُعَةٍ يُصَلِّي إِلَى شَيْءٍ يَسْتُرُهُ مِنَ النَّاسِ، فَأَرَادَ شَابٌّ مِنْ بَنِي أَبِي مُعَيْطٍ، أَنْ يَجْتَازَ بَيْنَ يَدَيْهِ، فَدَفَعَ نَحْرَهُ فَنَظَرَ الشَّابُّ فَلَمْ يَجِدْ مَسَاغًا إِلَّا بَيْنَ يَدَيْ أَبِي سَعِيدٍ، فَعَادَ لِيَجْتَازَ فَدَفَعَهُ أَبُو سَعِيدٍ أَشَدَّ مِنَ الْأُولَى، فَنَالَ مِنْ أَبِي سَعِيدٍ ثُمَّ دَخَلَ عَلَى مَرْوَانَ فَشَكَا إِلَيْهِ مَا لَقِيَ، قَالَ: وَدَخَلَ أَبُو سَعِيدٍ عَلَى مَرْوَانَ، فَقَالَ لَهُ مَرْوَانُ: مَالَكَ وَلِابْنِ أَخِيكَ؟ جَاءَ يَشْكُوكَ. فَقَالَ أَبُو سَعِيدٍ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: ''''إِذَا صَلَّى أَحَدُكُمْ إِلَى شَيْءٍ يَسْتُرُهُ مِنَ النَّاسِ، فَأَرَادَ أَحَدٌ أَنْ يَجْتَازَ بَيْنَ يَدَيْهِ، فَلْيَدْفَعْهُ فَإِنْ أَبَى فَلْيُقَاتِلْهُ، فَإِنَّمَا هُوَ شَيْطَانٌ''''. (ق,د)', 'അബൂസ്വാലിഹുസ്സമാൻ(റ): അബൂസഈദിൽ ഖുദിരി(റ) ഒരു വെള്ളിയാഴ്ച ദിനത്തിൽ ജനങ്ങളിൽ നിന്ന് തന്നെ മറക്കുന്ന ഒന്നിലേക്ക് തിരിഞ്ഞു നിസ്കരിക്കുന്നതായി ഞാൻ കണ്ടു. അപ്പോൾ ബനൂമുഹൈത്ത് ഗോത്രത്തിൽ പെട്ട ഒരു യുവാവ് കടന്നു വന്നു. അയാൾ അദ്ദേഹത്തിനു മുന്നിലൂടെ കടന്നു പോകാനുദ്ദേശിച്ചു. അബൂസഈദ്(റ) അയാളെ നെഞ്ചിനു പിടിച്ചു തള്ളി. അയാൾ ചുറ്റും നോക്കി, അബൂസഈദിന്റെ മുന്നിലൂടെയല്ലാതെ കടന്നു പോകാൻ മറ്റു വഴികളൊന്നും കണ്ടില്ല. അയാൾ മുന്നിലൂടെ തന്നെ കടക്കാൻ ശ്രമിച്ചു. വീണ്ടും അയാളെ നെഞ്ചിൽ ആദ്യത്തേതിനേക്കാൾ ശക്തമായി തള്ളി. അബൂസഈദി(റ)നോട് അയാൾക്ക് ദേഷ്യം വന്നു. അയാൾ മർവാന്റെ അടുത്ത് ചെന്ന് താൻ അഭിമുഖീകരിക്കേണ്ടി വന്ന പ്രശ്നത്തെക്കുറിച്ച് പറഞ്ഞു. അപ്പോൾ അബൂസഈദ്(റ) മർവാന്റെ അടുത്ത് വന്നു. മർവാൻ അയാളോട് ചോദിച്ചു: നിങ്ങൾക്കും സഹോദര പുത്രനുമിടയിൽ എന്താണ് പ്രശ്നം? അവൻ നിങ്ങളെ കുറിച്ച് പരാതി പറഞ്ഞിരിക്കുന്നു. അപ്പോൾ അബൂസഈദ്(റ) പറഞ്ഞു: റസൂൽ(സ) ഇപ്രകാരം പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "നിങ്ങൾ നിസ്കരിക്കുമ്പോൾ ജനങ്ങളിൽ നിന്നും മറ സ്വീകരിക്കുക. അരെങ്കിലും മുന്നിലൂടെ കടക്കാൻ ശ്രമിച്ചാൽ അയാളെ തള്ളുക, അയാൾ പ്രതിരോധിച്ചാൽ അയാളോട് യുദ്ധം ചെയ്യട്ടെ, കാരണം അയാൾ പിശാചാണ്." (ബു,മു,ദ)', 'أَبِي صَالِحٍ السَّمَّانِ', 'അബൂസ്വാലിഹുസ്സമാൻ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 717, 718, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ الْكَعْبَةَ هُوَ وَأُسَامَةُ بْنُ زَيْدٍ وَبِلَالٌ وَعُثْمَانُ بْنُ طَلْحَةَ الْحَجَبِيُّ فَأَغْلَقَهَا عَلَيْهِ. قَالَ عَبْدُ اللهِ بْنُ عُمَرَ: فَسَأَلْتُ بِلَالًا حِينَ خَرَجَ مَاذَا صَنَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: جَعَلَ عَمُودًا عَنْ يَسَارِهِ، وَعَمُودَيْنِ عَنْ يَمِينِهِ، وَثَلَاثَةَ أَعْمِدَةٍ وَرَاءَهُ، وَكَانَ الْبَيْتُ يَوْمَئِذٍ عَلَى سِتَّةِ أَعْمِدَةٍ، ثُمَّ صَلَّى وَجَعَلَ بَيْنَهُ وَبَيْنَ الْجِدَارِ نَحْوًا مِنْ ثَلَاثَةِ أَذْرُعٍ. (خ,ن)', 'ഇബ്നുഉമർ(റ): നിശ്ചയം, പ്രവാചകൻ(സ) കഅ്ബയിൽ പ്രവേശിച്ചു. കൂടെ ഉസാമത്തുബ്നു സൈദ്(റ), ബിലാൽ(റ), ഉസ്മാനുബ്നു ത്വൽഹ(റ) എന്നിവരുമുണ്ടായിരുന്നു. ഉസ്മാൻ(റ) (കഅ്ബയുടെ) വാതിലടച്ചു. പുറത്തു കടന്ന ശേഷം ബിലാലി(റ)നോട് അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) ചോദിച്ചു: റസൂൽ(സ) എന്താണ് ചെയ്തത്? അദ്ദേഹം പറഞ്ഞു: ''റസൂൽ(സ) ഒരു തൂണ് ഇടതു ഭാഗത്തും രണ്ട് തൂണ് വലതു ഭാഗത്തും മൂന്ന് തൂണുകൾ പിന്നിലും ആക്കിക്കൊണ്ട് നിസ്കരിച്ചു''. കഅബക്ക് അന്ന് ആറ് തൂണുകളാണ് ഉണ്ടായിരുന്നത്, നബിക്കും ചുമരിനും ഇടയിൽ ഏതാണ്ട് മൂന്ന് മുഴം അകലമുണ്ടായിരുന്നു. (ബു,ന)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 718, 718, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ''''مَنِ اسْتَطَاعَ مِنْكُمْ أَنْ لَا يَحُولَ بَيْنَهُ وَبَيْنَ قِبْلَتِهِ أَحَدٌ فَلْيَفْعَلْ''''. (د)', 'ഇബ്നുഉമർ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ആർക്കെങ്കിലും അയാൾക്കും കഅ്ബക്കും ഇടയിൽ ഒരാളും മറയാകാതെ നിൽക്കാൻ കഴിയുമെങ്കിൽ അങ്ങിനെ ചെയ്യട്ടെ." (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 718, 718, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنِ الْمِقْدَادِ بْنِ الْأَسْوَدِ رَضِيَ اللهُ عَنْهُ قَالَ: مَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي إِلَى عُودٍ، وَلَا شَجَرَةٍ إِلَّا جَعَلَهُ عَلَى حَاجِبِهِ الْأَيْمَنِ أَوِ الْأَيْسَرِ، وَلَا يَصْمُدُ لَهُ صَمْدًا. (د)', 'മിഖ്ദാദുബ്നു അസ്വദ്(റ): നബി(സ) വടിയുടേയോ, മരത്തിന്റേയോ നേരെ നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടിട്ടില്ല. അത് തന്റെ ഇടതു വശത്തോ, വലത് വശത്തോ ആക്കിയിട്ടല്ലാതെ, അതിന് നേരെ തിരിഞ്ഞു നിന്നിട്ടുമില്ല. (ദ)', 'الْمِقْدَادِ بْنِ الْأَسْوَدِ', 'മിഖ്ദാദുബ്നു അസ്വദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 718, 718, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ كَانَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَصِيرَةٌ يَبْسُطُهَا بِالنَّهَارِ، وَيَحْتَجِرُهَا بِاللَّيْلِ فَيُصَلِّي فِيهَا، فَفَطَنَ لَهُ النَّاسُ فَصَلَّوْا بِصَلَاتِهِ، وَبَيْنَهُ وَبَيْنَهُمُ الْحَصِيرَةُ فَقَالَ: ''''اكْلَفُوا مِنَ الْعَمَلِ مَا تُطِيقُونَ فَإِنَّ اللهَ عَزَّ وَجَلَّ لَا يَمَلُّ حَتَّى تَمَلُّوا وَإِنَّ أَحَبَّ الْأَعْمَالِ إِلَى اللهِ عَزَّ وَجَلَّ أَدْوَمُهُ وَإِنْ قَلَّ''''. ثُمَّ تَرَكَ مُصَلَّاهُ ذَلِكَ، فَمَا عَادَ لَهُ حَتَّى قَبَضَهُ اللهُ عَزَّ وَجَلَّ، وَكَانَ إِذَا عَمِلَ عَمَلًا أَثْبَتَهُ. (ن)', 'ആഇശ(റ): റസൂലി(സ)ന് ഒരു പായ ഉണ്ടായിരുന്നു. പകൽ അത് വിരിച്ചിടും, രാത്രിയിൽ ഒരു ഭാഗം മടക്കി വെക്കും. എന്നിട്ട് അതിൽ നിസ്കരിക്കും. അങ്ങനെ ജനങ്ങൾ ആ നിസ്കാരത്തെ കുറിച്ച് അറിയുകയും, നബി(സ)യോടൊപ്പം നിസ്കരിക്കുകയും ചെയ്തു. അവർക്കും നബി(സ)ക്കുമിടയിൽ പായ ഉണ്ടാവും. ശേഷം പ്രവാചകൻ(സ) പറയും; "നിങ്ങൾ കഴിയുന്നത്ര സൽകർമ്മങ്ങൾ ചെയ്യുക. നിങ്ങൾക്ക് മടുക്കുംവരെ പ്രതാപവാനായ അല്ലാഹുവിന് മടുക്കുകയില്ല, അല്ലാഹുവിന്റെ അടുക്കൽ ഏറ്റവും ഇഷ്ടപ്പെട്ട സൽകർമ്മം പതിവായി ചെയ്യുന്ന സൽകർമ്മമാണ്. അതെത്ര കുറച്ചാണെങ്കിലും ശരി." ശേഷം നബി(സ) ആ നിസ്കാര സ്ഥലം ഒഴിവാക്കി. പിന്നെ മരണം വരെ അങ്ങോട്ടു മടങ്ങിയിട്ടില്ല. നബി(സ) എന്തെങ്കിലും പ്രവൃത്തി ചെയ്യുകയാണെങ്കിൽ അത് പതിവായും നന്നാക്കിയും ചെയ്യാറുണ്ടായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 718, 719, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِعَرَفَةَ، فَجِئْتُ أَنَا وَالْفَضْلُ عَلَى أَتَانٍ، فَمَرَرْنَا عَلَى بَعْضِ الصَّفِّ، فَنَزَلْنَا عَنْهَا وَتَرَكْنَاهَا ثُمَّ دَخَلْنَا فِي الصَّفِّ. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) അറഫയിൽ നിസ്കരിക്കുകയായിരുന്നു. അപ്പോൾ ഞാനും ഫദ്ലും(റ) ഒരു കഴുതയുമായി വന്നു. ഞങ്ങൾ ചില അണികളിലൂടെ നടന്നു. പിന്നീട് കഴുതയെ ഉപേക്ഷിച്ച് അണിയിൽ വന്നു നിന്നു. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 719, 719, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي حُجْرَةِ أُمِّ سَلَمَةَ: فَمَرَّ بَيْنَ يَدَيْهِ عَبْدُ اللهِ أَوْ عُمَرُ ابْنُ أَبِي سَلَمَةَ – فَقَالَ بِيَدِهِ، فَرَجَعَ فَمَرَّتْ زَيْنَبُ بِنْتُ أُمِّ سَلَمَةَ، فَقَالَ بِيَدِهِ هَكَذَا، فَمَضَتْ فَلَمَّا صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ''''هُنَّ أَغْلَبُ''''. (جه)', 'ഉമ്മുസലമ(റ): നബി(സ) ഉമ്മുസലമ(റ)യുടെ മുറിയിൽ നിസ്കരിക്കുകയായിരുന്നു.അപ്പോൾ മുന്നിലൂടെ അബ്ദുല്ലയോ, ഉമറുബ്നു അബീ സലമയോ നടന്നു. നബി(സ) മടങ്ങാൻ കൈ കൊണ്ട് (ആഗ്യംകാണിച്ചു കൊണ്ട്) ആവശ്യപ്പെട്ടു. അപ്പോൾ അദ്ദേഹം തിരിച്ചു പോയി. പിന്നീട് സൈനബ് ബിൻത് ഉമ്മുസലമ നടന്നു, കൈ കൊണ്ട് ആംഗ്യം കാണിച്ചു. പക്ഷേ മഹതി അതിലൂടെ പോയി. നിസ്കരിച്ചു കഴിഞ്ഞപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അവർ സ്ത്രീകളാണ് മുൻകടന്നവർ." (ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 719, 719, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ جَابِرٍ، عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمْ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ''''يَقْطَعُ الصَّلَاةَ الْكَلْبُ الْأَسْوَدُ وَالْمَرْأَةُ الْحَائِضُ''''. (د,ن,جه)', 'ജാബിർ(റ): ഇബ്നുഅബ്ബാസ്(റ) നബി(സ)യിൽ നിന്ന് ഉദ്ധരിക്കുന്നു: "കറുത്ത നായയും, അശുദ്ധിയുള്ള സ്ത്രീയും നിസ്കാരത്തെ മുറിച്ചു കളയും." (ദ,ന,ജ)', 'جَابِرٍ، عَنِ ابْنِ عَبَّاسٍ', 'ജാബിർ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 719, 719, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ عَبْدِ اللهِ بْنِ مُغَفَّلٍ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ''''يَقْطَعُ الصَّلَاةَ الْمَرْأَةُ وَالْكَلْبُ وَالْحِمَارُ''''. (جه)', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ): നബി(സ) പറഞ്ഞു: "സ്ത്രീയും, നായയും, കഴുതയും നിസ്കാരത്തെ മുറിച്ചു കളയുന്നതാണ്." (ജ)', 'عَبْدِ اللهِ بْنِ مُغَفَّلٍ', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 719, 719, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ''''يَقْطَعُ الصَّلَاةَ إِذَا لَمْ يَكُنْ بَيْنَ يَدَيِ الرَّجُلِ، مِثْلُ مُؤْخِرَةِ الرَّحْلِ، الْمَرْأَةُ، وَالْحِمَارُ، وَالْكَلْبُ الْأَسْوَدُ''''. قَالَ: قُلْتُ: مَا بَالُ الْأَسْوَدِ مِنَ الْأَحْمَرِ؟ قَالَ: سَأَلْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَمَا سَأَلْتَنِي، فَقَالَ: ''''الْكَلْبُ الْأَسْوَدُ شَيْطَانٌ''''. (م,د,ت,ن,جه)', 'അബൂദർറ്(റ): നബി(സ) പറഞ്ഞു: "വാഹനത്തിന്റെ പിൻഭാത്തുള്ളതു പോലെയെങ്കിലും നിസ്കരിക്കുന്നവന്റെ മുമ്പിലില്ലെങ്കിൽ സ്ത്രീയും, കഴുതയും, കറുത്ത നായയും നിസ്കാരം മുറിക്കുന്നതാണ്." ഞാൻ ചോദിച്ചു: കറുത്ത നായക്ക് ചുവന്ന നായയേക്കാൾ എന്താണുള്ളത്? അദ്ദേഹം പറഞ്ഞു: ഇക്കാര്യം നബി(സ)യോട് ഞാൻ ചോദിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "കറുത്ത നായ പിശാചാണ്." (മു,ദ,തു,ന,ജ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 719, 719, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَحْسَبُهُ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ''''إِذَا صَلَّى أَحَدُكُمْ إِلَى غَيْرِ سُتْرَةٍ فَإِنَّهُ يَقْطَعُ صَلَاتَهُ الْكَلْبُ وَالْحِمَارُ وَالْخِنْزِيرُ وَالْيَهُودِيُّ وَالْمَجُوسِيُّ وَالْمَرْأَةُ وَيُجْزِئُ عَنْهُ إِذَا مَرُّوا بَيْنَ يَدَيْهِ عَلَى قَذْفَةٍ بِحَجَرٍ''''. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ മറയില്ലാതെ നിസ്കരിച്ചാൽ നിശ്ചയം, അവന്റെ നിസ്കാരത്തെ നായയും, കഴുതയും, പന്നിയും, ജൂതനും, അഗ്നിയാരാധകനും, സ്ത്രീയും മുറിച്ചു കളയും. അവർ മുന്നിലൂടെ നടക്കുമ്പോൾ ഒരു കല്ലെടുത്തെറിയൽ അവന് മതിയാകുന്നതാണ്." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 720, 720, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ يَزِيدَ بْنِ نِمْرَانَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَجُلًا بِتَبُوكَ مُقْعَدًا، فَقَالَ: مَرَرْتُ بَيْنَ يَدَيِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَا عَلَى حِمَارٍ وَهُوَ يُصَلِّي فَقَالَ: ''''اللَّهُمَّ اقْطَعْ أَثَرَهُ''''. فَمَا مَشَيْتُ عَلَيْهَا بَعْدُ. وَفِي رِوَايَةٍ: ''''قَطَعَ صَلَاتَنَا قَطَعَ اللهُ اثَرَهُ''''. وَفِي رِوَايَةٍ: عَنْ غَزْوَانَ الشَّامِيِّ: أَنَّهُ نَزَلَ بِتَبُوكَ وَهُوَ حَاجٌّ، فَإِذَا هُوَ بِرَجُلٍ مُقْعَدٍ، فَسَأَلَهُ عَنْ أَمْرِهِ فَقَالَ لَهُ: سَأُحَدِّثُكَ حَدِيثًا فَلَا تُحَدِّثْ بِهِ مَا سَمِعْتَ أَنِّي حَيٌّ إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَزَلَ بِتَبُوكَ إِلَى نَخْلَةٍ فَقَالَ: ''''هَذِهِ قِبْلَتُنَا''''. ثُمَّ صَلَّى إِلَيْهَا، فَأَقْبَلْتُ وَأَنَا غُلَامٌ أَسْعَى حَتَّى مَرَرْتُ بَيْنَهُ وَبَيْنَهَا، فَقَالَ: ''''قَطَعَ اللهُ أَثَرَهُ''''. فَمَا قُمْتُ عَلَيْهَا إِلَى يَوْمِي هَذَا. (د)', 'യസീദുബ്നു നിംറാൻ(റ): തബൂക്കിൽ വെച്ച് ഞാൻ ഒരാൾ ഇരിക്കുന്നതായി കണ്ടു. അയാൾ പറഞ്ഞു: ഞാൻ നബി(സ) നിസ്കരിച്ചു കൊണ്ടിരിക്കെ അവിടുത്തെ മുന്നിലൂടെ കഴുതപ്പുറത്ത് കടന്നുപോയി. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവേ, അയാളുടെ പരമ്പര നീ മുറിക്കേണമേ." പിന്നീട് ഞാൻ ആ വഴി നടന്നിട്ടില്ല.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=25), 1, 'وَفِي رِوَايَةٍ: ''''قَطَعَ صَلَاتَنَا قَطَعَ اللهُ اثَرَهُ''''.', 'മറ്റൊരു നിവേദനിൽ: "ഇയാൾ നമ്മുടെ നിസ്കാരം മുറിച്ചിരിക്കുന്നു. അല്ലാഹു ഇയാളുടെ പരമ്പര മുറിക്കട്ടെ." അസ്വാനുശ്ശാമിയിൽ നിന്നും റിപ്പോർട്ട് ചെയ്യുന്നു: അദ്ദേഹം ഹജ്ജ് ചെയ്യാൻ പോകുമ്പോൾ ആയിരിക്കെ തബൂക്കിൽ വന്നിറങ്ങി. അപ്പോഴതാ യുദ്ധത്തിൽ നിന്നും മാറ്റി നിർത്തപ്പെട്ട ഒരാൾ. അങ്ങനെ അയാളുടെ (മാറ്റിനിർത്തപ്പെട്ടതിന്റെ) കാര്യത്തെപ്പറ്റി അന്വേഷിച്ചു. അയാൾ പറഞ്ഞു: ഞാൻ നിനക്ക് കാര്യം പറഞ്ഞു തരാം. ഞാൻ ജീവിച്ചിരിക്കെ നീ അത് ആരോടും പറയരുത്. റസൂൽ(സ) ഒരു ഇത്തപ്പനക്കടുത്ത് തബൂക്കിൽ വന്നിറങ്ങി. എന്നിട്ട് തിരുമേനി(സ) പറഞ്ഞു: നമുക്ക് ഇതിന് നേരെ നിന്ന് നിസ്കരിക്കാം. പിന്നെ അതിലേക്ക് തിരിഞ്ഞ് നിസ്കരിക്കാൻ തുടങ്ങി. ഞാൻ കുട്ടിയായതിനാൽ ഞാൻ മുമ്പോട്ട് ചെന്ന് റസൂൽ(സ)ക്കും ഈത്തപ്പനക്കും ഇടയിലൂടെ നടന്നു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അല്ലാഹു അവന്റെ പരമ്പര മുറിക്കട്ടെ!" അതിനുശേഷം ഞാൻ ഇന്നുവരെയും അതുവഴി കടന്നുപോയിട്ടില്ല. (ദ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=25), 2, 'وَفِي رِوَايَةٍ: عَنْ غَزْوَانَ الشَّامِيِّ: أَنَّهُ نَزَلَ بِتَبُوكَ وَهُوَ حَاجٌّ، فَإِذَا هُوَ بِرَجُلٍ مُقْعَدٍ، فَسَأَلَهُ عَنْ أَمْرِهِ فَقَالَ لَهُ: سَأُحَدِّثُكَ حَدِيثًا فَلَا تُحَدِّثْ بِهِ مَا سَمِعْتَ أَنِّي حَيٌّ إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَزَلَ بِتَبُوكَ إِلَى نَخْلَةٍ فَقَالَ: ''''هَذِهِ قِبْلَتُنَا''''. ثُمَّ صَلَّى إِلَيْهَا، فَأَقْبَلْتُ وَأَنَا غُلَامٌ أَسْعَى حَتَّى مَرَرْتُ بَيْنَهُ وَبَيْنَهَا، فَقَالَ: ''''قَطَعَ اللهُ أَثَرَهُ''''. فَمَا قُمْتُ عَلَيْهَا إِلَى يَوْمِي هَذَا. (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: ''''كُنْتُ بَيْنَ يَدَيْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُصَلِّي، فَإِذَا أَرَدْتُ أَنْ أَقُومَ كَرِهْتُ أَنْ أَقُومَ فَأَمُرَّ بَيْنَ يَدَيْهِ انْسَلَلْتُ انْسِلَالًا. (ن)', 'ആഇശ(റ): മഹതി പറഞ്ഞു: പ്രവാചകൻ(സ) നിസ്കരിക്കുമ്പോൾ ഞാൻ അവിടുത്തെ മുന്നിലായിരുന്നു. ഞാൻ എഴുന്നേൽക്കാൻ ഉദ്ദേശിച്ചു. മുന്നിലൂടെ കടന്നു പോകേണ്ടി വരും എന്നതിനാൽ ഞാൻ എഴുന്നേൽക്കുന്നത് വെറുത്തു. പിന്നീട് ഞാൻ (പെട്ടെന്ന്) ഊർന്നിറങ്ങി. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 720, 720, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنِ الْفَضْلِ بْنِ الْعَبَّاسِ قَالَ: زَارَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَبَّاسًا فِي بَادِيَةٍ لَنَا، وَلَنَا كُلَيْبَةٌ وَحِمَارَةٌ تَرْعَى فَصَلَّى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْعَصْرَ وَهُمَا بَيْنَ يَدَيْهِ، فَلَمْ يُزْجَرَا وَلَمْ يُؤَخَّرَا. (ن)', 'ഫദ്ലുബ്നുൽ അബ്വാസ്(റ): നബി(സ) അബ്വാസിനെ ഒരു താഴ്വരയിൽ ചെന്ന് സന്ദർശിച്ചു. ഞങ്ങൾക്കവിടെ മേഞ്ഞു നടക്കുന്ന നായകളും, കഴുതകളുമുണ്ടായിരുന്നു. നബി(സ) അവിടെ വെച്ച് അസ്ർ നിസ്കരിച്ചു. അവ മുന്നിലൂടെ നടന്നു കൊണ്ടിരുന്നു. അവയെ തടയുകയോ, മാറ്റി നിർത്തുകയോ ചെയ്തില്ല. (ന)', 'الْفَضْلِ بْنِ الْعَبَّاسِ قَالَ', 'ഫദ്ലുബ്നുൽ അബ്വാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 720, 720, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ قَتَادَةَ قَالَ: قُلْتُ لِجَابِرِ بْنِ زَيْدٍ: مَا يَقْطَعُ الصَّلَاةَ؟ قَالَ: كَانَ ابْنُ عَبَّاسٍ يَقُولُ: الْمَرْأَةُ الْحَائِضُ وَالْكَلْبُ. (ن)', 'ഖതാദ(റ): ഞാൻ ജാബിറുബ്നു സൈദി(റ)നോട് നിസ്കാരം മുറിക്കുന്നത് എന്താണ് എന്നു ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: അശുദ്ധിയുള്ള സ്ത്രീയും, നായയുമാണെന്ന് ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞിട്ടുണ്ട്. (ന)', 'قَتَادَةَ قَالَ', 'ഖതാദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 721, 721, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ بَيْنَ يَدَيِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَبَيْنَ الْقِبْلَةِ، قَالَتْ: وَأَنَا حَائِضٌ. (د)', 'ആഇശ(റ): അവർ പറഞ്ഞു: ഞാൻ ആർത്തവകാരിയായിരിക്കെ, നബി(സ)ക്കും, ഖിബ്ലക്കും ഇടയിലായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 721, 721, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي صَلَاتَهُ مِنَ اللَّيْلِ وَهِيَ مُعْتَرِضَةٌ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ، رَاقِدَةً عَلَى الْفِرَاشِ الَّذِي يَرْقُدُ عَلَيْهِ، حَتَّى إِذَا أَرَادَ أَنْ يُوتِرَ أَيْقَظَهَا فَأَوْتَرَتْ. (ق,د,ن,جه)', 'ആഇശ(റ): പ്രവാചകൻ(സ) തന്റെ രാത്രി നിസ്കാരം നിർവ്വഹിക്കുകയായിരുന്നു. അവർ (ആഇശ) പ്രവാചകനും, ഖിബ്ലക്കും ഇടയിൽ നബി(സ) കിടന്നുറങ്ങുന്ന അതേ വിരിപ്പിൽ ഉറങ്ങുകയായിരുന്നു. പ്രവാചകൻ(സ) വിത്റ് നിസ്കരിക്കാൻ ഉദ്ദേശിക്കുമ്പോൾ അവരെയും വിളിച്ചുണർത്തും, ആഇശ(റ)യും വിത്റ് നിസ്കരിക്കും. (ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 721, 721, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ رَضِيَ اللهُ عَنْهَا، عَنْ أُمِّهَا قَالَتْ: كَانَ فِرَاشُهَا بِحِيَالِ مَسْجِدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ق,د,جه)', 'സൈനബ് ബിൻത് അബീ സലമ(റ) തന്റെ ഉമ്മയിൽ നിന്ന്: മഹതി പറഞ്ഞു: മഹതിയുടെ വിരിപ്പ് പ്രവാചകർ(സ)യുടെ പള്ളിയിലെ (മുന്നിൽ) മറയ്ക്കരികിലായിരുന്നു. (ബു,മു,ദ,ജ)', 'زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ', 'സൈനബ് ബിൻത് അബീ സലമ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 721, 721, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي وَأَنَا بِحَذَائِهِ وَرُبَّمَا أَصَابَنِي ثَوْبُهُ إِذَا سَجَدَ. (جه)', 'മൈമൂന(റ) (പ്രവാചക പത്നി): ഞാൻ നബി(സ)യുടെ വിരിപ്പിലായിരിക്കെ നബി(സ) അതിൽ നിസ്കരിക്കാറുണ്ടായിരുന്നു. സുജൂദിനിടയിൽ ചിലപ്പോൾ നബി(സ)യുടെ വസ്ത്രം എന്റെ ദേഹത്ത് വീഴാറുണ്ടായിരുന്നു. (ജ)', 'مَيْمُونَةَ', 'മൈമൂന(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 721, 721, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُصَلِّيَ خَلْفَ الْمُتَحَدِّثِ وَالنَّائِمِ. (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ചെറിയ അശുദ്ധിയുള്ളവരുടെയും, ഉറങ്ങുന്നവരുടെയും പിന്നിൽ നിന്നുള്ള നിസ്കാരം പ്രവാചകൻ(സ) വിരോധിച്ചിരിക്കുന്നു. (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 721, 721, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: بِئْسَمَا عَدَلْتُمُونَا بِالْحِمَارِ وَالْكَلْبِ! قَدْ رَأَيْتُ رَسُولَ اللهِ يُصَلِّي وَأَنَا مُعْتَرِضَةٌ بَيْنَ يَدَيْهِ، فَإِذَا أَرَادَ أَنْ يَسْجُدَ غَمَزَ رِجْلِي فَضَمَمْتُهَا إِلَيَّ ثُمَّ يَسْجُدُ. (ق,د,ن)', 'ആഇശ(റ): ഞങ്ങളെ (സ്ത്രീകളെ) നായകളും കഴുതകളുമായി തുല്യപ്പെടുത്തുന്ന നിങ്ങൾ എത്ര മോശം!, ഞാൻ മുന്നിൽ കിടക്കുകയായിരിക്കെ പ്രവാചകൻ(സ) നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. നബി(സ) സുജൂദ് ചെയ്യാനുദ്ദേശിച്ചാൽ എന്റെ കാലിൽ തൊടും, അപ്പോൾ ഞാനത് എന്നിലേക്ക് ചേർത്തു പിടിക്കും. ശേഷം പ്രവാചകൻ(സ) സുജുദ് ചെയ്യും. (ബു,മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 721, 721, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا قَالَتْ: كُنْتُ أَنَامُ، وَأَنَا مُعْتَرِضَةٌ فِي قِبْلَةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَيُصَلِّي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَا أَمَامَهُ، إِذَا أَرَادَ أَنْ يُوتِرَ غَمَزَنِي، فَقَالَ: ''''تَنَحِّي''''. (د)', 'ആഇശ(റ): പ്രവാചകൻ(സ) നിസ്കരിക്കുമ്പോൾ ഞാൻ ഖിബ്ലയുടെ ഭാഗത്ത് ഉറങ്ങുകയായിരുന്നു. ഞാൻ മുന്നിൽ ഉണ്ടായിരിക്കെ തന്നെ പ്രവാചകൻ(സ) നിസ്കരിച്ചു. അങ്ങനെ വിത്റ് നിസ്കരിക്കാൻ ഉദ്ദേശിക്കുമ്പോൾ എന്നെ പിച്ചിയ ശേഷം പറയും; "അൽപം മാറൂ." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 722, 722, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: جِئْتُ عَلَى حِمَارٍ وَفِي رِوَايَةٍ: أَقْبَلْتُ رَاكِبًا عَلَى أَتَانٍ وَأَنَا يَوْمَئِذٍ قَدْ نَاهَزْتُ الِاحْتِلَامَ، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِالنَّاسِ بِمِنًى، فَمَرَرْتُ بَيْنَ يَدَيْ بَعْضِ الصَّفِّ فَنَزَلْتُ، فَأَرْسَلْتُ الْأَتَانَ تَرْتَعُ، وَدَخَلْتُ فِي الصَّفِّ، فَلَمْ يُنْكِرْ ذَلِكَ أَحَدٌ. (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞാൻ കഴുതപ്പുറത്ത് വന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: ഞാൻ പ്രായപൂർത്തിയോടടുത്ത സന്ദർഭത്തിൽ, പ്രവാചകൻ(സ) മിനയിൽ വെച്ച് ജനങ്ങൾക്ക് ഇമാമായി നിസ്കരിച്ചു കൊണ്ടിരിക്കെ ഞാൻ ഒരു പെൺകഴുതപ്പുറത്ത് വന്നു. അപ്പോൾ ഞാൻ ചില അണികളിലൂടെ നടന്നു പോയി, ഞാൻ ഇറങ്ങി കഴുതയെ മേയാൻ വിട്ടു. ശേഷം ഒരു അണിയിൽ പ്രവേശിച്ചു (നിസ്കരിച്ചു.) അത് ആരും വിലക്കിയില്ല. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 722, 722, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=36), 1, 'وَفِي رِوَايَةٍ: أَقْبَلْتُ رَاكِبًا عَلَى أَتَانٍ وَأَنَا يَوْمَئِذٍ قَدْ نَاهَزْتُ الِاحْتِلَامَ، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِالنَّاسِ بِمِنًى، فَمَرَرْتُ بَيْنَ يَدَيْ بَعْضِ الصَّفِّ فَنَزَلْتُ، فَأَرْسَلْتُ الْأَتَانَ تَرْتَعُ، وَدَخَلْتُ فِي الصَّفِّ، فَلَمْ يُنْكِرْ ذَلِكَ أَحَدٌ. (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: ഞാൻ പ്രായപൂർത്തിയോടടുത്ത സന്ദർഭത്തിൽ, പ്രവാചകൻ(സ) മിനയിൽ വെച്ച് ജനങ്ങൾക്ക് ഇമാമായി നിസ്കരിച്ചു കൊണ്ടിരിക്കെ ഞാൻ ഒരു പെൺകഴുതപ്പുറത്ത് വന്നു. അപ്പോൾ ഞാൻ ചില അണികളിലൂടെ നടന്നു പോയി, ഞാൻ ഇറങ്ങി കഴുതയെ മേയാൻ വിട്ടു. ശേഷം ഒരു അണിയിൽ പ്രവേശിച്ചു (നിസ്കരിച്ചു.) അത് ആരും വിലക്കിയില്ല. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَبِي الصَّهْبَاءِ قَالَ: تَذَاكَرْنَا مَا يَقْطَعُ الصَّلَاةَ عِنْدَ ابْنِ عَبَّاسٍ، فَقَالَ: جِئْتُ أَنَا وَغُلَامٌ مِنْ بَنِي عَبْدِ الْمُطَّلِبِ عَلَى حِمَارٍ، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، فَنَزَلَ وَنَزَلْتُ، وَتَرَكْنَا الْحِمَارَ أَمَامَ الصَّفِّ فَمَا بَالَاهُ، وَجَاءَتْ جَارِيَتَانِ مِنْ بَنِي عَبْدِ الْمُطَّلِبِ فَدَخَلَتَا بَيْنَ الصَّفِّ فَمَا بَالَى ذَلِكَ. (د,ن)', 'അബൂസഹ്ബാഅ്(റ): ഞങ്ങൾ ഇബ്നുഅബ്ബാസി(റ)ന്റെ അടുത്ത് വെച്ച് നിസ്കാരം മുറിയുന്നതിനെ കുറിച്ച് സംസാരിക്കുകയായിരുന്നു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ) നിസ്കരിച്ചു കൊണ്ടിരിക്കെ ഞാനും ബനൂ അബ്ദുൽ മുത്തലിബ് ഗോത്രത്തിൽപ്പെട്ട ഒരു കുട്ടിയും ഒരു കഴുതപ്പുറത്ത് വന്നു. അണിയുടെ മുന്നിൽ കഴുതയെ നിർത്തി ഞങ്ങൾ രണ്ടുപേരും ഇറങ്ങി. അവിടുന്ന് അത് ശ്രദ്ധിച്ചില്ല. അപ്പോൾ ബനീ അബ്ദുൽ മുത്വലിബ് ഗോത്രത്തിൽപ്പെട്ട രണ്ടു പെൺകുട്ടികൾ വന്നു. അവർ അണിയിൽ പ്രവേശിച്ചു. അതും അവിടുന്ന് ശ്രദ്ധിച്ചില്ല. (ദ,ന)', 'أَبِي الصَّهْبَاءِ قَالَ', 'അബൂസഹ്ബാഅ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 722, 722, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَبِي بَرْزَةَ الْأَسْلَمِيِّ رَضِيَ اللهُ عَنْهُ، صَلَّى يَوْمًا فِي غَزْوَةٍ وَلِجَامُ دَابَّتِهِ بِيَدِهِ، فَجَعَلَتِ الدَّابَّةُ تُنَازِعُهُ، وَجَعَلَ يَتْبَعُهَا، فَقِيلَ لَهُ فِي ذَالِكَ فَقَالَ: إِنِّي غَزَوْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سِتَّ غَزَوَاتٍ أَوْ سَبْعَ غَزَوَاتٍ أَوْ ثَمَانَ وَشَهِدْتُ تَيْسِيرَهُ، وَإِنِّي إِنْ كُنْتُ أَنْ أُرَاجِعَ مَعَ دَابَّتِي أَحَبُّ إِلَيَّ مِنْ أَنْ أَدَعَهَا تَرْجِعُ إِلَى مَأْلَفِهَا فَيَشُقَّ عَلَيَّ. (خ)', 'അബൂബർസതുൽ അസ്ലമി(റ): ഒരു യുദ്ധത്തിൽ നിസ്കരിച്ചപ്പോൾ തന്റെ മൃഗത്തിന്റെ (കുതിരയുടെ) കടിഞ്ഞാൺ അദ്ദേഹത്തിന്റെ കയ്യിൽത്തന്നെയായിരുന്നു. മൃഗം അദ്ദേഹത്തെ വലിക്കാൻ തുടങ്ങി. അദ്ദേഹം വിടാതെ മൃഗത്തിന്റെ പിന്നാലെ തന്നെപോയി. നിസ്കാരത്തിൽ അങ്ങനെ ചെയ്തതിനെക്കുറിച്ച് ചിലർ അദ്ദേഹത്തോട് ചോദിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഞാൻ തിരുമേനി(സ)യോടൊപ്പം ആറോ ഏഴോ എട്ടോ യുദ്ധങ്ങളിൽ പങ്കെടുത്തിട്ടുണ്ട്. തിരുമേനിയുടെ വിട്ടുവീഴ്ചയുള്ള നടപടികൾ കണ്ടിട്ടുമുണ്ട്. മൃഗത്തെ അതിന്റെ ആലയിലേക്ക് പോകാൻ വിടുകയും എനിക്കു വിഷമം അനുഭവിക്കേണ്ടിവരികയും ചെയ്യുന്നതിനേക്കാൾ, കുതിരയുടെ കടിഞ്ഞാൻ വിടാതെ അതിന്റെ പിന്നാലെ പോകുന്നതാണ് എനിക്ക് കൂടുതലിഷ്ടം. (ബു)', 'أَبِي بَرْزَةَ الْأَسْلَمِيِّ', 'അബൂബർസതുൽ അസ്ലമി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 722, 722, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا ذُكِرَتْ حَدِيثُ الْخُسُوفِ، وَقَالَ فِي هَذِهِ الرِّوَايَةِ بَعْدَ قَوْلِهِ: ''''وَلَقَدْ رَأَيْتُ النَّارَ يَحْطِمُ بَعْضُهَا بَعْضًا'''': ''''وَرَأَيْتُ فِيهَا عَمْرَو بْنَ لُحَيٍّ يَجُرُّ قُصْبَهُ وَهُوَ الَّذِي سَيَّبَ السَّوَائِبَ''''. (خ)', 'ഗ്രഹണസംഭവത്തക്കുറിച്ചുള്ള വിവരണം ആഇശ(റ) നൽകിയത് മറ്റൊരു റിപ്പോർട്ടിൽ വന്നിട്ടുണ്ട്. "നരകത്തെ ഞാൻ കണ്ടപ്പോൾ അതിന്റെ ഒരു ഭാഗം മറ്റേ ഭാഗത്തെ തകർത്തുകൊണ്ടിരിക്കുന്നു" എന്ന് അരുളിയശേഷം ഈ നിവേദനത്തിൽ ഇതു കൂടിയുണ്ട്: "നരകത്തിൽ ഞാൻ അംറുബ്നുലുഹയ്യിനെ കണ്ടു, സർവ്വ സ്വതന്ത്രമായി ചുറ്റി നടക്കാൻ (ബിംബങ്ങൾക്ക്) മൃഗങ്ങളെ നേർച്ചയാക്കിയവൻ." (ബു)', 'عَائِشَةَ', 'ഗ്രഹണസംഭവത്തക്കുറിച്ചുള്ള വിവരണം ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 723, 723, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=39), 1, null, 'മറ്റൊരു നിവേദനിൽ വന്നിട്ടുണ്ട്. "നരകത്തെ ഞാൻ കണ്ടപ്പോൾ അതിന്റെ ഒരു ഭാഗം മറ്റേ ഭാഗത്തെ തകർത്തുകൊണ്ടിരിക്കുന്നു" എന്ന് അരുളിയശേഷം ഈ നിവേദനത്തിൽ ഇതു കൂടിയുണ്ട്: "നരകത്തിൽ ഞാൻ അംറുബ്നുലുഹയ്യിനെ കണ്ടു, സർവ്വ സ്വതന്ത്രമായി ചുറ്റി നടക്കാൻ (ബിംബങ്ങൾക്ക്) മൃഗങ്ങളെ നേർച്ചയാക്കിയവൻ." (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِاللَّيْلِ، وَأَنَا إِلَى جَنْبِهِ وَأَنَاحَائِضٌ، وَعَلَيَّ مِرْطٌ بَعْضُهُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ت)', 'ആഇശ(റ): അവർ പറഞ്ഞു: ഞാൻ നബി(സ)യുടെ ഒരു ഭാഗത്തായിരിക്കെ, അവിടുന്ന് നിസ്കരിക്കുകയായിരുന്നു. ഞാൻ ആർത്തവ കാരിയുമായിരുന്നു. എന്റെ പുതപ്പിന്റെ ഒരു ഭാഗം പ്രവാചകന്റെ(സ) ദേഹത്തായിരുന്നു. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 723, 723, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنِ الْفَضْلِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَانَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَنَحْنُ فِي بَادِيَةٍ لَنَا، وَمَعَهُ عَبَّاسٌ فَصَلَّى فِي صَحْرَاءَ، لَيْسَ بَيْنَ يَدَيْهِ سُتْرَةٌ، وَحِمَارَةٌ لَنَا، وَكَلْبَةٌ تَعْبَثَانِ بَيْنَ يَدَيْهِ، فَمَا بَالَى ذَلِكَ. (د,ن)', 'അൽഫദ്ലു ബ്നു അബ്വാസ്(റ): ഞങ്ങൾ ഒരു താഴ്വരയിലായിരിക്കെ നബി(സ)യും, അബ്വാസും(റ) ഞങ്ങളുടെ അടുത്ത് വന്നു. അങ്ങനെ മുന്നിൽ മറയില്ലാതെ അവിടുന്ന് മരുഭൂമിയിൽ നിസ്കരിച്ചു. ഞങ്ങളുടെ കഴുതയും, നായയും അവിടുത്തെ മുന്നിലൂടെ മേഞ്ഞിരുന്നു. അവിടുന്നത് പരിഗണിച്ചില്ല. (ദ,ന)', 'الْفَضْلِ بْنِ عَبَّاسٍ', 'അൽഫദ്ലു ബ്നു അബ്വാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 723, 723, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنِ الْحَسَنِ الْعُرَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: ذُكِرَ عِنْدَ ابْنِ عَبَّاسٍ مَا يَقْطَعُ الصَّلَاةَ، فَذَكَرُوا الْكَلْبَ وَالْحِمَارَ وَالْمَرْأَةَ فَقَالَ: مَا تَقُولُونَ فِي الْجَدْيِ؟ إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي يَوْمًا، فَذَهَبَ جَدْيٌ يَمُرُّ بَيْنَ يَدَيْهِ، فَبَادَرَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْقِبْلَةَ. (جه)', 'ഹസനുൽ ഉറനി(റ): അദ്ദേഹം പറയുന്നു: ഇബ്നുഅബ്ബാസി(റ)ന്റെ അടുത്ത് വെച്ച് നിസ്കാരം മുറിയുന്നതിനെ കുറിച്ച് പറയപ്പെട്ടു. നായയെയും, കഴുതയെയും, സ്ത്രീയെയും കുറിച്ച് പറഞ്ഞു. ആട്ടിൻ കുട്ടിയെ കുറിച്ചുള്ള അഭിപ്രായമെന്താണെന്ന് അദ്ദേഹം ചോദിച്ചു. ഒരു ദിവസം നബി(സ) നിസ്കരിക്കുമ്പോൾ ഒരാട്ടിൻ കുട്ടി മുൻപിലൂടെ നടന്നു. നബി(സ) അതിനെ ഖിബ്ലയുടെ ഭാഗത്തേക്ക് തെളിച്ചു. (ജ)', 'الْحَسَنِ الْعُرَنِيِّ', 'ഹസനുൽ ഉറനി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 723, 723, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أَبِي سَعِيدٍ عَنْ أَبِيهِ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: ''''إِذَا صَلَّى أَحَدُكُمْ فَلْيُصَلِّ إِلَى سُتْرَةٍ وَلْيَدْنُ مِنْهَا وَلَا يَدَعْ أَحَدًا يَمُرُّ بَيْنَ يَدَيْهِ فَإِنْ جَاءَ أَحَدٌ يَمُرُّ فَلْيُقَاتِلْهُ، فَإِنَّهُ شَيْطَانٌ''''. (م,د,ن,جه)', 'അബൂസഈദുൽ ഖുദിരി(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ഒരാൾ നിസ്കരിച്ചാൽ മറ സ്വീകരിക്കുകയും, അതിനോടടുത്ത് നിൽക്കുകയും ചെയ്യുക. നിങ്ങൾക്ക് മുന്നിലൂടെ ആരെയും നടക്കാൻ അനുവദിക്കാതിരിക്കുക. ആരെങ്കിലും നടന്നാൽ അയാളോട് യുദ്ധം ചെയ്യുക. കാരണം അവൻ പിശാചാണ്." (മു,ദ,ന,ജ)', 'أَبِي سَعِيدٍ عَنْ أَبِيهِ قَالَ', 'അബൂസഈദുൽ ഖുദിരി(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 723, 723, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ''''إِذَا كَانَ أَحَدُكُمْ يُصَلِّي، فَلَا يَدَعْ أَحَدًا يَمُرُّ بَيْنَ يَدَيْهِ، فَإِنْ أَبَى فَلْيُقَاتِلْهُ، فَإِنَّ مَعَهُ الْقَرِينَ''''. وَفِي رِوَايَةٍ: ''''فَإِنَّ مَعَهُ الْعُزَّى''''. (م,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും നിസ്കരിക്കുകയാണെങ്കിൽ, മുന്നിലൂടെ ആരെയും നടക്കാൻ അനുവദിക്കരുത്. അതിന് ആരെങ്കിലും വിസമ്മതിച്ചാൽ അയാളെ (ശക്തമായി) തടയുക. കാരണം അവന്റെ കൂടെ പിശാചുണ്ട്." മറ്റൊരു റിപ്പോർട്ടിൽ: "അവന്റെ കൂടെ ദുർമാർഗ്ഗം അവലംബിച്ചവൻ ഉണ്ട്." (മു,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 724, 724, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=44), 1, 'وَفِي رِوَايَةٍ: ''''فَإِنَّ مَعَهُ الْعُزَّى''''. (م,جه)', 'മറ്റൊരു നിവേദനിൽ: "അവന്റെ കൂടെ ദുർമാർഗ്ഗം അവലംബിച്ചവൻ ഉണ്ട്." (മു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أُهْدِيَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرُّوجُ حَرِيرٍ، فَلَبِسَهُ فَصَلَّى فِيهِ ثُمَّ انْصَرَفَ فَنَزَعَهُ نَزْعًا شَدِيدًا كَالْكَارِهِ لَهُ، وَقَالَ: ''''لَا يَنْبَغِي هَذَا لِلْمُتَّقِينَ''''. (ق,ن)', 'ഉഖ്ബത്തു ബ്നു ആമിർ(റ): പ്രവാചകർ(സ)ക്ക് പട്ടിന്റെ ഒരു വിരി നൽകപ്പെട്ടു, പ്രവാചകൻ(സ) അത് ധരിച്ചു കൊണ്ട് നിസ്കരിച്ചു. പിന്നീടത് വെറുക്കുന്നവനെ പോലെ ശക്തമായി വലിച്ചൂരി. എന്നിട്ട് പറഞ്ഞു; "ഇത് സൂക്ഷ്മാലുക്കൾക്ക് യോജിച്ചതല്ല." (ബു,മു,ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബത്തു ബ്നു ആമിർ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 724, 724, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَعَدَلْتُمُونَا بِالْكَلْبِ وَالْحِمَارِ لَقَدْ رَأَيْتُنِي مُضْطَجِعَةً عَلَى السَّرِيرِ فَيَجِيءُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَيَتَوَسَّطُ السَّرِيرَ فَيُصَلِّي، فَأَكْرَهُ أَنْ أُسَنِّحَهُ فَأَنْسَلُّ مِنْ قِبَلِ رِجْلَيِ السَّرِيرِ حَتَّى أَنْسَلَّ مِنْ لِحَافِي. (خ)', 'ആഇശ(റ): നിങ്ങൾ നായയോടും, കഴുതയോടും ഞങ്ങളെ തുല്യപ്പെടുത്തുകയാണോ? ഞാൻ കട്ടിലിൽ കിടക്കുകയായിരിക്കെ പ്രവാചകൻ(സ) കട്ടിലിന്റെ മധ്യ ഭാഗത്തിന് നേരെ നിസ്കരിച്ചു. അവിടുത്തെ ശ്രദ്ധ തിരിയുന്നത് ഞാൻ വെറുത്തു. അതിനാൽ ഞാൻ പുതപ്പിൽനിന്ന് നീങ്ങിപ്പോകുമാറ് കട്ടിലിന്റെ കാലിന്റെ ഭാഗത്തേക്ക് ഊർന്നിറങ്ങി. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 724, 724, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ جَابِرٍ، عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى حَصِيرٍ. حسن صحيح. (م,ت,جه)', 'ജാബിർ(റ), അബൂസഈദുൽ ഖുദിരി(റ): നബി(സ) പായയിൽ നിസ്കരിച്ചിരുന്നു. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (മു,തു,ജ)', 'جَابِرٍ، عَنْ أَبِي سَعِيدٍ', 'ജാബിർ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 724, 724, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ أُمَّ سُلَيْمٍ سَأَلَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَأْتِيَهَا فَيُصَلِّيَ فِي بَيْتِهَا، فَتَتَّخِذَهُ مُصَلًّى، فَأَتَاهَا فَعَمَدَتْ إِلَى حَصِيرٍ فَنَضَحَتْهُ بِمَاءٍ فَصَلَّى عَلَيْهِ وَصَلَّوْا مَعَهُ. (ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)യോട് ഉമ്മുസുലൈം(റ) തന്റെ വീട്ടിലേക്ക് വരാനും, അവിടെ വെച്ച് നിസ്കരിക്കാനും പറഞ്ഞു. ആ സ്ഥലം മഹതിക്കുള്ള നിസ്കാര സ്ഥലമാക്കാനായിരുന്നു അത്. നബി(സ) മഹതിയുടെ വീട്ടിൽ ചെന്നു. അവർ ഒരു പായ വെള്ളം കുടഞ്ഞ ശേഷം വിരിച്ചു. നബി(സ) അതിൽ നിസ്കരിച്ചു. അവരെല്ലാവരും അവിടത്തോടൊപ്പം നിസ്കരിച്ചു. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 724, 724, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَجُلٌ مِنَ الْأَنْصَارِ: يَا رَسُولَ اللهِ إِنِّي رَجُلٌ ضَخْمٌ وَكَانَ ضَخْمًا لَا أَسْتَطِيعُ أَنْ أُصَلِّيَ مَعَكَ – وَصَنَعَ لَهُ طَعَامًا وَدَعَاهُ إِلَى بَيْتِهِ – فَصَلِّ حَتَّى أَرَاكَ كَيْفَ تُصَلِّي فَأَقْتَدِيَ بِكَ. فَنَضَحُوا لَهُ طَرَفَ حَصِيرٍ كَانَ لَهُمْ، فَقَامَ فَصَلَّى رَكْعَتَيْنِ، قِيلَ لِأَنَسِ بْنِ مَالِكٍ: أَكَانَ يُصَلِّي الضُّحَى؟ قَالَ: لَمْ أَرَهُ صَلَّى إِلَّا يَوْمَئِذٍ. (خ,د)', 'അനസുബ്നു മാലിക്(റ): അൻസാരികളിൽ പെട്ട ഒരാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, ഞാൻ തടിച്ച ഒരാളാണ്. താങ്കളുടെ കൂടെ നിസ്കരിക്കാൻ എനിക്ക് സാധ്യമല്ല. അങ്ങനെ അദ്ദേഹം പ്രവാചകർ(സ)ക്കു വേണ്ടി ഭക്ഷണം തയ്യാറാക്കി അവിടുത്തെ വീട്ടിലേക്ക് ക്ഷണിച്ചു. (എന്നിട്ട് പറഞ്ഞു:) താങ്കൾ നിസ്കരിക്കുക, താങ്കൾ എങ്ങനെയാണ് നിസ്കരിക്കുന്നതെന്ന് ഞാൻ കാണുകയും, അത് തുടരുകയും ചെയ്യട്ടെ. അവരുടെ പായയുടെ ഒരു ഭാഗം നനച്ചു (മൃദുലമാക്കി) കൊടുത്തു. അതിൽ നിന്ന് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. ''ളുഹാ'' ആണോ നിസ്കരിച്ചത് എന്ന് അനസുബ്നു മാലികി(റ)നോട് ചോദിക്കപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: ഞാനത് അന്നല്ലാതെ കണ്ടിട്ടില്ല. (ബു,ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 724, 725, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي عَلَى الْحَصِيرِ وَالْفَرْوَةِ الْمَدْبُوغَةِ. (د)', 'മുഗീറത്തുബ്നു ശുഅ്ബ(റ): നബി(സ) പായയിലും, ഊറക്കിട്ട തോലിലും നിസ്കരിച്ചിരുന്നു. (ദ)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറത്തുബ്നു ശുഅ്ബ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 725, 725, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي عَلَى الْخُمْرَةِ. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) വിരിപ്പിൽ നിസ്കരിച്ചിരുന്നു. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 725, 725, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: صَلَّى وَهُوَ بِالْبَصْرَةِ عَلَى بِسَاطِهِ، ثُمَّ حَدَّثَ أَصْحَابَهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي عَلَى بِسَاطِهِ. [ز: في إسناده ضعيف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): അദ്ദേഹം ബസ്വറയിലായിരിക്കെ വിരിപ്പിൽ നിസ്കരിച്ചു. ശേഷം തന്റെ അനുയായികളോട് പറഞ്ഞു: നബി(സ) തന്റെ വിരിപ്പിൽ നിസ്കരിച്ചിരുന്നു. (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 725, 725, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي بَيْتِ أُمِّ سَلَمَةَ مُشْتَمِلًا فِي ثَوْبٍ وَاحِدٍ. حَسَنٌ صَحِيحٌ. (ق,ت,ن,جه)', 'ഉമറുബ്നു അബീ സലമ(റ): ഒറ്റ വസ്ത്രം ധരിച്ചു കൊണ്ട് ഉമ്മുസലമ(റ)യുടെ വീട്ടിൽ വെച്ച് പ്രവാചകൻ(സ) നിസ്കരിക്കുന്നത് അദ്ദേഹം കണ്ടിരുന്നു. ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി. (ബു,മു,തു,ന,ജ)', 'عُمَرَ بْنِ أَبِي سَلَمَةَ', 'ഉമറുബ്നു അബീ സലമ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 725, 725, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ سَائِلًا سَأَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الصَّلَاةِ فِي الثَّوْبِ الْوَاحِدِ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: ''''أَوَلِكُلِّكُمْ ثَوْبَانِ''''. (ق,د,ن,جه)', 'അബൂഹുറൈറ(റ): ഒറ്റ വസ്ത്രത്തിൽ നിസ്കരിക്കുന്നതിനെ കുറിച്ച് പ്രവാചക(സ)നോട് ഒരാൾ ചോദിച്ചപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങൾക്കൊക്കെ രണ്ട് വസ്ത്രം ഇല്ലയോ?" (ബു,മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 725, 725, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، إِنِّي لَأَكُونُ فِي الصَّيْدِ وَلَيْسَ عَلَيَّ إِلَّا الْقَمِيصُ، أَفَأُصَلِّي فِيهِ؟ قَالَ: ''''وَزُرَّهُ عَلَيْكَ وَلَوْ بِشَوْكَةٍ''''. (د,ن)', 'സലത്തമത്തുബ്നു അക്വഅ്(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരെ, ഞാൻ വേട്ടക്ക് പോവുമ്പോൾ എന്റെ കൈവശം ഒറ്റ ഖമീസല്ലാതെ മറ്റൊന്നും ഉണ്ടാവില്ല, എനിക്ക് അതു കൊണ്ട് നിസ്കരിക്കാമോ? പ്രവാചകൻ(സ) പറഞ്ഞു: "ഒരു മുള്ളു കൊണ്ടെങ്കിലും അതിനെ ചേർത്ത് കുത്തുക." (ദ,ന)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലത്തമത്തുബ്നു അക്വഅ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 726, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَشْهَدُ أَنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: ''''مَنْ صَلَّى فِي ثَوْبٍ وَاحِدٍ فَلْيُخَالِفْ بَيْنَ طَرَفَيْهِ''''. (خ,د)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) ഇപ്രകാരം പറയുന്നതായി കേട്ടിട്ടുണ്ടെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു: "ആരെങ്കിലും ഒറ്റ വസ്ത്രത്തിൽ നിസ്കരിക്കുകയാണെങ്കിൽ അവൻ അതിന്റെ അറ്റങ്ങൾ എതിർ ദിശയിൽ (പിരടിയിലേക്ക് ഇട്ടു കെട്ടികൊണ്ട്) ഇടട്ടെ!" (ബു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 726, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ جَابِرِ بْنِ عَبْدِاللهِ رَضِيَ اللهُ عَنْهُ يُحَدِّثُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَنْقُلُ مَعَهُمُ الْحِجَارَةَ لِلْكَعْبَةِ وَعَلَيْهِ إِزَارُهُ فَقَالَ لَهُ الْعَبَّاسُ عَمُّهُ: يَا ابْنَ أَخِي لَوْ حَلَلْتَ إِزَارَكَ فَجَعَلْتَ عَلَى مَنْكِبَيْكَ دُونَ الْحِجَارَةِ، قَالَ: فَحَلَّهُ فَجَعَلَهُ عَلَى مَنْكِبَيْهِ فَسَقَطَ مَغْشِيًّا عَلَيْهِ فَمَا رُئِيَ بَعْدَ ذَلِكَ عُرْيَانًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): റസൂൽ(സ) അവരോടപ്പം കഅ്ബക്ക് വേണ്ടി കല്ലുകൾ വഹിച്ചിരുന്നു. നബി(സ) തുണി ഉടുത്തിട്ടുണ്ടായിരുന്നു. അപ്പോൾ പിതൃസഹോദരൻ അബ്ബാസ്(റ) പറഞ്ഞു: സഹോദര പുത്രാ, നീ തുണി അഴിച്ചാൽ കല്ല് വെക്കുമ്പോൾ തോളിൽ വെക്കാമായിരുന്നു. അപ്പോൾ തുണി അഴിച്ച് തോളിൽ വെച്ചു. ഉടൻ പ്രവാചകൻ(സ) അബോധാവസ്ഥയിൽ നിലത്ത് വീണു. അതിന് ശേഷം ഒരിക്കലും അവിടുന്ന് നഗ്നനായി കാണപ്പെട്ടിട്ടില്ല. (ബു)', 'جَابِرِ بْنِ عَبْدِاللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 86', array['خ']::text[], array['ബു']::text[], null, null, 726, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ، أَنَّهُ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ اشْتِمَالِ الصَّمَّاءِ، وَأَنْ يَحْتَبِيَ الرَّجُلُ فِي ثَوْبٍ وَاحِدٍ لَيْسَ عَلَى فَرْجِهِ مِنْهُ شَيْءٌ. (خ)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ഒറ്റ വസ്ത്രം പുതക്കുന്നത് നബി(സ) വിരോധിച്ചിരിക്കുന്നു. ഗുഹ്യ സ്ഥാനങ്ങളിൽ ഒന്നും ധരിച്ചിട്ടില്ലാത്ത രൂപത്തിൽ ഒറ്റ വസ്ത്രത്തിൽ മുട്ട് കെട്ടിഇരിക്കുന്നതും (കാരണം ഔറത്ത് വെളിപ്പെടാൻ സാധ്യതയുണ്ട്.) (ബു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 87', array['خ']::text[], array['ബു']::text[], null, null, 726, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ بَيْعَتَيْنِ: عَنِ اللِّمَاسِ وَالنِّبَاذِ، وَأَنْ يَشْتَمِلَ الصَّمَّاءَ وَأَنْ يَحْتَبِيَ الرَّجُلُ فِي ثَوْبٍ وَاحِدٍ. (خ)', 'അബൂഹുറൈറ(റ): രണ്ട് കച്ചവടം നബി(സ) വിരോധിച്ചു: കണ്ണടച്ചു തൊട്ടുകൊണ്ടുള്ള കച്ചവടവും, വിലയുറപ്പിക്കാതെ പകരം നൽകുന്ന കച്ചവടവും. അതുപോലെ ഒറ്റ വസ്ത്രം കൊണ്ട് വിടവില്ലാത്ത രീതിയിൽ മൂടുന്നതും, ഒറ്റവസ്ത്രത്തിൽ മുട്ട് കെട്ടി ഇരിക്കുന്നതും. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 88', array['خ']::text[], array['ബു']::text[], null, null, 726, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ عَبْدِ اللهِ بْنِ السَّائِبِ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الصُّبْحَ بِمَكَّةَ، فَاسْتَفْتَحَ سُورَةَ الْمُؤْمِنِينَ، حَتَّى إِذَا جَاءَ ذِكْرُ مُوسَى وَهَارُونَ أَوْ ذِكْرُ مُوسَى وَعِيسَى أَخَذَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَعْلَةٌ فَحَذَفَ فَرَكَعَ، وَعَبْدُ اللهِ بْنُ السَّائِبِ حَاضِرٌ لِذَلِكَ. (م,د,ن,جه)', 'അബ്ദില്ലാഹിബ്നു സാഇബ്(റ): നബി(സ) ഞങ്ങളെയും കൊണ്ട് മക്കയിൽ വെച്ച് സുബ്ഹി നിസ്കരിച്ചു. ആദ്യം سورة المؤمنون പാരായണം ചെയ്തു. അങ്ങനെ മൂസാ(അ) - ഹാറൂൻ(അ), അല്ലെങ്കിൽ മൂസാ(അ) - ഈസാ(അ) സംബന്ധമായ പരാമർശങ്ങൾ വന്നപ്പോൾ ചുമ വന്നു. അപ്പോൾ പാരായണം നിർത്തി റുകൂഅ് ചെയ്തു. അബ്ദില്ലാഹിബ്നു സാഇബ്(റ) അപ്പോൾ അവിടെ ഉണ്ടായിരുന്നു. (മു,ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ السَّائِبِ', 'അബ്ദില്ലാഹിബ്നു സാഇബ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 89', array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 726, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ جَابِرِ بْنِ عَبْدِاللهِ رَضِيَ اللهُ عَنْهُ قَالَ خَرَجْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَسْفَارِهِ فَجِئْتُ لَيْلَةً لِبَعْضِ أَمْرِي فَوَجَدْتُهُ يُصَلِّي وَعَلَيَّ ثَوْبٌ وَاحِدٌ، فَاشْتَمَلْتُ بِهِ وَصَلَّيْتُ إِلَى جَانِبِهِ، فَلَمَّا انْصَرَفَ، قَالَ: مَا السُّرَى يَا جَابِرُ؟ فَأَخْبَرْتُهُ بِحَاجَتِي، فَلَمَّا فَرَغْتُ قَالَ: مَا هَذَا الِاشْتِمَالُ الَّذِي رَأَيْتُ؟ قُلْتُ: كَانَ ثَوْبٌ، قَالَ: فَإِنْ كَانَ وَاسِعًا فَالْتَحِفْ بِهِ، وَإِنْ كَانَ ضَيِّقًا فَاتَّزِرْ بِهِ. (خ)', 'ജാബിർ(റ): നബി(സ)യുടെ ചില യാത്രകളിൽ അവിടത്തോടൊപ്പം ഞാൻ പുറപ്പെട്ടു. അപ്പോൾ ഞാൻ നബി(സ) നിസ്കരിക്കുന്നതായി കണ്ടു. എന്റടുത്ത് ഒരു വസ്ത്രമേ ഉണ്ടായിരുന്നുള്ളൂ. ഞാൻ അത് ചുറ്റി ധരിച്ച് നബി(സ)യുടെ ഒരു വശത്തുനിന്ന് നിസ്കരിച്ചു. വിരമിച്ചപ്പോൾ എന്നോട് ചോദിച്ചു: "ജാബിർ! നീ എന്തിനാണ് രാത്രി പോയത്?" ഞാൻ എന്റെ ആവശ്യം അറിയിച്ചു. ഞാൻ നിസ്ക്കരിച്ചു കഴിഞ്ഞപ്പോൾ എന്നോട് ചോദിച്ചു: "നീ എന്താണീ ചുറ്റും ധരിച്ചത്?" ഞാൻ പറഞ്ഞു: എനിക്ക് ഒറ്റ വസ്ത്രമേ ഉള്ളൂ. അപ്പോൾ പറഞ്ഞു: "അത് വലുതാണെങ്കിൽ അത് ചുറ്റിപ്പുതക്കുക. വലുപ്പം കുറവാണെങ്കിൽ ഉടുക്കുക." (ബു)', 'جَابِرِ بْنِ عَبْدِاللهِ', 'ജാബിർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 90', array['خ']::text[], array['ബു']::text[], null, null, 727, 727, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ مُغِيرَةَ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ قَالَ: ''''يَا مُغِيرَةُ خُذِ الْإِدَاوَةَ فَأَخَذْتُهَا فَانْطَلَقَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى تَوَارَى عَنِّي فَقَضَى حَاجَتَهُ وَعَلَيْهِ جُبَّةٌ شَامِيَّةٌ، فَذَهَبَ لِيُخْرِجَ يَدَهُ مِنْ كُمِّهَا فَضَاقَتْ فَأَخْرَجَ يَدَهُ مِنْ أَسْفَلِهَا فَصَبَبْتُ عَلَيْهِ فَتَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ وَمَسَحَ عَلَى خُفَّيْهِ ثُمَّ صَلَّى. (خ)', 'മുഗീറബ്നു ശുഅ്ബ(റ): ഞാൻ നബി(സ)യുടെ കൂടെ ഒരു യാത്രയിലായിരുന്നു. അവിടുന്ന് പറഞ്ഞു: "മുഗീറാ, വെള്ളപാത്രം എടുക്കുക." ഞാൻ അത് എടുത്തു. പ്രവാചകൻ(സ) തന്റെ ആവശ്യം നിർവ്വഹിക്കുവാൻ ദൂരത്തേക്ക് പോയി. റസൂൽ(സ) ഒരു ശാമീ ജുബ്ബ ധരിച്ചിരുന്നു. അപ്പോൾ റസൂൽ(സ) അതിന്റെ കഫ്ഫിലൂടെ കൈ ഊരിയെടുക്കുവാൻ ശ്രമിച്ചു. അപ്പോൾ അത് ഇടുങ്ങി. പിന്നീട് താഴ്ഭാഗത്ത് കൂടെ ഊരിയെടുത്തു. ഞാൻ വെള്ളം ഒഴിച്ചു കൊടുത്തപ്പോൾ റസൂൽ(സ) നിസ്കാരത്തിന് വേണ്ടി വുളു ചെയ്തു. പിന്നീട് ഖുഫ്ഫ തടവികൊണ്ട് നിസ്കരിച്ചു. (ബു)', 'مُغِيرَةَ بْنِ شُعْبَةَ', 'മുഗീറബ്നു ശുഅ്ബ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 91', array['خ']::text[], array['ബു']::text[], null, null, 727, 727, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ: أَنَّهُ دَخَلَ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُصَلِّي فِي ثَوْبٍ وَاحِدٍ مُتَوَشِّحًا بِهِ. (جه)', 'അബൂസഈദുൽ ഖുദ്രി(റ): അദ്ദേഹം പ്രവാചകൻ(സ) ഒറ്റ വസ്ത്രത്തിൽ നിസ്കരിക്കുമ്പോൾ അങ്ങോട്ടു ചെന്നു. (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 92', array['جه']::text[], array['ജ']::text[], null, null, 727, 727, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: فَصَلَّى ثَمَانِيَ رَكَعَاتٍ مُلْتَحِفًا فِي ثَوْبٍ وَاحِدٍ، فَلَمَّا انْصَرَفَ قُلْتُ يَا رَسُولَ اللهِ: زَعَمَ ابْنُ أُمِّي أَنَّهُ قَاتِلٌ رَجُلًا قَدْ أَجَرْتُهُ فُلَانُ ابْنُ هُبَيْرَةَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: قَدْ أَجَرْنَا مَنْ أَجَرْتِ يَا أُمَّ هَانِئٍ، قَالَتْ أُمُّ هَانِئٍ: وَذَاكَ ضُحًى. (خ)', 'അബൂത്വാലിബിന്റെ മകൾ ഉമ്മുഹാനിഅ്(റ): തിരുമേനി(സ) ഒറ്റ വസ്ത്രം മാത്രം ധരിച്ചുകൊണ്ട് എട്ടു റക്അത്തു നിസ്കരിച്ചു. അപ്രകാരം തന്നെ, ആ നിസ്കാരത്തിൽനിന്നു തിരുമേനി(സ) വിരമിച്ചു കഴിഞ്ഞപ്പോൾ, ''ദൈവദൂതരേ! ഞാൻ അഭയം നൽകിയിരിക്കുന്ന ഇന്ന ആളെ കൊന്നുകളയുമെന്നു എന്റെ സഹോദരൻ ഭീഷണിപ്പെടുത്തുന്നു''വെന്നു ഞാൻ പറഞ്ഞു. അപ്പോൾ "ഓ, ഉമ്മുഹാനിഅ്! നീ അഭയം നൽകിയവന് ഞങ്ങളും അഭയം നൽകിയിരിക്കുന്നു"വെന്ന് തിരുമേനി(സ) അരുളി. തിരുമേനി(സ)യുടെ ആ നമസ്കാരം ''ളുഹാ'' നിസ്കാരമായിരുന്നുവെന്നാണ് ഉമ്മുഹാനിഅ്(റ) പറഞ്ഞിരിക്കുന്നത്. (ബു)', 'أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ', 'അബൂത്വാലിബിന്റെ മകൾ ഉമ്മുഹാനിഅ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 93', array['خ']::text[], array['ബു']::text[], null, null, 727, 727, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنِي أَبُو بَكْرٍ فِي تِلْكَ الْحَجَّةِ فِي مُؤَذِّنِينَ يَوْمَ النَّحْرِ نُؤَذِّنُ بِمِنًى أَنْ لَا يَحُجَّ بَعْدَ الْعَامِ مُشْرِكٌ، وَلَا يَطُوفُ بِالْبَيْتِ عُرْيَانٌ، قَالَ حُمَيْدُ بْنُ عَبْدالرَّحْمَنِ ثُمَّ أَرْدَفَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلِيًّا فَأَمَرَهُ أَنْ يُؤَذِّنَ بِبَرَاءَةٍ، قَالَ أَبُو هُرَيْرَةَ: فَأَذَّنَ مَعَنَا عَلِيٌّ فِي أَهْلِ مِنًى يَوْمَ النَّحْرِ، لَا يَحُجُّ بَعْدَ الْعَامِ مُشْرِكٌ، وَلَا يَطُوفُ بِالْبَيْتِ عُرْيَانٌ. (خ)', 'അബൂഹുറൈറ(റ): (അബൂബക്കറി(റ)നെ നേതാവായി നിയോഗിച്ചിരുന്ന) ആ ഹജ്ജിൽ, ബലിയുടെ ദിനത്തിൽ മിനായിൽ വെച്ച് ''ഈ വർഷത്തിനുശേഷം ഒരു ബഹുദൈവ വിശ്വാസിയും ഹജ്ജ് ചെയ്യാൻ പാടില്ല. വിവസ്ത്രനായി ഒരാളും തന്നെ കഅ്ബയെ പ്രദക്ഷിണം ചെയ്യരുത്'' എന്ന് വിളംബരം ചെയ്യാൻ നിയോഗിച്ചവരുടെ കൂട്ടത്തിൽ അബൂബക്കർ(റ) എന്നെയും നിയോഗിച്ചിരുന്നു. ഹുമൈദ് പറയുന്നു: ഖുർആനിലെ ''സൂറത്തു ബറാഅത്ത്'' വിളംബരം ചെയ്യാൻ വേണ്ടി തൊട്ടു പിന്നിലായി അലി(റ)യെ റസൂൽ(സ) നിയോഗിക്കുകയുണ്ടായി. അബൂഹുറൈറ(റ) തുടരുന്നു: ബലിയുടെ ദിനത്തിൽ ജനക്കൂട്ടത്തിൽ നിന്നുകൊണ്ട് ''ഈ വർഷത്തിനു ശേഷം ഒരു ബഹുദൈവ വിശ്വാസിയും ഹജ്ജ് ചെയ്യരുതെന്നും ഒരാളും വിവസ്ത്രനായിക്കൊണ്ട് കഅ്ബയെ പ്രദക്ഷിണം ചെയ്യരുതെന്നും ഞങ്ങളോടൊപ്പം അലി(റ)യും വിളംബരം ചെയ്തുകൊണ്ടിരുന്നു. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 94', array['خ']::text[], array['ബു']::text[], null, null, 728, 728, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يُصَلِّيَنَّ أَحَدُكُمْ فِي الثَّوْبِ الْوَاحِدِ لَيْسَ عَلَى عَاتِقه مِنْهُ شَيْءٌ". (خ,د,ن)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാളും ഒറ്റ വസ്ത്രത്തിൽ തന്റെ പിരടിയിൽ അതിന്റെ ഒരു ഭാഗം ഇല്ലാത്ത രീതിയിൽ നിസ്കരിക്കരുത്." (ബു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 57', array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 728, 728, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلٍ، عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي ثَوْبٍ وَاحِدٍ مُلْتَحِفًا مُخَالِفًا بَيْنَ طَرَفَيْهِ عَلَى مَنْكِبَيْهِ. (د,ت,ن,جه)', 'ഉമാമത്തുബ്നു സഹ്ല്, ഉമറുബ്നു അബീസലമ(റ): അദ്ദേഹം പറഞ്ഞു: പ്രവാചകൻ(സ) ഒറ്റ വസ്ത്രത്തിൽ - അതിന്റെ അറ്റങ്ങൾ രണ്ടും വിപരീത ദിശയിൽ ഇട്ടു കൊണ്ട് - ശരീരം പൊതിഞ്ഞു കൊണ്ട് നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടു. (ദ,തു,ന,ജ)', 'أَبِي أُمَامَةَ بْنِ سَهْلٍ، عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ', 'ഉമാമത്തുബ്നു സഹ്ല്, ഉമറുബ്നു അബീസലമ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 58', array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 728, 728, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَقَدْ رَأَيْتُ الرِّجَالَ عَاقِدِي أُزُرِهِمْ فِي أَعْنَاقِهِمْ مِنْ ضِيقِ الْأُزُرِ، خَلْفَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، كَأَمْثَالِ الصِّبْيَانِ، فَقَالَ قَائِلٌ: يَا مَعْشَرَ النِّسَاءِ لَا تَرْفَعْنَ رُءُوسَكُنَّ حَتَّى يَرْفَعَ الرِّجَالُ. (خ,د,ن)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): വസ്ത്രങ്ങൾ ഇല്ലാത്തതു കാരണം പുരുഷന്മാർ അവരുടെ വിരിപ്പ് കഴുത്തിൽ കെട്ടി നബി(സ)ക്കു പിന്നിൽ കുട്ടികളെപ്പോലെ നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടു. അപ്പോൾ ഒരാൾ പറഞ്ഞു; സ്ത്രീകളെ, പുരുഷന്മാർ തല ഉയർത്തിയ ശേഷമല്ലാതെ നിങ്ങൾ (സുജൂദിൽ നിന്ന്) തല ഉയർത്തരുത്. (ബു,ദ,ന)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 59', array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 728, 728, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَمَّنَا جَابِرُ بْنُ عَبْدِ اللهِ فِي قَمِيصٍ لَيْسَ عَلَيْهِ رِدَاءٌ، فَلَمَّا انْصَرَفَ قَالَ: إِنِّي رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي قَمِيصٍ. (م,د)', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്കർ(റ): ജാബിറുബ്നു അബ്ദില്ല(റ) ഞങ്ങൾക്ക് ഒറ്റ വസ്ത്രം ധരിച്ചുകൊണ്ട് മേൽ തട്ടമില്ലാതെ ഇമാമായി നിസ്കരിച്ചു. നിസ്കാര ശേഷം അദ്ദേഹം പറഞ്ഞു: നബി(സ) ഒറ്റ വസ്ത്രത്തിൽ നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (മു,ദ)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്കർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 60', array['م','د']::text[], array['മു','ദ']::text[], null, null, 729, 729, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ عُبَادَةَ بْنِ الْوَلِيدِ بْنِ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَتَيْنَا جَابِرًا يَعْنِي ابْنَ عَبْدِ اللهِ قَالَ: سِرْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةٍ، فَقَامَ يُصَلِّي، وَكَانَتْ عَلَيَّ بُرْدَةٌ،ذَهَبْتُ أُخَالِفُ بَيْنَ طَرَفَيْهَا فَلَمْ تَبْلُغْ لِي، وَكَانَتْ لَهَا ذَبَاذِبُ، فَنَكَّسْتُهَا ثُمَّ خَالَفْتُ بَيْنَ طَرَفَيْهَا، ثُمَّ تَوَاقَصْتُ عَلَيْهَا لَا تَسْقُطُ، ثُمَّ جِئْتُ حَتَّى قُمْتُ عَنْ يَسَارِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَخَذَ بِيَدِي فَأَدَارَنِي حَتَّى أَقَامَنِي عَنْ يَمِينِهِ، فَجَاءَ ابْنُ صَخْرٍ حَتَّى قَامَ عَنْ يَسَارِهِ، فَأَخَذَنَا بِيَدَيْهِ جَمِيعًا حَتَّى أَقَامَنَا خَلْفَهُ، قَالَ: وَجَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَرْمُقُنِي وَأَنَا لَا أَشْعُرُ، ثُمَّ فَطِنْتُ بِهِ، فَأَشَارَ إِلَيَّ أَنْ أَتَّزِرَ بِهَا، فَلَمَّا فَرَغَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَا جَابِرُ". قَالَ: قُلْتُ: لَبَّيْكَ يَا رَسُولَ اللهِ، قَالَ: "إِذَا كَانَ وَاسِعًا فَخَالِفْ بَيْنَ طَرَفَيْهِ، وَإِذَا كَانَ ضَيِّقًا فَاشْدُدْهُ عَلَى حِقْوِكَ". (م,د)', 'ഉബാദത്തുബ്നുൽ വലീദ് ബ്നു ഉബാദ(റ): ജാബിറുബ്നു അബ്ദില്ല(റ) ഞങ്ങളുടെ അടുത്ത് വന്നു. അദ്ദേഹം പറഞ്ഞു: ഞാൻ നബി(സ)യോടൊപ്പം ഒരു യുദ്ധത്തിൽ സഞ്ചരിച്ചു, പ്രവാചകൻ(സ) നിസ്കരിക്കാൻ എഴുന്നേറ്റു, എന്റെയടുത്ത് ഒരു പുതപ്പ് ഉണ്ടായിരുന്നു. അതിന്റെ രണ്ട് അറ്റങ്ങൾ എതിർ ദിശയിൽ ഇടാൻ ഉദ്ദേശിച്ചു. പക്ഷെ, എനിക്കത് മതിയായില്ല. അതിന് ചെണ്ടുകൾ ഉണ്ടായിരുന്നു. ഞാനതിനെ മിറച്ചിടുകയും അതിന്റെ രണ്ടറ്റങ്ങൾ എതിർ ദിശയിലാക്കുകയും ചെയ്തു. എന്നിട്ട് അതെന്റെ കഴുത്തിലൂടെ ഇട്ടു. ശേഷം ഞാൻ ചെന്ന് പ്രവാചക(സ)ന്റെ ഇടതു ഭാഗത്ത് നിന്നു. എന്നെ കൈക്കു പിടിച്ച് ചുറ്റിച്ച് വലത് ഭാഗത്ത് നിർത്തി. അപ്പോൾ ഇബ്നുസഖ്റ്(റ) വന്ന് പ്രവാചക(സ)ന്റെ ഇടതു ഭാഗത്ത് നിന്നു. അപ്പോൾ പ്രവാചകൻ(സ) ഞങ്ങളുടെ കൈ പിടിച്ച് പിന്നിൽ നിർത്തി. ശേഷം പ്രവാചകൻ(സ) ഞാനറിയാതെ എന്നെ വീക്ഷിച്ചു. പിന്നീട് എനിക്കത് മനസ്സിലായി, വസ്ത്രത്തെ കൂട്ടി വെക്കാൻ അവിടുന്ന് ആംഗ്യം കാണിച്ചു. നമസ്കാര ശേഷം പ്രവാചകൻ(സ) വിളിച്ചു: "ജാബിർ" ഞാൻ പറഞ്ഞു: പ്രവാചകരേ, ഞാനിതാ വിളി കേട്ടു. പ്രവാചകൻ(സ) പറഞ്ഞു: "വസ്ത്രം വിശാലതയുള്ളതാണെങ്കിൽ അതിന്റെ അറ്റങ്ങൾ (പിരടികൂടെ മറയുന്ന രീതിയിൽ) വിപരീത ദിശയിൽ ഇടുക, വലിപ്പം കുറഞ്ഞതാണെങ്കിൽ നിന്റെ ധരിക്കുന്ന സ്ഥലത്ത് ഉറപ്പിക്കുക." (മു,ദ)', 'عُبَادَةَ بْنِ الْوَلِيدِ بْنِ عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദത്തുബ്നുൽ വലീദ് ബ്നു ഉബാദ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 61', array['م','د']::text[], array['മു','ദ']::text[], null, null, 729, 729, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، أَوْ قَالَ: قَالَ عُمَرُ رَضِيَ اللهُ عَنْهُ: "إِذَا كَانَ لِأَحَدِكُمْ ثَوْبَانِ فَلْيُصَلِّ فِيهِمَا، فَإِنْ لَمْ يَكُنْ إِلَّا ثَوْبٌ وَاحِدٌ فَلْيَتَّزِرْ بِهِ، وَلَا يَشْتَمِلِ اشْتِمَالَ الْيَهُودِ". (د)', 'ഇബ്നുഉമർ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങളിലാർക്കെങ്കിലും രണ്ട് വസ്ത്രങ്ങളുണ്ടെങ്കിൽ അതുമായി നിസ്കരിക്കട്ടെ, ഒറ്റ വസ്ത്രമേ ഉള്ളുവെങ്കിൽ അതിനെ ചേർത്തു കെട്ടട്ടെ. ജൂതന്മാരെ പോലെ വലിച്ചിഴക്കരുത്." (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 62', array['د']::text[], array['ദ']::text[], null, null, 729, 729, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُصَلِّيَ فِي لِحَافٍ لَا يَتَوَشَّحُ بِهِ، وَالْآخَرُ: أَنْ تُصَلِّيَ فِي سَرَاوِيلَ وَلَيْسَ عَلَيْكَ رِدَاءٌ. (د)', 'ബുറൈദ(റ): (ശരീരം) ചുറ്റിപ്പൊതിയാത്ത തരത്തിൽ ഒറ്റ വസ്ത്രത്തിൽ നിസ്കരിക്കുന്നത് നബി(സ) നിരോധിച്ചു. മറ്റൊന്ന്: മേൽവസ്ത്രമില്ലാതെ പൈജാമ മാത്രം ധരിച്ച് നീ നമസ്കരിക്കുക. (ദ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 63', array['د']::text[], array['ദ']::text[], null, null, 729, 730, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ سَعِيدِ بْنِ الْحَارِثِ قَالَ: سَأَلْنَا جَابِرَ بْنَ عَبْدِاللهِ عَنِ الصَّلَاةِ فِي الثَّوْبِ الْوَاحِدِ فَقَالَ: خَرَجْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَسْفَارِهِ، فَجِئْتُ لَيْلَةً لِبَعْضِ أَمْرِي، فَوَجَدْتُهُ يُصَلِّي، وَعَلَيَّ ثَوْبٌ وَاحِدٌ، فَاشْتَمَلْتُ بِهِ وَصَلَّيْتُ إِلَى جَانِبِهِ، فَلَمَّا انْصَرَفَ قَالَ: "مَا السُّرَى يَا جَابِرُ؟" فَأَخْبَرْتُهُ بِحَاجَتِي، فَلَمَّا فَرَغْتُ قَالَ: "مَا هَذَا الِاشْتِمَالُ الَّذِي رَأَيْتُ؟" قُلْتُ: كَانَ ثَوْبٌ يَعْنِي ضَاقَ، قَالَ: "فَإِنْ كَانَ وَاسِعًا فَالْتَحِفْ بِهِ، وَإِنْ كَانَ ضَيِّقًا فَاتَّزِرْ بِهِ". (خ)', 'സഈദുബ്നുൽ ഹാരിസ്(റ): ഞങ്ങൾ ജാബിറുബ്നു അബ്ദുല്ല(റ)യോട് ഒറ്റ വസ്ത്രമണിഞ്ഞ് നിസ്കരിക്കുന്നതിനെപ്പറ്റി ചോദിച്ചു: അദ്ദേഹം പറഞ്ഞു: ഞാൻ നബി(സ)യോടൊപ്പം ഒരു യാത്ര പോയി. രാത്രി നബി(സ)യുടെ അടുക്കലേക്ക് എന്റെ ചില ആവശ്യങ്ങൾക്കായി പോയി. അപ്പോൾ നബി(സ) നിസ്കരിക്കുകയായിരുന്നു. ഞാനാണെങ്കിൽ ഒരു വസ്ത്രം മാത്രമെ ധരിച്ചിരുന്നുള്ളൂ. ആ വസ്ത്രം ചുറ്റി ധരിച്ച് നബി(സ)യുടെ ഒരു വശത്ത് ഞാനും നിസ്കരിച്ചു. നിസ്കാരശേഷം നബി(സ) ചോദിച്ചു: "ജാബിർ! എന്താണ് കാര്യം?" അപ്പോൾ ഞാൻ എന്റെ ആവശ്യം പറഞ്ഞു. ശേഷം നബി(സ) ചോദിച്ചു: "എന്താണ് ഞാനീ കണ്ട വസ്ത്രം ചുറ്റൽ?" ഞാൻ പറഞ്ഞു: ഒരു വസ്ത്രമേ ഉണ്ടായിരുന്നുള്ളൂ. നബി(സ) പറഞ്ഞു: "എങ്കിൽ അത് വിശാലമാണെങ്കിൽ അതുകൊണ്ട് ശരീരത്തിൽ ചുറ്റിധരിക്കണം. അത് വലിപ്പം കുറവാണെങ്കിൽ അത്കൊണ്ട് അരയിലുടുക്കണം." (ബു)', 'سَعِيدِ بْنِ الْحَارِثِ قَالَ', 'സഈദുബ്നുൽ ഹാരിസ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 64', array['خ']::text[], array['ബു']::text[], null, null, 730, 730, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، قِيلَ لَهُ: أَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي نَعْلَيْهِ؟ قَالَ: نَعَمْ. حَسَنٌ صَحِيحٌ. (ق,ت,ن)', 'അനസുബ്നു മാലിക്(റ): അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: പ്രവാചകൻ(സ) ചെരിപ്പ് ധരിച്ചു കൊണ്ടായിരുന്നുവോ നിസ്കരിച്ചിരുന്നത്? അദ്ദേഹം പറഞ്ഞു: അതെ. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയണം). (ബു,മു,തു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 64', array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 730, 730, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنِ ابْنِ أَبِي أَوْسٍ قَالَ: كَانَ جَدِّي أَوْسٌ رَضِيَ اللهُ عَنْهُ أَحْيَانًا يُصَلِّي، فَيُشِيرُ إِلَيَّ وَهُوَ فِي الصَّلَاةِ، فَأُعْطِيهِ نَعْلَيْهِ، وَيَقُولُ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي نَعْلَيْهِ. (جه)', 'ഇബ്നുഅബീഔസ്(റ): എന്റെ പിതാമഹൻ ഔസ്(റ) നിസ്കരിക്കുമ്പോൾ ഇടക്ക് എന്നോട് ആംഗ്യം കാണിക്കും. അപ്പോൾ അദ്ദേഹത്തിന്റെ ചെരിപ്പ് ഞാൻ നൽകും, അദ്ദേഹം പറയും: പ്രവാചകൻ(സ) ചെരിപ്പ് ധരിച്ചു കൊണ്ട് നിസ്കരിച്ചിരുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ജ)', 'ابْنِ أَبِي أَوْسٍ قَالَ', 'ഇബ്നുഅബീഔസ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 65', array['جه']::text[], array['ജ']::text[], null, null, 730, 730, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ عَبْدِ اللهِ بنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي حَافِيًا وَمُنْتَعِلًا. (د,جه)', 'അബ്ദില്ലാഹിബ്നു അംറ്(റ): പ്രവാചകൻ(സ) ചെരിപ്പ് ധരിച്ചു കൊണ്ടും അല്ലാതെയും നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ദ,ജ)', 'عَبْدِ اللهِ بنِ عَمْرٍو', 'അബ്ദില്ലാഹിബ്നു അംറ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 66', array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 730, 730, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَقَدْ رَأَيْنَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي النَّعْلَيْنِ وَالْخُفَّيْنِ. [ز: في إسناده ضعيف] (جه)', 'അബ്ദില്ലാഹിബ്നു മസ്ഊദ്(റ): അദ്ദേഹം പറഞ്ഞു: പ്രവാചകൻ(സ) ചെരിപ്പ് ധരിച്ചും ഖുഫ്ഫ (സോക്സ്) ധരിച്ചും നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടു. (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദില്ലാഹിബ്നു മസ്ഊദ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 67', array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 730, 731, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ عَبْدِ اللهِ بْنِ السَّائِبِ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي يَوْمَ الْفَتْحِ، وَوَضَعَ نَعْلَيْهِ عَنْ يَسَارِهِ. (د,ن)', 'അബ്ദില്ലാഹിബ്നു സാഇബ്(റ): മക്കാ വിജയ ദിവസം നബി(സ) തന്റെ ചെരിപ്പുകൾ ഇടത് ഭാഗത്ത് വെച്ചുകൊണ്ട് നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടു. (ദ,ന)', 'عَبْدِ اللهِ بْنِ السَّائِبِ', 'അബ്ദില്ലാഹിബ്നു സാഇബ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 68', array['د','ن']::text[], array['ദ','ന']::text[], null, null, 731, 731, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِأَصْحَابِهِ إِذْ خَلَعَ نَعْلَيْهِ فَوَضَعَهُمَا عَنْ يَسَارِهِ، فَلَمَّا رَأَى ذَلِكَ الْقَوْمُ أَلْقَوْا نِعَالَهُمْ، فَلَمَّا قَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاتَهُ قَالَ: "مَا حَمَلَكُمْ عَلَى إِلْقَاءِ نِعَالِكُمْ". قَالُوا: رَأَيْنَاكَ أَلْقَيْتَ نَعْلَيْكَ فَأَلْقَيْنَا نِعَالَنَا، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ جِبْرِيلَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَتَانِي فَأَخْبَرَنِي أَنَّ فِيهِمَا قَذَرًا. أَوْ قَالَ: أَذًى". وَقَالَ: "إِذَا جَاءَ أَحَدُكُمْ إِلَى الْمَسْجِدِ فَلْيَنْظُرْ: فَإِنْ رَأَى فِي نَعْلَيْهِ قَذَرًا أَوْ: أَذًى فَلْيَمْسَحْهُ وَلْيُصَلِّ فِيهِمَا". وَفِي رِوَايَةٍ: "خَبَثٌ". (د)', 'അബൂസഈദുൽ ഖുദിരി(റ): നബി(സ) അനുചരരോടൊപ്പം നിസ്കരിക്കുമ്പോൾ ചെരിപ്പ് അഴിച്ച് ഇടത് ഭാഗത്ത് വെച്ചു, അതു കണ്ട് മറ്റുള്ളവരും അവരുടെ ചെരുപ്പുകൾ അഴിച്ച് വെച്ചു. നിസ്കാരം കഴിഞ്ഞപ്പോൾ നബി(സ) ചോദിച്ചു: "ചെരിപ്പുകൾ അഴിച്ചു വെക്കാൻ നിങ്ങളെ പ്രേരിപ്പിച്ചതെന്താണ്?" അവർ പറഞ്ഞു: അങ്ങ് ചെരിപ്പ് അഴിച്ച് വെക്കുന്നത് കണ്ടപ്പോൾ ഞങ്ങളും ചെരുപ്പ് അഴിച്ച് വെച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എന്റെ അടുത്ത് ജിബ്‌രീൽ(അ) വരികയും എന്റെ ചെരുപ്പിൽ മാലിന്യം ഉള്ളതായി അറിയിക്കുകയും ചെയ്തു." ശേഷം പറഞ്ഞു: "നിങ്ങളാരെങ്കിലും പള്ളിയിൽ വന്നാൽ അയാൾ ചെരിപ്പ് പരിശോധിക്കട്ടെ, അതിൽ വല്ല മാലിന്യവും ഉണ്ടായാൽ അത് നിലത്ത് ഉരസിയ ശേഷം അതുമായി നിസ്കരിച്ചു കൊള്ളട്ടെ." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദിരി(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 69', array['د']::text[], array['ദ']::text[], null, null, 731, 731, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=79), 1, 'وَفِي رِوَايَةٍ: "خَبَثٌ". (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَالِفُوا الْيَهُودَ، فَإِنَّهُمْ لَا يُصَلُّونَ فِي نِعَالِهِمْ وَلَا خِفَافِهِمْ". (د)', 'ശദ്ദാദുബ്നു ഔസ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങൾ ജൂതന്മാരോട് വിപരീതം പ്രവർത്തിക്കുക, അവർ അവരുടെ ചെരിപ്പിലും ഖുഫ്ഫയിലും നിസ്കരിക്കാറില്ല." (ദ)', 'شَدَّادِ بْنِ أَوْسٍ', 'ശദ്ദാദുബ്നു ഔസ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 70', array['د']::text[], array['ദ']::text[], null, null, 731, 731, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى فِي خَمِيصَةٍ لَهَا أَعْلَامٌ، فَنَظَرَ إِلَى أَعْلَامِهَا نَظْرَةً، فَلَمَّا انْصَرَفَ قَالَ: "اذْهَبُوا بِخَمِيصَتِي هَذِهِ إِلَى أَبِي جَهْمٍ وَأْتُونِي بِأَنْبِجَانِيَّةِ أَبِي جَهْمٍ، فَإِنَّهَا أَلْهَتْنِي آنِفًا عَنْ صَلَاتِي". (ق,ن)', 'ആഇശ(റ): നബി(സ) ചിത്രങ്ങളുള്ള ഒരു വസ്ത്രത്തിൽ നിസ്കരിച്ചു. അപ്പോൾ അതിലെ ചിത്രത്തിലേക്ക് ഒന്നു നോക്കി. നിസ്കാര ശേഷം നബി(സ) പറഞ്ഞു: "നിങ്ങൾ എന്റെ ഈ വസ്ത്രം അബൂജഹ്മിന്റെ അടുക്കൽ കൊണ്ടു പോവുക, എന്നിട്ട് അയാളുടെ കട്ടിയുള്ള രോമ വസ്ത്രം കൊണ്ടു വരിക. അത് എന്റെ നിസ്കാരത്തിൽ അശ്രദ്ധയുണ്ടാക്കി." (ബു,മു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 71', array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 731, 731, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ فِي بَيْتِي ثَوْبٌ فِيهِ تَصَاوِيرُ، فَجَعَلْتُهُ إِلَى سَهْوَةٍ فِي الْبَيْتِ، فَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي إِلَيْهِ، ثُمَّ قَالَ: "يَا عَائِشَةُ،أَخِّرِيهِ عَنِّي". فَنَزَعْتُهُ، فَجَعَلْتُهُ وَسَائِدَ. (ن)', 'ആഇശ(റ): എന്റെ വീട്ടിൽ ചിത്രങ്ങളുള്ള ഒരു വസ്ത്രമുണ്ടായിരുന്നു. അത് ഞാൻ വീടിന്റെ ഒരു മൂലയിൽ വെച്ചു. പ്രവാചകൻ(സ) അതിലേക്ക് തിരിഞ്ഞാണ് നിസ്കരിച്ചത്. പിന്നീട് പറഞ്ഞു: "ആഇശാ, ഇത് എന്റെ പിൻഭാഗത്ത് വെക്കുക." അപ്പോൾ അത് ഞാൻ ഊരിയെടുത്ത് തലയണയാക്കി. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 72', array['ن']::text[], array['ന']::text[], null, null, 731, 731, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ فِي حُلَّةٍ حَمْرَاءَ، فَرَكَزَ عَنَزَةً فَصَلَّى إِلَيْهَا، يَمُرُّ مِنْ وَرَائِهَا الْكَلْبُ وَالْمَرْأَةُ وَالْحِمَارُ. (خ,ن)', 'അബീ ജുഹൈഫ(റ): പ്രവാചകൻ(സ) ഒരു ചുവന്ന വസ്ത്രം ധരിച്ച് പുറത്തു വന്നു. എന്നിട്ട് ഒരു വടി നാട്ടി അതിലേക്ക് തിരിഞ്ഞു നിന്ന് നിസ്കരിച്ചു. അതിനു പിന്നിലൂടെ നായയും, കഴുതയും, സ്ത്രീയും നടക്കുന്നുണ്ടായിരുന്നു. (ബു,ന)', 'أَبِي جُحَيْفَةَ', 'അബീ ജുഹൈഫ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 73', array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 732, 732, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ أَبِي جُحَيْفَةَ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي قُبَّةٍ حَمْرَاءَ مِنْ أَدَمٍ، وَرَأَيْتُ بِلَالًا أَخَذَ وَضُوءَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَرَأَيْتُ النَّاسَ يَبْتَدِرُونَ ذَاكَ الْوَضُوءَ، فَمَنْ أَصَابَ مِنْهُ شَيْئًا تَمَسَّحَ بِهِ، وَمَنْ لَمْ يُصِبْ مِنْهُ شَيْئًا أَخَذَ مِنْ بَلَلِ يَدِ صَاحِبِهِ، ثُمَّ رَأَيْتُ بِلَالًا أَخَذَ عَنَزَةً فَرَكَزَهَا، وَخَرَجَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي حُلَّةٍ حَمْرَاءَ مُشَمِّرًا، صَلَّى إِلَى الْعَنَزَةِ بِالنَّاسِ رَكْعَتَيْنِ، وَرَأَيْتُ النَّاسَ وَالدَّوَابَّ يَمُرُّونَ مِنْ بَيْنِ يَدَيِ الْعَنَزَةِ. (خ)', 'അബൂജുഹൈഫ(റ): നബി(സ)യെ ചുവന്ന തോലുകൊണ്ടുള്ള വസ്ത്രം ധരിച്ചതായി ഞാൻ കണ്ടു. ബിലാൽ(റ) നബി(സ)ക്ക് വുദു ചെയ്യാനുള്ള വെള്ളം എടുത്തിരുന്നു. ജനങ്ങളെല്ലാം നബി(സ)യുടെ വുളുവിന്റെ ബാക്കി വെള്ളത്തിനായി ധൃതി കൂട്ടുന്നതും കണ്ടു. ആർക്കെങ്കിലും അതിൽ നിന്ന് അൽപം കിട്ടിയാൽ ശരീരത്തിൽ തടവും. ഒന്നും കിട്ടിയില്ലെങ്കിൽ അടുത്തയാളുടെ കയ്യിന്റെ നനവിൽ നിന്ന് എടുക്കും. പിന്നെ ബിലാൽ(റ) ഒരു വടിയെടുത്ത് നാട്ടി വെച്ചു. നബി(സ) ചുവന്ന വസ്ത്രമണിഞ്ഞ് ധൃതിയിൽ വന്നു. വടിയുടെ പിന്നിൽ നിന്ന് ജനങ്ങൾക്ക് ഇമാമായി രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. വടിയുടെ മുന്നിലൂടെ ജനങ്ങളും മൃഗങ്ങളും നടക്കുന്നത് ഞാൻ കണ്ടു. (ബു)', 'أَبِي جُحَيْفَةَ قَالَ', 'അബൂജുഹൈഫ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 74', array['خ']::text[], array['ബു']::text[], null, null, 732, 732, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَأَصَابَنَا مَطَرٌ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ شَاءَ فَلْيُصَلِّ فِي رَحْلِهِ". حَسَنٌ صَحِيحٌ. (م,د,ت)', 'ജാബിർ(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം ഒരു യാത്രയിലായിരുന്നു. അപ്പോൾ മഴ പെയ്തു. നബി(സ) പറഞ്ഞു: "വീട്ടിൽ വെച്ച് നിസ്കരിക്കാൻ ഉദ്ദേശിക്കുന്നവർ (അങ്ങിനെ) നിസ്കരിക്കട്ടെ." (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (മു,ദ,തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 75', array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 732, 732, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي حَاجَةٍ، فَجِئْتُ وَهُوَ يُصَلِّي عَلَى رَاحِلَتِهِ نَحْوَ الْمَشْرِقِ، وَالسُّجُودُ أَخْفَضُ مِنَ الرُّكُوعِ. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'ജാബിർ(റ): പ്രവാചകൻ(സ) എന്നെ ഒരാവശ്യത്തിനായി അയച്ചു. ഞാൻ തിരിച്ചു വന്നപ്പോൾ നബി(സ) കിഴക്കോട്ട് തിരിഞ്ഞ് നിസ്കരിക്കുകയായിരുന്നു. സുജൂദ് റുകൂഇനേക്കാൾ താഴ്ന്നു കൊണ്ടായിരുന്നു. (ചെയ്തിരുന്നത്) (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ബു,മു,ദ,തു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 76', array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 732, 732, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى إِلَى بَعِيرِهِ، أَوْ رَاحِلَتِهِ، وَكَانَ يُصَلِّي عَلَى رَاحِلَتِهِ حَيْثُ مَا تَوَجَّهَتْ بِهِ. حَسَنٌ صَحِيحٌ. (ق,ت,ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) തന്റെ വാഹനത്തിലേക്ക് തിരിഞ്ഞ് നിസ്കരിക്കുകയായിരുന്നു. നബി(സ) തന്റെ വാഹനപ്പുറത്ത് നിന്നും നിസ്കരിക്കാറുള്ളത് വാഹനം തിരിഞ്ഞു നിൽക്കുന്ന ഭാഗത്തേക്കാണ്. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ബു,മു,തു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 77', array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 733, 733, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي عَلَى دَابَّتِهِ، وَهُوَ مُقْبِلٌ مِنْ مَكَّةَ إِلَى الْمَدِينَةِ، وَفِيهِ أُنْزِلَتْ: { فَأَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللهِ } [بقرة: ١١٥] (ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) മക്കയിൽ നിന്ന് മദീനയിലേക്ക് തിരിഞ്ഞിരിക്കെ വാഹനപ്പുറത്ത് നിസ്കരിച്ചിരുന്നു. അപ്പോഴാണ് ''നിങ്ങൾ എങ്ങോട്ട് തിരിഞ്ഞാലും അവിടെ അല്ലാഹുവിന്റെ പ്രീതിയുണ്ട്.'' എന്ന സൂക്തം അവതരിച്ചത്. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 78', array['ن']::text[], array['ന']::text[], 'بقرة: ١١٥', null, 733, 733, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ عَبْدِ اللهِ بْنِ عَبْدِ الرَّحْمَنِ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَنَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى بِنَا فِي مَسْجِدِ بَنِي عَبْدِ الْأَشْهَلِ، فَرَأَيْتُهُ وَاضِعًا يَدَيْهِ عَلَى ثَوْبِهِ إِذَا سَجَدَ. (جه)', 'അബ്ദുല്ലാഹിബ്നു അബ്ദുർറഹ്മാൻ(റ): നബി(സ) ഞങ്ങളുടെ അടുത്ത് വന്നപ്പോൾ ബനൂ അശ്ഹലിന്റെ പള്ളിയിൽ വെച്ച് ഞങ്ങളേയും കൊണ്ട് നിസ്കരിച്ചു. അപ്പോൾ പ്രവാചകൻ(സ) വസ്ത്രത്തിൽ കൈ വെച്ച് അതിൽ സുജൂദ് ചെയ്യുന്നത് ഞാൻ കണ്ടു. (ജ)', 'عَبْدِ اللهِ بْنِ عَبْدِ الرَّحْمَنِ', 'അബ്ദുല്ലാഹിബ്നു അബ്ദുർറഹ്മാൻ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 79', array['جه']::text[], array['ജ']::text[], null, null, 733, 733, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ ثَابِتِ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى فِي بَنِي عَبْدِ الْأَشْهَلِ، وَعَلَيْهِ كِسَاءٌ مُتَلَفِّفٌ بِهِ، يَضَعُ يَدَيْهِ عَلَيْهِ، يَقِيهِ بَرْدَ الْحَصَى. [ز:في إسناده ضعيف] (جه)', 'സാബിതുബ്നു സ്വാമിത്ത്(റ): നബി(സ) ബനൂ അശ്ഹലിന്റെ പള്ളിയിൽ നിസ്കരിച്ചു. നബി(സ) ഒരു പുതപ്പ് ചുറ്റിയിരുന്നു. തണുപ്പകറ്റാൻ അവിടുന്ന് കൈ അതിൽ വെക്കാറുണ്ടായിരുന്നു. (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'ثَابِتِ بْنِ الصَّامِتِ', 'സാബിതുബ്നു സ്വാമിത്ത്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 80', array['جه']::text[], array['ജ']::text[], 'ز:في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 733, 733, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ أَنَسِ ابْنِ مَالِكٍ قَالَ: كُنَّا نُصَلِّي مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي شِدَّةِ الْحَرِّ، فَإِذَا لَمْ يَقْدِرْ أَحَدُنَا أَنْ يُمَكِّنَ جَبْهَتَهُ بَسَطَ ثَوْبَهُ فَسَجَدَ عَلَيْهِ. (ق,د,ت,جه)', 'അനസുബ്നു മാലിക്(റ): ഞങ്ങൾ കഠിനമായ ചൂടിൽ നബി(സ)യോടൊപ്പം നിസ്കരിക്കുമായിരുന്നു. ഞങ്ങളിലാർക്കെങ്കിലും നെറ്റി പതിക്കാൻ (സുജൂദ് ചെയ്യാൻ) സാധിക്കാതെ വന്നാൽ വസ്ത്രം നിലത്തു വിരിച്ച് അതിൽ സുജൂദ് ചെയ്യുമായിരുന്നു. (ബു,മു,ദ,തു,ജ)', 'أَنَسِ ابْنِ مَالِكٍ قَالَ', 'അനസുബ്നു മാലിക്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 81', array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 733, 733, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كُنَّا نُصَلِّي مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَيَضَعُ أَحَدُنَا طَرَفَ الثَّوْبِ مِنْ شِدَّةِ الْحَرِّ، فِي مَكَانِ السُّجُودِ. (خ)', 'അനസുബ്നു മാലിക്(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം നിസ്കരിക്കുമ്പോൾ ഞങ്ങളിലൊരാൾ കഠിനമായ ചൂടിനാൽ വസ്ത്രത്തിന്റെ തല സുജൂദ് ചെയ്യുന്ന സ്ഥലത്ത് വെക്കുമായിരുന്നു. (ബു)', 'أَنَسِ بْنِ مَالِكٍ قَالَ', 'അനസുബ്നു മാലിക്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 82', array['خ']::text[], array['ബു']::text[], null, null, 733, 733, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَبِي هُرَيْرَةَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا صَلَّى أَحَدُكُمْ فَلَا يَضَعْ نَعْلَيْهِ عَنْ يَمِينِهِ وَلَا عَنْ يَسَارِهِ فَتَكُونَ عَنْ يَمِينِ غَيْرِهِ إِلَّا أَنْ لَا يَكُونَ عَنْ يَسَارِهِ أَحَدٌ وَلْيَضَعْهُمَا بَيْنَ رِجْلَيْهِ". (د)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു; "നിങ്ങൾ നിസ്കരിക്കുമ്പോൾ ചെരുപ്പ് വലതു ഭാഗത്തോ ഇടതു ഭാഗത്തോ വെക്കരുത്, ഇടതു ഭാഗത്ത് വെച്ചാൽ അത് അടുത്തുള്ളവന്റെ വലതു ഭാഗത്തായിത്തീരും. അവന്റെ ഇടതു ഭാഗത്ത് ആരും ഇല്ലാതിരിക്കുമ്പോഴല്ലാതെ, ആകയാൽ അവന്റെ കാലുകൾക്കിടയിൽ വെക്കട്ടെ." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 83', array['د']::text[], array['ദ']::text[], null, null, 734, 734, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ أَبِي هُرَيْرَةَ: عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا صَلَّى أَحَدُكُمْ فَخَلَعَ نَعْلَيْهِ فَلَا يُؤْذِ بِهِمَا أَحَدًا لِيَجْعَلْهُمَا بَيْنَ رِجْلَيْهِ أَوْ لِيُصَلِّ فِيهِمَا". (د)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു; "നിങ്ങളിലൊരാൾ നിസ്കരിക്കുമ്പോൾ തന്റെ ചെരുപ്പ് മറ്റൊരാൾക്ക് ശല്ല്യമില്ലാത്ത രീതിയിൽ കാലുകൾക്കിടയിൽ അഴിച്ചു വെക്കട്ടെ. അല്ലെങ്കിൽ അത് ധരിച്ചുകൊണ്ട് നിസ്കരിക്കട്ടെ." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 84', array['د']::text[], array['ദ']::text[], null, null, 734, 734, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ مَسَّ الْحَصَى فَقَدْ لَغَا". (جه)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു; "ആരെങ്കിലും നിസ്കാരത്തിൽ മണൽ തടവി(നീക്കി)യാൽ അവൻ അനാവശ്യം പ്രവർത്തിച്ചു." (ജ)', 'أَبِي هُرَيْرَةَ قَالَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 85', array['جه']::text[], array['ജ']::text[], null, null, 734, 734, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ مُعَيْقِيبٍ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي مَسْحِ الْحَصَى فِي الصَّلَاةِ: "إِنْ كُنْتَ فَاعِلًا فَمَرَّةً وَاحِدَةً". (ق,د,ت,ن,جه)', 'മുഐഖിബ്(റ): പ്രവാചകൻ(സ) നിസ്കാരത്തിൽ മണൽ തടവുന്നതിനെ കുറിച്ച് പറഞ്ഞു; "ആരെങ്കിലും നിസ്കാരത്തിൽ മണൽ തടവുകയാണങ്കിൽ അവൻ ഒരു പ്രാവശ്യം മാത്രം ചെയ്യട്ടെ." (ബു,മു,ദ,തു,ന,ജ)', 'مُعَيْقِيبٍ قَالَ', 'മുഐഖിബ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 86', array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 734, 734, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ أَبِي ذَرٍّ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا قَامَ أَحَدُكُمْ إِلَى الصَّلَاةِ، فَإِنَّ الرَّحْمَةَ تُوَاجِهُهُ، فَلَا يَمْسَحْ بِالْحَصَى". (د,ت,ن,جه)', 'അബൂദർറ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു; "ആരെങ്കിലും നിസ്കാരത്തിന് നിന്നാൽ അവൻ കാരുണ്യത്തിലേക്ക് തിരിഞ്ഞു. അതിനാൽ അവർ മണൽ തടവരുത്." (ദ,തു,ന,ജ)', 'أَبِي ذَرٍّ قَالَ', 'അബൂദർറ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 87', array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 734, 734, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ أُمِّ سَلَمَةَ قَالَتْ: رَأَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ غُلَامًا لَنَا يُقَالُ لَهُ: أَفْلَحُ – وَفِي رِوَايَةٍ: رُبَاحٌ – إِذَا سَجَدَ نَفَخَ، فَقَالَ: "يَا أَفْلَحُ، تَرِّبْ وَجْهَكَ". (ت)', 'ഉമ്മുസലമ(റ): ഞങ്ങളുടെ അടിമയായ അഫ്ലഹ് - മറ്റൊരു റിപ്പോർട്ടിൽ: റുബാഹ് - സുജൂദിൽ മണൽ ഊതുന്നത് (ഈതി ഒഴിവാക്കുന്നത്) പ്രവാചകൻ(സ) കണ്ടപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു; "അഫ്ലഹേ, നീ മണ്ണിൽ മുഖം വെച്ച് സുജൂദ് ചെയ്യുക." (തു)', 'أُمِّ سَلَمَةَ قَالَتْ', 'ഉമ്മുസലമ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 88', array['ت']::text[], array['തു']::text[], null, null, 734, 734, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=98), 1, 'وَفِي رِوَايَةٍ: رُبَاحٌ – إِذَا سَجَدَ نَفَخَ، فَقَالَ: "يَا أَفْلَحُ، تَرِّبْ وَجْهَكَ". (ت)', 'മറ്റൊരു നിവേദനിൽ: റുബാഹ് - സുജൂദിൽ മണൽ ഊതുന്നത് (ഈതി ഒഴിവാക്കുന്നത്) പ്രവാചകൻ(സ) കണ്ടപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു; "അഫ്ലഹേ, നീ മണ്ണിൽ മുഖം വെച്ച് സുജൂദ് ചെയ്യുക." (തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَنَسِ بْنِ مَالِكٍ: كَانَ قِرَامٌ لِعَائِشَةَ سَتَرَتْ بِهِ جَانِبَ بَيْتِهَا فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَمِيطِي عَنَّا قِرَامَكِ هَذَا فَإِنَّهُ لَا تَزَالُ تَصَاوِيرُهُ تَعْرِضُ فِي صَلَاتِي". (خ)', 'അനസുബ്നു മാലിക്(റ): ആഇശ(റ)യുടെ ഒരു (ചിത്രമുള്ള) വിരി കൊണ്ട് വീടിന്റെ ഒരു ഭാഗത്ത് മറ തൂക്കിയിരുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു; "നീ നിന്റെ ഈ വിരിപ്പ് മാറ്റുക, അതിലെ ചിത്രം നിസ്കാരത്തിൽ എന്റെ മുന്നിൽ പ്രത്യക്ഷപ്പെടുന്നു." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 89', array['خ']::text[], array['ബു']::text[], null, null, 734, 734, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ أَنَّهُ قَالَ: "لَا يَقْبَلُ اللهُ صَلَاةَ حَائِضٍ إِلَّا بِخِمَارِهِ". (د,ت,جه)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു; "പ്രായപൂർത്തി എത്തിയ (ആർത്തവം ഉണ്ടായ) ഒരു സ്ത്രീയുടെ നിസ്കാരം മുഖ മക്കനെയില്ലാതെ അല്ലാഹു സ്വീകരിക്കുകയില്ല." (ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 90', array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 735, 735, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا وَقَدْ نَزَلَتْ عَلَى صَفِيَّةَ أُمِّ طَلْحَةَ، فَرَأَتْ بَنَاتٍ لَهَا، فَقَالَتْ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ فِي حُجْرَتِي جَارِيَةً، فَأَلْقَى لِي حِقْوَهُ وَقَالَ لِي: "شُقِّيهِ بِشِقَّيْنِ. فَأَعْطِي هَذِهِ نِصْفًا وَالْفَتَاةَ الَّتِي عِنْدَ أُمِّ سَلَمَةَ نِصْفًا، فَإِنِّي لَا أُرَاهَا إِلَّا قَدْ حَاضَتْ، أَوْ: لَا أُرَاهُمَا إِلَّا قَدْ حَاضَتَا". (د)', 'ആഇശ(റ): മഹതി സ്വഫിയ്യ ഉമ്മുത്വൽഹയുടെ അടുത്ത് ചെന്നപ്പോൾ അവരുടെ പെൺമക്കളെ കണ്ടു. അപ്പോൾ പറഞ്ഞു: എന്റെ അടുത്ത് ചെറിയ ഒരു പെൺകുട്ടി ഉള്ളപ്പോൾ നബി(സ) എന്റെ അടുത്ത് വന്നു. അവിടുന്ന് തന്റെ വിരി ഇട്ടു തന്നു കൊണ്ട് പറഞ്ഞു: "അത് രണ്ടായി മുറിക്കുക, ഇവൾക്ക് പകുതി കൊടുക്കുക, ഉമ്മുസലമയുടെ അടുത്തുള്ളവൾക്ക് പകുതി കൊടുക്കുക. അവൾക്ക് പ്രായപൂർത്തിയായതായി ഞാൻ കാണുന്നു. അല്ലെങ്കിൽ അവർക്ക് രണ്ടുപേർക്കും പ്രായപൂർത്തിയായതായി ഞാൻ കാണുന്നു." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 91', array['د']::text[], array['ദ']::text[], null, null, 735, 735, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ السَّدْلِ فِي الصَّلَاةِ، وَأَنْ يُغَطِّيَ الرَّجُلُ فَاهُ. (د,ت,جه)', 'അബൂഹുറൈറ(റ): നിസ്കാരത്തിൽ വസ്ത്രം വലിച്ചിഴക്കുന്നതും, ഒരാൾ തന്റെ വായ മൂടുന്നതും പ്രവാചകൻ(സ) വിരോധിച്ചു. (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 92', array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 735, 735, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنِ ابْنِ جُرَيْجٍ قَالَ: أَكْثَرُ مَا رَأَيْتُ عَطَاءً يُصَلِّي سَادِلًا. (د)', 'ഇബ്നുജുറൈജ്(റ): അദ്ദേഹം പറഞ്ഞു: നിസ്കാരത്തിൽ വസ്ത്രം നിലത്തിഴക്കുന്നതായാണ് അത്വാഇനെ ഞാൻ മിക്കപ്പോഴും കാണാറുള്ളത്. (ദ)', 'ابْنِ جُرَيْجٍ قَالَ', 'ഇബ്നുജുറൈജ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 93', array['د']::text[], array['ദ']::text[], null, null, 735, 735, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا يُصَلِّي فِي شُعُرِنَا، أَوْ: فِي لُحُفِنَا. (د)', 'ആഇശ(റ): പ്രവാചകൻ(സ) ഞങ്ങളുടെ ശരീരത്തിൽ ചേർന്നു കിടക്കുന്ന വസ്ത്രത്തിൽ നിസ്കരിക്കാറുണ്ടായിരുന്നില്ല. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 94', array['د']::text[], array['ദ']::text[], null, null, 735, 735, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ سَأَلَ أُخْتَهُ أُمَّ حَبِيبَةَ رَضِيَ اللهُ عَنْهَا، زَوْجَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: هَلْ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي الثَّوْبِ الَّذِي يُجَامِعُ فِيهِ؟ قَالَتْ: نَعَمْ، إِذَا لَمْ يَكُنْ فِيهِ أَذًى. (د,ن,جه)', 'മുആവിയതുബ്നു അബൂസുഫ്യാൻ(റ): അദ്ദേഹം പ്രവാചക പത്നിയും തന്റെ സഹോദരിയുമായ ഉമ്മുഹബീബ(റ)യോട് ചോദിച്ചു: നബി(സ) സംഭോഗം ചെയ്ത അതേ വസ്ത്രം ധരിച്ച് നിസ്കരിക്കാറുണ്ടായിരുന്നോ? അവർ പറഞ്ഞു: അതെ, അതിൽ വൃത്തികേടുകളില്ലെങ്കിൽ. (ദ,ന,ജ)', 'مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ', 'മുആവിയതുബ്നു അബൂസുഫ്യാൻ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 95', array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 735, 736, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَرَأْسُهُ يَقْطُرُ مَاءً، فَصَلَّى بِنَا فِي ثَوْبٍ وَاحِدٍ، مُتَوَشِّحًا بِهِ، قَدْ خَالَفَ بَيْنَ طَرَفَيْهِ، فَلَمَّا انْصَرَفَ قَالَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ: يَا رَسُولَ اللهِ، تُصَلِّي بِنَا فِي ثَوْبٍ وَاحِدٍ؟ قَالَ: "نَعَمْ، أُصَلِّي فِيهِ، وَفِيهِ أَيْ قَدْ جَامَعْتُ فِيهِ". [ز: في إسناده ضعيف] (جه)', 'അബൂദർറ്(റ): തലയിൽ നിന്നും വെള്ളത്തുള്ളികൾ ഉറ്റിവീഴുന്ന നിലയിൽ നബി(സ) ഞങ്ങളിലേക്കു വന്നു. അങ്ങനെ ഒറ്റ വസ്ത്രത്താൽ ചുറ്റപ്പെട്ട്, ഇരുഭാഗത്തും വസ്ത്രം വിരിച്ചിട്ടുകൊണ്ട് നബി(സ) നിസ്കരിച്ചു. നിസ്കാര ശേഷം ഉമർ(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരെ, ഒരൊറ്റ വസ്ത്രം ധരിച്ചാണോ അങ്ങ് ഞങ്ങൾക്കിമാമായി നിസ്കരിച്ചത്? നബി(സ) പറഞ്ഞു: "അതെ, ആ വസ്ത്രം ധരിച്ച് ഞാൻ നിസ്കരിക്കുന്നു, അഥവാ ഞാൻ സംഭോഗം ചെയ്ത വസ്ത്രം ധരിച്ച്." (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്വലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أَبِي الدَّرْدَاءِ', 'അബൂദർറ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 96', array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 736, 736, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلَ رَجُلٌ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: يُصَلِّي فِي الثَّوْبِ الَّذِي يَأْتِي فِيهِ أَهْلَهُ؟ قَالَ: "نَعَمْ، إِلَّا أَنْ يَرَى فِيهِ شَيْئًا فَيَغْسِلَهُ". (جه)', 'ജാബിറുബ്നു സമുറ(റ): ഒരാൾ നബി(സ)യോട് ചോദിച്ചു: തന്റെ ഭാര്യയുമായി ബന്ധപ്പെട്ട വസ്ത്രത്തിൽ നിസ്കരിക്കാമോ? നബി(സ) പറഞ്ഞു: "അതെ, അതിലൊന്നും (മ്ലേച്ഛത) കണ്ടില്ലെങ്കിൽ. കണ്ടാൽ അത് കഴുകണം." (ജ)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 97', array['جه']::text[], array['ജ']::text[], null, null, 736, 736, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ سَعِيدٍ الْمَقْبُرِيِّ: أَنَّهُ رَأَى أَبَا رَافِعٍ مَوْلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِحَسَنِ بْنِ عَلِيٍّ عَلَيْهِمَا السَّلَامُ وَهُوَ يُصَلِّي قَائِمًا، وَقَدْ غَرَزَ ضَفْرَهُ فِي قَفَاهُ، فَحَلَّهَا أَبُو رَافِعٍ، فَالْتَفَتَ حَسَنٌ إِلَيْهِ مُغْضَبًا، فَقَالَ أَبُو رَافِعٍ: أَقْبِلْ عَلَى صَلَاتِكَ وَلَا تَغْضَبْ. فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "ذَلِكَ كِفْلُ الشَّيْطَانِ" يَعْنِي مَقْعَدَ الشَّيْطَانِ يَعْنِي مَغْرِزَ ضَفْرِهِ. (د,ت,جه)', 'അബൂസഈദുൽ മഖ്ബുരി(റ): ഹസനു ബ്നു അലി(റ) നിസ്കരിക്കുമ്പോൾ അബൂറാഫിഅ് സമീപത്തുകൂടെ നടക്കുന്നത് അദ്ദേഹം കണ്ടു. ഹസൻ(റ)വിന്റെ മുടി പിരടിയിലേക്ക് മടക്കി മെടഞ്ഞിട്ടുണ്ട്. അബൂറാഫിഅ് അത് അഴിച്ചു. ഹസൻ(റ) ദേഷ്യത്തോടെ നോക്കി, അപ്പോൾ അബൂറാഫിഅ് പറഞ്ഞു: ദേഷ്യപ്പെടാതെ നിസ്കാരം തുടർന്നോളൂ, "അത് (മുടി കെട്ടി വെക്കുന്ന സ്ഥലം) പിശാചിന്റെ ഇരിപ്പിടമാണെ"ന്ന് പ്രവാചകൻ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. (ദ,തു,ജ)', 'سَعِيدٍ الْمَقْبُرِيِّ', 'അബൂസഈദുൽ മഖ്ബുരി(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 98', array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 736, 736, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، وَقَدْ رَأَى عَبْدَ اللهِ بْنَ الْحَارِثِ يُصَلِّي وَرَأْسُهُ مَعْقُوصٌ مِنْ وَرَائِهِ، فَقَامَ وَرَاءَهُ فَجَعَلَ يَحُلُّهُ وَأَقَرَّ لَهُ الْآخَرُ، فَلَمَّا انْصَرَفَ أَقْبَلَ إِلَى ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا فَقَالَ: مَا لَكَ وَرَأْسِي؟ قَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّمَا مَثَلُ هَذَا مَثَلُ الَّذِي يُصَلِّي وَهُوَ مَكْتُوفٌ". (م,د,ن)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): അബ്ദുല്ലാഹിബ്നു ഹാരിസ്(റ) മുടി പിന്നിൽ നിന്ന് മെടഞ്ഞിട്ട് നിസ്കരിക്കുന്നത് അദ്ദേഹം കണ്ടു. അദ്ദേഹം പിന്നിൽ ചെന്ന് (മുടി) അഴിച്ചിട്ടു. മറ്റൊരാൾ അത് അംഗീകരിച്ചു. നിസ്കാര ശേഷം അബ്ദുല്ലാഹിബ്നു അബ്ബാസി(റ)നു നേരെ തിരിഞ്ഞ് അദ്ദേഹം ചോദിച്ചു: എന്റെ തല യിൽ താങ്കൾക്കെന്തു കാര്യം? അദ്ദേഹം പറഞ്ഞു: "ഇങ്ങനെ നിസ്കരക്കുന്നത് കൈ പിന്നിൽ കെട്ടി നിസ്കരിക്കുന്നതിന് തുല്യമാണെ"ന്ന് പ്രവാചകൻ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. (മു,ദ,ന)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 99', array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 736, 737, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أُمِرْتُ أَنْ لَا أَكُفَّ شَعَرًا وَلَا ثَوْبًا". (ن,جه)', 'ഇബ്നുഅബ്വാസ്(റ): നബി(സ) പറഞ്ഞു: "എന്റെ വസ്ത്രവും മുടിയും ഒതുക്കി പിടിക്കാതിരിക്കാൻ ഞാൻ കൽപ്പിക്കപ്പെട്ടു." (ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്വാസ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 100', array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 737, 737, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: أُمِرْنَا أَلَّا نَكُفَّ شَعَرًا وَلَا ثَوْبًا وَلَا نَتَوَضَّأَ مِنْ مَوْطِإٍ. (د,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): വസ്ത്രവും മുടിയും ഒതുക്കി പിടിക്കാതിരിക്കാനും, മേച്ചിൽ സ്ഥലത്ത് നിന്ന് വുദു ചെയ്യാതിരിക്കാനും ഞങ്ങൾ കൽപിക്കപ്പെട്ടു. (ദ,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 101', array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 737, 737, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ أَبِي رَافِعٍ رَضِيَ اللهُ عَنْهُ مَوْلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى الْحَسَنَ بْنَ عَلِيٍّ وَهُوَ يُصَلِّي، وَقَدْ عَقَصَ شَعْرَهُ، فَأَطْلَقَهُ، أَوْ: نَهَى عَنْهُ، وَقَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُصَلِّيَ الرَّجُلُ وَهُوَ عَاقِصٌ شَعْرَهُ. (جه)', 'റസൂലി(സ)ന്റെ മൗലയായ അബൂറാഫിഅ്: ഹസനുബ്നു അലി(റ) തന്റെ മുടി ഉള്ളിലേക്ക് കെട്ടി നിസ്കരിക്കുന്നത് അദ്ദേഹം കണ്ടു. അബൂറാഫിഅ് കെട്ടഴിച്ചു. അല്ലെങ്കിൽ: അതിനെ തടഞ്ഞു. എന്നിട്ട് പറഞ്ഞു: പുരുഷൻ തന്റെ മുടി പിന്നിലേക്ക് കെട്ടി നിസ്കരിക്കുന്നത് നബി(സ) വിരോധിച്ചിരിക്കുന്നു. (ജ)', 'أَبِي رَافِعٍ', null, null, 'അച്ചടിയിലെ നമ്പർ: 102', array['جه']::text[], array['ജ']::text[], null, null, 737, 737, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ حَازِمِ بْنِ دِينَارٍ: أَنَّ رِجَالًا أَتَوْا سَهْلَ بْنَ سَعْدٍ السَّاعِدِيَّ رَضِيَ اللهُ عَنْهُ وَقَدِ امْتَرَوْا فِي الْمِنْبَرِ: مِمَّ عُودُهُ فَسَأَلُوهُ عَنْ ذَلِكَ؟ فَقَالَ: وَاللهِ إِنِّي لَأَعْرِفُ مِمَّا هُوَ، وَلَقَدْ رَأَيْتُهُ أَوَّلَ يَوْمٍ وُضِعَ، وَأَوَّلَ يَوْمٍ جَلَسَ عَلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَرْسَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى فُلَانَةَ، امْرَأَةٍ مِنَ الْأَنْصَارِ قَدْ سَمَّاهَا سَهْلٌ: "أَنْ مُرِي غُلَامَكِ النَّجَّارَ أَنْ يَعْمَلَ لِي أَعْوَادًا، أَجْلِسُ عَلَيْهِنَّ إِذَا كَلَّمْتُ النَّاسَ". فَأَمَرْتُهُ فَعَمِلَهَا مِنْ طَرْفَاءِ الْغَابَةِ، ثُمَّ جَاءَ بِهَا، فَأَرْسَلَتْ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَ بِهَا فَوُضِعَتْ هَهُنَا ثُمَّ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَقِيَ فَصَلَّى عَلَيْهَا وَكَبَّرَ وَهُوَ عَلَيْهَا، ثُمَّ رَكَعَ وَهُوَ عَلَيْهَا، ثُمَّ نَزَلَ الْقَهْقَرَى فَسَجَدَ فِي أَصْلِ الْمِنْبَرِ، ثُمَّ عَادَ، فَلَمَّا فَرَغَ أَقْبَلَ عَلَى النَّاسِ فَقَالَ: "أَيُّهَا النَّاسُ، إِنَّمَا صَنَعْتُ هَذَا لِتَأْتَمُّوا وَلِتَعَلَّمُوا صَلَاتِي". (خ,ن)', 'ഹാസിമുബ്നു ദീനാർ(റ): സഹ്ലുബ്നു സഅദുസ്സാഇദി(റ)യുടെ അടുത്ത് ഏതാനും പേർ വന്നു. മിമ്പർ (പ്രസംഗ പീഠം) എന്തിനാൽ നിർമ്മിച്ചു എന്ന കാര്യത്തിൽ അവർ തർക്കത്തിലായിരുന്നു. അവർ അദ്ദേഹത്തോട് അതിനെ കുറിച്ച് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവാണെ, അത് എന്തിനാൽ നിർമ്മിച്ചതാണെന്ന് തീർച്ചയായും എനിക്കറിയാം. അത് സ്ഥാപിച്ച ദിവസം തന്നെ ഞാനത് കണ്ടിട്ടുണ്ട്, റസൂൽ(സ) അതിൽ ആദ്യം ഇരുന്ന ദിവസം തന്നെ ഞാനത് കണ്ടിട്ടുണ്ട്. ഒരു അൻസ്വാരി സ്ത്രീയുടെ - അവളുടെ പേര് സഹ്ൽ(റ) പറഞ്ഞിരുന്നു - അടുത്തേക്ക് പ്രവാചകൻ(സ) ആളെ അയച്ചുകൊണ്ട് പറഞ്ഞു: "ജനങ്ങളോട് സംസാരിക്കുമ്പോൾ എനിക്ക് ഇരിക്കുവാൻവേണ്ടി എനിക്ക് ഒരു മരപ്പടി (മിമ്പർ) ഉണ്ടാക്കിത്തരാൻ നീ നിന്റെ ആശാരിയായ അടിമയോട് കൽപ്പിക്കണം." അവൾ പറഞ്ഞ പ്രകാരം അവൻ (അടിമ) അത് നിർമ്മിച്ചു. കാട്ടിലെ ത്വർഫാ മരം കൊണ്ടാണത് (മിമ്പർ) നിർമ്മിച്ചത്. ശേഷം അത് റസൂലിന്റെ അടുത്തേക്ക് കൊടുത്തയച്ചു. അതിനെ റസൂൽ(സ) സ്ഥാപിക്കാൻ നിർദ്ദേശിച്ചിടത്ത് സ്ഥാപിച്ചു. പിന്നീട് റസൂൽ അതിന്റെ മുകളിൽ നിന്ന് നമസ്കരിക്കുന്നത് ഞാൻ കണ്ടു. അതിൽ നിന്നുകൊണ്ട് തകബീർ ചൊല്ലി, റുകൂഅ് നിർവ്വഹിച്ചു. പിന്നീട് ഇറങ്ങി വന്ന് മിമ്പറിന്റെ ചുവട്ടിൽ സുജൂദ് ചെയ്തു. തിരിച്ചു ചെന്ന് ജനങ്ങളെ അഭിമുഖീകരിച്ച് പറഞ്ഞു: "ജനങ്ങളേ, ഞാൻ ഇത് ചെയ്തത് നിങ്ങൾ എന്നോട് തുടരാനും എന്റെ നിസ്കാരം നിങ്ങൾ പഠിക്കാനുമാണ്." (ബു,ന)', 'حَازِمِ بْنِ دِينَارٍ', 'ഹാസിമുബ്നു ദീനാർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 103', array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 737, 738, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ يُصَلِّي عِنْدَ الْأُسْطُوَانَةِ الَّتِي عِنْدَ الْمُصْحَفِ، فَقِيلَ لَهُ: يَا أَبَا مُسْلِمٍ أَرَاكَ تَتَحَرَّى الصَّلَاةَ عِنْدَ هَذِهِ الْأُسْطُوَانَةِ؟ قَالَ: فَإِنِّي رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَحَرَّى الصَّلَاةَ عِنْدَهَا. (خ)', 'സലമത്ത്(റ) പറയുന്നു: മുസ്ഹഫ് സൂക്ഷിച്ച പെട്ടിയുടെ അടുത്തുള്ള തൂണിന്റെ മുമ്പിൽ നിന്നുകൊണ്ട് അദ്ദേഹം നിസ്കരിക്കാറുണ്ടായിരുന്നു. ചിലർ അദ്ദേഹത്തോട് ചോദിച്ചു. അബൂമുസ്ലിം! നിങ്ങൾ ഈ തൂണിനടുത്തുനിന്ന് നിസ്കരിക്കാൻ ശ്രദ്ധിക്കുന്നുണ്ടല്ലോ. (എന്താണിതിന് കാരണം?) അദ്ദേഹം പറഞ്ഞു: തിരുമേനി(സ) ഈ തൂണിന്നടുത്തു നിന്ന് നിസ്കരിക്കാൻ പ്രത്യേകം ശ്രദ്ധിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ബു)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമത്ത്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 104', array['خ']::text[], array['ബു']::text[], null, null, 738, 738, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ عَبْدِ اللهِ بْنِ الشِّخِّيرِ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، فَبَزَقَ تَحْتَ الْيُسْرَى قَدَمِهِ. وَفِي رِوَايَةٍ: ثُمَّ دَلَكَهَا بِنَعْلِهِ. (د)', 'അബ്ദുല്ലാഹിബ്നു ശിഖീർ(റ): റസൂൽ(സ) നിസ്കരിക്കുമ്പോൾ ഞാൻ കണ്ടിട്ടുണ്ട്. പ്രവാചകൻ(സ) ഇടത് കാൽ ചുവട്ടിലാണ് തുപ്പിയിരുന്നത്. മറ്റൊരു റിപ്പോർട്ട്: പിന്നീട് അത് ചെരുപ്പു കൊണ്ട് ഉരച്ചു കളയും. (ദ)', 'عَبْدِ اللهِ بْنِ الشِّخِّيرِ', 'അബ്ദുല്ലാഹിബ്നു ശിഖീർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 105', array['د']::text[], array['ദ']::text[], null, null, 738, 738, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=115), 1, 'وَفِي رِوَايَةٍ: ثُمَّ دَلَكَهَا بِنَعْلِهِ. (د)', 'മറ്റൊരു നിവേദന്: പിന്നീട് അത് ചെരുപ്പു കൊണ്ട് ഉരച്ചു കളയും. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ وَاثِلَةَ بْنَ الْأَسْقَعِ فِي مَسْجِدِ دِمَشْقَ بَصَقَ عَلَى الْبُورِيِّ ثُمَّ مَسَحَهُ بِرِجْلِهِ، فَقِيلَ لَهُ: لِمَ فَعَلْتَ هَذَا؟ قَالَ: "لِأَنِّي رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُهُ". (د)', 'അബൂസഈദ്(റ): വാസിലത്തുബ്നുൽ അസ്ഖഅ്(റ) ദമസ്കസിലെ പള്ളിയിൽ നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടു, അദ്ദേഹം പായയിലേക്ക് തുപ്പി. പിന്നീട് തന്റെ കാലു കൊണ്ട് ഉരച്ചു. എന്തു കൊണ്ടാണ് അപ്രകാരം ചെയ്തതെന്ന് ചോദിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) അപ്രകാരം ചെയ്യുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ദ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 106', array['د']::text[], array['ദ']::text[], null, null, 738, 738, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَانَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي مَسْجِدِنَا هَذَا وَفِي يَدِهِ عُرْجُونُ ابْنِ طَابٍ، فَنَظَرَ فَرَأَى فِي قِبْلَةِ الْمَسْجِدِ نُخَامَةً، فَأَقْبَلَ عَلَيْهَا فَحَتَّهَا بِالْعُرْجُونِ، ثُمَّ قَالَ: "أَيُّكُمْ يُحِبُّ أَنْ يُعْرِضَ اللهُ عَنْهُ بِوَجْهِهِ". ثُمَّ قَالَ: "إِنَّ أَحَدَكُمْ إِذَا قَامَ يُصَلِّي فَإِنَّ اللهَ قِبَلَ وَجْهِهِ، فَلَا يَبْصُقَنَّ قِبَلَ وَجْهِهِ وَلَا عَنْ يَمِينِهِ، وَلْيَبْزُقْ عَنْ يَسَارِهِ تَحْتَ رِجْلِهِ الْيُسْرَى، فَإِنْ عَجِلَتْ بِهِ بَادِرَةٌ فَلْيَقُلْ بِثَوْبِهِ هَكَذَا". وَوَضَعَهُ عَلَى فِيهِ ثُمَّ دَلَكَهُ، ثُمَّ قَالَ: "أَرُونِي عَبِيرًا". فَقَامَ فَتًى مِنَ الْحَيِّ يَشْتَدُّ إِلَى أَهْلِهِ فَجَاءَ بِخَلُوقٍ فِي رَاحَتِهِ، فَأَخَذَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَجَعَلَهُ عَلَى رَأْسِ الْعُرْجُونِ، ثُمَّ لَطَخَ بِهِ عَلَى أَثَرِ النُّخَامَةِ. قَالَ جَابِرٌ: فَمِنْ هُنَاكَ جَعَلْتُمُ الْخَلُوقَ فِي مَسَاجِدِكُمْ. (د)', 'ജാബിർ(റ): പ്രവാചകൻ(സ) ഞങ്ങളുടെ ഈ പള്ളിയിൽ വന്നു. അവിടുത്തെ കയ്യിൽ ഉണങ്ങിയ പനയോലയുണ്ട്. ഖിബ്ലയുടെ ഭാഗത്ത് കഫം റസൂൽ(സ)യുടെ ശ്രദ്ധയിൽ പെട്ടു. അവിടേക്ക് ചെന്ന് ഈന്തപ്പന വടികൊണ്ട് അത് നീക്കി. പിന്നെ ചോദിച്ചു:"നിങ്ങളിലാരാണ് തന്നിൽനിന്നും അല്ലാഹു അവന്റെ വജ്ഹിനെ തിരിച്ചു കളയണമെന്ന് ആഗ്രഹിക്കുന്നത്?" പിന്നീട് പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും നിസ്കരിക്കാൻ നിന്നാൽ നിശ്ചയം, അല്ലാഹു അവന്റെ മുന്നിലുണ്ട്. അതുകൊണ്ടു തന്നെ മുൻ ഭാഗത്തേക്കോ, വലത്തോട്ടോ തുപ്പരുത്. ഇടത് കാലിന്നടിയിലേക്ക് തുപ്പട്ടെ. ആർക്കെങ്കിലും അതിന്ന് പ്രയാസം തോന്നിയാൽ അവന്റെ വസ്ത്രമുപയോഗിച്ച് ഇങ്ങനെ ചെയ്യട്ടെ", റസൂൽ(സ) തന്റെ വായയുടെമേൽ വസ്ത്രം വെച്ച് അതിനെ ഉരസിയ ശേഷം പറഞ്ഞു: "കുറച്ച് സുഗന്ധം കൊണ്ടു വരൂ" അപ്പോൾ ഒരു യുവാവ് വീട്ടിലേക്ക് ഓടി, തന്റെ ഉള്ളൻ കയ്യിൽ സുഗന്ധവുമായി വന്നു. അത് റസൂൽ(സ) ഈത്തപ്പന വടിയുടെ അറ്റത്ത് പുരട്ടി കഫത്തിന്റെ അടയാളമുള്ളിടത്ത് തേച്ചു. ജാബിർ(റ) പറഞ്ഞു: അന്നുമുതലാണ് പള്ളിയിൽ സുഗന്ധമുപയോഗിക്കാൻ തുടങ്ങിയത്. (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 107', array['د']::text[], array['ദ']::text[], null, null, 738, 739, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ يَوْمًا إِذْ رَأَى نُخَامَةً فِي قِبْلَةِ الْمَسْجِدِ، فَتَغَيَّظَ عَلَى النَّاسِ ثُمَّ حَكَّهَا، فَدَعَا بِزَعْفَرَانٍ فَلَطَّخَهُ بِهِ، وَقَالَ: "إِنَّ اللهَ قِبَلَ وَجْهِ أَحَدِكُمْ إِذَا صَلَّى فَلَا يَبْزُقْ بَيْنَ يَدَيْهِ". (ق,د)', 'ഇബ്നു ഉമർ(റ): ഒരിക്കൽ പ്രവാചകൻ(സ) ഖുതുബ നിർവ്വഹിക്കുന്നതിനിടയിൽ പള്ളിയുടെ ഖിബ്ലയുടെ ഭാഗത്ത് കഫം കാണാനിടയായി. പ്രവാചകൻ(സ) ജനങ്ങളോട് ദേഷ്യപ്പെട്ടു. പിന്നീടത് നീക്കം ചെയ്തു. ശേഷം കുങ്കുമം കൊണ്ടു വരാൻ ആവശ്യപ്പെട്ടു, മറ്റൊരു റിപ്പോർട്ടിൽ: അവിടെയത് തെളിച്ചു. ശേഷം പറഞ്ഞു: "നിശ്ചയം, നിങ്ങൾ നിസ്കരിക്കുമ്പോൾ നിങ്ങളുടെ മുൻ ഭാഗത്ത് അല്ലാഹുവുണ്ട്. അത് കൊണ്ട് മുന്നിലേക്ക് തുപ്പരുത്." (ബു,മു,ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 108', array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 739, 739, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=118), 1, null, 'മറ്റൊരു നിവേദനിൽ: അവിടെയത് തെളിച്ചു. ശേഷം പറഞ്ഞു: "നിശ്ചയം, നിങ്ങൾ നിസ്കരിക്കുമ്പോൾ നിങ്ങളുടെ മുൻ ഭാഗത്ത് അല്ലാഹുവുണ്ട്. അത് കൊണ്ട് മുന്നിലേക്ക് തുപ്പരുത്." (ബു,മു,ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُحِبُّ الْعَرَاجِينَ وَلَا يَزَالُ فِي يَدِهِ مِنْهَا، فَدَخَلَ الْمَسْجِدَ فَرَأَى نُخَامَةً فِي قِبْلَةِ الْمَسْجِدِ، فَحَكَّهَا، ثُمَّ أَقْبَلَ عَلَى النَّاسِ مُغْضَبًا فَقَالَ: "أَيَسُرُّ أَحَدَكُمْ أَنْ يُبْصَقَ فِي وَجْهِهِ؟ إِنَّ أَحَدَكُمْ إِذَا اسْتَقْبَلَ الْقِبْلَةَ فَإِنَّمَا يَسْتَقْبِلُ رَبَّهُ عَزَّ وَجَلَّ، وَالْمَلَكُ عَنْ يَمِينِهِ، فَلَا يَتْفُلْ عَنْ يَمِينِهِ وَلَا فِي قِبْلَتِهِ، وَلْيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ، فَإِنْ عَجِلَ بِهِ أَمْرٌ فَلْيَقُلْ هَكَذَا". وَوَصَفَ ذَلِكَ: أَنْ يَتْفُلَ فِي ثَوْبِهِ ثُمَّ يَرُدَّ بَعْضَهُ عَلَى بَعْضٍ. (ق,د)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) ഉണക്ക ഈത്തപ്പനയോല ഇഷ്ടപ്പെട്ടിരുന്നു. അവിടുത്തെ കയ്യിലത് ഉണ്ടാകാറുമുണ്ട്. ഒരിക്കൽ നബി(സ) പള്ളിയിൽ പ്രവേശിച്ചു അപ്പോൾ പള്ളിയുടെ ഖിബ്ലയുടെ ഭാഗത്ത് കഫം കണ്ടു. അത് ഉരച്ച് കളഞ്ഞ് ജനങ്ങളെ നോക്കി പറഞ്ഞു: "നിങ്ങളിലൊരാളുടെ മുഖത്ത് തുപ്പുന്നത് നിങ്ങൾ ഇഷ്ടപ്പെടുമോ? നിങ്ങളിലൊരാൾ ഖിബ്ലക്ക് നേരെ തിരിയുമ്പോൾ അല്ലാഹുവിന്റെ നേരെയാണ് തിരിയുന്നത്, അവന്റെ വലത് ഭാഗത്ത് മലക്കുകളുമുണ്ട്. അതിനാൽ ഖിബ്ല യുടെ ഭാഗത്തേക്കും, വലത് ഭാഗത്തേക്കും തുപ്പരുത്. ഇടത് ഭാഗത്തേക്കോ കാൽ ചുവട്ടിലേക്കോ തുപ്പട്ടെ. ഇനി അതിന് തടസ്സമുണ്ടെങ്കിൽ ഇപ്രകാരം ചെയ്തുകൊള്ളട്ടെ." നബി(സ) അത് കാണിച്ചു തന്നു: വസ്ത്രത്തിൽ തുപ്പിയിട്ട് വസ്ത്രം പരസ്പരം ഉരക്കുക. (ബു,മു,ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 109', array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 739, 739, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ أَبِي سَهْلَةَ السَّائِبِ بْنِ خَلَّادٍ رَضِيَ اللهُ عَنْهُ، مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَجُلًا أَمَّ قَوْمًا، فَبَصَقَ فِي الْقِبْلَةِ، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْظُرُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ فَرَغَ: "لَا يُصَلِّي لَكُمْ". فَأَرَادَ بَعْدَ ذَلِكَ أَنْ يُصَلِّيَ لَهُمْ فَمَنَعُوهُ. وَأَخْبَرُوهُ بِقَوْلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ ذَلِكَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "نَعَمْ". وَحَسِبْتُ أَنَّهُ قَالَ: "إِنَّكَ آذَيْتَ اللهَ وَرَسُولَهُ". (د)', 'അബുസഹ്ലത്തു സാഇബുബ്നു ഖല്ലാദ്(റ): നബി(സ)യുടെ സ്വഹാബികളിൽ ഒരാൾ ജനങ്ങൾക്ക് ഇമാമാവുകയും ഖിബ്ലഭാഗത്തേക്ക് തുപ്പുകയും ചെയ്തു. റസൂൽ(സ) അത് കണ്ടു, നിസ്കാര ശേഷം പ്രവാചകൻ(സ) പറഞ്ഞു: "അയാൾ നിങ്ങൾക്ക് (ഇമാമായി) നിസ്കരിക്കരുത്." പിന്നീടദ്ദേഹം അവർക്ക് ഇമാമായി നിസ്കരിക്കാനുദ്ദേശിച്ചു. എന്നാൽ ജനങ്ങൾ അത് തടയുകയും അവർ നബി(സ)യുടെ വാക്ക് അദ്ദേഹത്തോട് പറയുകയും ചെയ്തു. അയാളിക്കാര്യം നബി(സ)യോട് പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "അതെ." അവിടുന്ന് ഇപ്രകാരം പറഞ്ഞുവെന്നാണ് ഞാൻ കരുതുന്നത്: "നീ അല്ലാഹുവിനേയും റസൂലിനേയും വേദനിപ്പിച്ചു." (ദ)', 'أَبِي سَهْلَةَ السَّائِبِ بْنِ خَلَّادٍ', 'അബുസഹ്ലത്തു സാഇബുബ്നു ഖല്ലാദ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 110', array['د']::text[], array['ദ']::text[], null, null, 740, 740, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ طَارِقِ بْنِ عَبْدِ اللهِ الْمُحَارِبِيِّ رَضِيَ اللهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا قَامَ الرَّجُلُ إِلَى الصَّلَاةِ – أَوْ إِذَا صَلَّى أَحَدُكُمْ – فَلَا يَبْزُقْ أَمَامَهُ، وَلَا عَنْ يَمِينِهِ، وَلَكِنْ عَنْ تِلْقَاءِ يَسَارِهِ إِنْ كَانَ فَارِغًا، أَوْ تَحْتَ قَدَمِهِ الْيُسْرَى، ثُمَّ لِيَقُلْ بِهِ". (د,ت,ن,جه)', 'ത്വാരികിബ്നു അബ്ദുല്ലാഹിൽ മുഹാറബീ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ നിസ്കാരത്തിന്നായി നിന്നാൽ മുൻവശത്തേക്കോ, വലത് വശത്തേക്കോ തുപ്പരുത്, ആരുമില്ലെങ്കിൽ ഇടത് ഭാഗത്തേക്കോ, കാലിനടിയിലേക്കോ തുപ്പുക. പിന്നെയത് നീക്കം ചെയ്യുകയും ചെയ്യുക." (ദ,തു,ന,ജ)', 'طَارِقِ بْنِ عَبْدِ اللهِ الْمُحَارِبِيِّ', 'ത്വാരികിബ്നു അബ്ദുല്ലാഹിൽ മുഹാറബീ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 111', array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 740, 740, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى شَبَثَ بْنَ رِبْعِيٍّ بَزَقَ بَيْنَ يَدَيْهِ، فَقَالَ: يَا شَبَثُ، لَا تَبْزُقْ بَيْنَ يَدَيْكَ، فَإِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَنْهَى عَنْ ذَلِكَ، وَقَالَ: "إِنَّ الرَّجُلَ إِذَا قَامَ يُصَلِّي أَقْبَلَ اللهُ عَلَيْهِ بِوَجْهِهِ، حَتَّى يَنْقَلِبَ أَوْ يُحْدِثَ حَدَثَ سُوءٍ". (جه)', 'ഹുദൈഫ(റ): അദ്ദേഹം ശബസുബ്നു റബ്ഈ മുന്നിലേക്ക് തുപ്പിയതായി കണ്ടു. അദ്ദേഹം പറഞ്ഞു: ശബസേ, മുന്നിലേക്ക് തുപ്പരുത്. നബി(സ) അത് വിരോധിച്ചിട്ടുണ്ട്. നബി(സ) പറഞ്ഞു: "ഒരാൾ നിസ്കരിക്കാൻ നിന്നാൽ അയാൾ അല്ലാഹുവിനെയാണ് അഭിമുഖീകരിക്കുന്നത്. വല്ല ചീത്ത കാര്യവും സംഭവിക്കുന്നത് വരെയോ അതല്ലെങ്കിൽ അവൻ തിരിയുന്നത് വരെയോ." (ജ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 112', array['جه']::text[], array['ജ']::text[], null, null, 740, 740, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَزَقَ فِي ثَوْبِهِ وَهُوَ فِي الصَّلَاةِ، ثُمَّ دَلَكَهُ. (م,جه)', 'അനസുബുനു മാലിക്(റ): റസൂൽ(സ) നിസ്കാരത്തിലായിരിക്കെ തന്റെ വസ്ത്രത്തിലേക്ക് തുപ്പി. പിന്നെയത് ഉരച്ചു കളഞ്ഞു. (മു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബുനു മാലിക്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 113', array['م','جه']::text[], array['മു','ജ']::text[], null, null, 740, 740, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: الْبُزَاقُ فِي الْمَسْجِدِ خَطِيئَةٌ وَكَفَّارَتُهَا دَفْنُهَا. (ق,د,ت,ن)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "പള്ളിയിൽ തുപ്പുന്നത് പാപമാണ്. അത് കുഴിച്ച് മൂടലാണ് അതിന്റെ പ്രായശ്ചിത്തം." (ബു,മു,ദ,തു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 114', array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 740, 740, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ دَخَلَ هَذَا الْمَسْجِدَ فَبَزَقَ فِيهِ أَوْ تَنَخَّمَ، فَلْيَحْفِرْ فَلْيَدْفِنْهُ، فَإِنْ لَمْ يَفْعَلْ فَلْيَبْزُقْ فِي ثَوْبِهِ، ثُمَّ لِيَخْرُجْ بِهِ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഈ പള്ളിയിൽ പ്രവേശിച്ച് അതിൽ തുപ്പുകയോ, മൂക്ക് ചീറ്റുകയോ ചെയ്താൽ ഒരു കുഴി കുഴിച്ച് അതിൽ മൂടട്ടെ. അങ്ങനെ ചെയ്യുന്നില്ലെങ്കിൽ സ്വന്തം വസ്ത്രത്തിൽ തുപ്പി അതുമായി പുറത്തു പോവട്ടെ." (ദ)', 'أَبِي هُرَيْرَةَ قَالَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 115', array['د']::text[], array['ദ']::text[], null, null, 740, 741, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ عَبْدِ اللهِ بْنِ الشِّخِّيرِ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي وَفِي صَدْرِهِ أَزِيزٌ كَأَزِيزِ الرَّحَى، مِنَ الْبُكَاءِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ت,ن)', 'അബ്ദുല്ലാഹിബ്നു ശഖീർ(റ): തിരുമേനി(സ) നിസ്കരിക്കുന്നതു ഞാൻ കണ്ടു. അന്നേരം ആസുകല്ലിൽ നിന്നും മുഴക്കമുണ്ടാകുന്നതുപോലെ തിരുമേനി(സ)യുടെ നെഞ്ചിൽ നിന്നും അവിടുന്ന് കരയുന്നതിന്റെ ശബ്ദമുണ്ടായിരുന്നു. (തു,ന)', 'عَبْدِ اللهِ بْنِ الشِّخِّيرِ', 'അബ്ദുല്ലാഹിബ്നു ശഖീർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 116', array['ت','ن']::text[], array['തു','ന']::text[], null, null, 741, 741, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ أَبِى سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا تَثَاءَبَ أَحَدُكُمْ فِي الصَّلَاةِ فَلْيَكْظِمْ مَا اسْتَطَاعَ، فَإِنَّ الشَّيْطَانَ يَدْخُلُ". وَفِي رِوَايَةٍ: "فَلْيُمْسِكْ بِيَدِهِ عَلَى فِيهِ، فَإِنَّ الشَّيْطَانَ يَدْخُلُ". (ق,د,ت,ن)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും നിസ്കാരത്തിൽ കോട്ടു വായിട്ടാൽ സാധിക്കുന്നത്ര അവൻ തടഞ്ഞ് വെക്കട്ടെ. കാരണം അത് മുഖേന പിശാച് പ്രവേശിച്ചേക്കാം." മറ്റൊരു റിപ്പോർട്ടിൽ: "തന്റെ കൈകൊണ്ട് വായ് പൊത്തട്ടെ, കാരണം അതുമുഖേന പിശാച് പ്രവേശിച്ചേക്കാം (ബു,മു,ദ,തു,ന)', 'أَبِى سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 117', array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 741, 741, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=127), 1, 'وَفِي رِوَايَةٍ: "فَلْيُمْسِكْ بِيَدِهِ عَلَى فِيهِ، فَإِنَّ الشَّيْطَانَ يَدْخُلُ". (ق,د,ت,ن)', 'മറ്റൊരു നിവേദനിൽ: "തന്റെ കൈകൊണ്ട് വായ് പൊത്തട്ടെ, കാരണം അതുമുഖേന പിശാച് പ്രവേശിച്ചേക്കാം (ബു,മു,ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "التَّسْبِيحُ لِلرِّجَالِ، وَالتَّصْفِيقُ لِلنِّسَاءِ". حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "തസ്ബീഹ് ചൊല്ലൽ പുരുഷന്മാർക്കുള്ളതും കൈ കൊട്ടൽ സ്ത്രീകൾക്കുള്ളതുമാണ്." (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 118', array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 741, 741, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَخَّصَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلنِّسَاءِ فِي التَّصْفِيقِ، وَلِلرِّجَالِ فِي التَّسْبِيحِ. (جه)', 'ഇബ്നുഉമർ(റ): സ്ത്രീകൾക്ക് കൈ കൊട്ടുന്നതിലും പുരുഷന്മാർക്ക് തസ്ബീഹ് ചൊല്ലുന്നതിലും റസൂൽ(സ) അനുവാദം നൽകി. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 119', array['جه']::text[], array['ജ']::text[], null, null, 741, 741, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ قِتَالٌ بَيْنَ بَنِي عَمْرِو بْنِ عَوْفٍ، فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَتَاهُمْ لِيُصْلِحَ بَيْنَهُمْ بَعْدَ الظُّهْرِ، فَقَالَ لِبِلَالٍ: "إِنْ حَضَرَتْ صَلَاةُ الْعَصْرِ وَلَمْ آتِكَ فَمُرْ أَبَا بَكْرٍ فَلْيُصَلِّ بِالنَّاسِ". فَلَمَّا حَضَرَتْ الْعَصْرُ أَذَّنَ بِلَالٌ ثُمَّ أَقَامَ ثُمَّ أَمَرَ أَبَا بَكْرٍ فَتَقَدَّمَ، قَالَ فِي آخِرِهِ: "إِذَا نَابَكُمْ شَيْءٌ فِي الصَّلَاةِ فَلْيُسَبِّحِ الرِّجَالُ وَلْيُصَفِّحِ النِّسَاءُ". (د)', 'സഹ്ലുബ്നു സഅദ്(റ): അംറുബ്നു ഔഫ് ഗോത്രത്തിനിടയിൽ യുദ്ധം നടന്നു. നബി(സ) അത് അറിഞ്ഞപ്പോൾ അവർക്കിടയിൽ സന്ധിയുണ്ടാക്കാൻ വേണ്ടി ളുഹ്റിന് ശേഷം അവരുടെ അടുത്തേക്ക് പോയി. അവിടുന്ന് ബിലാലി(റ)നോട് പറഞ്ഞു: "അസ്വർ നിസ്കാരമാകുകയും ഞാൻ എത്താതിരിക്കുകയും ചെയ്താൽ അബൂബക്കറി(റ)നോട് ജനങ്ങൾക്ക് ഇമാം നിൽക്കാൻ കൽപ്പിക്കുക." അസ്വറിന്റെ സമയമായപ്പോൾ ബിലാൽ(റ) ബാങ്കും ഇഖാമത്തും കൊടുത്ത് അബൂബക്കറി(റ)നോട് ഇമാം നിൽക്കാൻ ആവശ്യപ്പെട്ടു. അവസാനം പ്രവാചകൻ(സ) ഇപ്രകാരം പറഞ്ഞു: "നിസ്കാരത്തിൽ വല്ലതും മറന്ന് പോയാൽ പുരുഷന്മാർ തസ്ബീഹ് ചൊല്ലട്ടെ, സ്ത്രീകൾ കൈ കൊട്ടുകയും ചെയ്യട്ടെ." (ദ)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅദ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 120', array['د']::text[], array['ദ']::text[], null, null, 741, 742, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ عِيسَى بْنِ أَيُّوبَ قَالَ: قَوْلُهُ "التَّصْفِيحُ لِلنِّسَاءِ" تَضْرِبُ بِأُصْبُعَيْنِ مِنْ يَمِينِهَا عَلَى كَفِّهَا الْيُسْرَى. (د)', 'ഈസബ്നു അയ്യൂബ് പറഞ്ഞു: സ്ത്രീകൾ കൈ കൊട്ടുക എന്നത് കൊണ്ട് പ്രവാചകൻ(സ) ഉദ്ദേശിക്കുന്നത് വലത് ഭാഗത്തെ രണ്ട് വിരലുകൾ കൊണ്ട് ഇടത് ഭാഗത്തെ മുൻകയ്യിൽ അടിക്കലാണ്. (ദ)', 'عِيسَى بْنِ أَيُّوبَ قَالَ', 'ഈസബ്നു അയ്യൂബ് പറഞ്ഞു', null, 'അച്ചടിയിലെ നമ്പർ: 121', array['د']::text[], array['ദ']::text[], null, null, 742, 742, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي وَهُوَ حَامِلٌ أُمَامَةَ، فَإِذَا سَجَدَ وَضَعَهَا، وَإِذَا قَامَ رَفَعَهَا. وَفِي رِوَايَةٍ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَؤُمُّ النَّاسَ، وَهُوَ حَامِلٌ أُمَامَةَ بِنْتَ أَبِي الْعَاصِ عَلَى عَاتِقِهِ، فَإِذَا رَكَعَ وَضَعَهَا فَإِذَا فَرَغَ مِنْ سُجُودِهِ أَعَادَهَا. (ق,د,ن)', 'അബൂഖത്താദ(റ): റസൂൽ(സ) ഉമാമയേയും (പ്രവാചകന്റെ പൗത്രൻ) വഹിച്ചുകൊണ്ട് നിസ്കരിച്ചു. സുജൂദ് ചെയ്യുമ്പോൾ താഴെ വെക്കും, നിൽക്കുമ്പോൾ വീണ്ടും എടുക്കും. മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) ഉമാമ ബിൻത് അബിൽ ആസിനെ മുതുകിൽ വഹിച്ചുകൊണ്ട്, ജനങ്ങൾക്ക് ഇമാമായി നിസ്കരിച്ചു. റുകൂഅ് ചെയ്യുമ്പോൾ താഴെ വെക്കും സുജൂദിൽ നിന്ന് ഉയർന്നാൽ വീണ്ടും വഹിക്കും. (ബു,മു,ദ,ന)', 'أَبِي قَتَادَةَ', 'അബൂഖത്താദ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 122', array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 742, 742, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=132), 1, 'وَفِي رِوَايَةٍ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَؤُمُّ النَّاسَ، وَهُوَ حَامِلٌ أُمَامَةَ بِنْتَ أَبِي الْعَاصِ عَلَى عَاتِقِهِ، فَإِذَا رَكَعَ وَضَعَهَا فَإِذَا فَرَغَ مِنْ سُجُودِهِ أَعَادَهَا. (ق,د,ن)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) ഉമാമ ബിൻത് അബിൽ ആസിനെ മുതുകിൽ വഹിച്ചുകൊണ്ട്, ജനങ്ങൾക്ക് ഇമാമായി നിസ്കരിച്ചു. റുകൂഅ് ചെയ്യുമ്പോൾ താഴെ വെക്കും സുജൂദിൽ നിന്ന് ഉയർന്നാൽ വീണ്ടും വഹിക്കും. (ബു,മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا، وَقَدْ سَأَلَتْهَا امْرَأَةٌ: مَاذَا تُصَلِّي فِيهِ الْمَرْأَةُ مِنَ الثِّيَابِ؟ فَقَالَتْ: تُصَلِّي فِي الْخِمَارِ وَالدِّرْعِ السَّابِغِ الَّذِي يُغَيِّبُ ظُهُورَ قَدَمَيْهَا. (د)', 'ഉമ്മുസലമ(റ): ഒരു സ്ത്രീ മഹതിയോട് ചോദിച്ചു: സ്ത്രീക്ക് നിസ്കരിക്കാൻ എന്ത് വസ്ത്രമാണ് വേണ്ടത്?. മഹതി പറഞ്ഞു: മുഖമക്കനയും, രണ്ട് കാൽ പാദങ്ങൾ മറയുന്ന മുഴു വസ്ത്രവുമാണ് വേണ്ടത്. (ദ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 123', array['د']::text[], array['ദ']::text[], null, null, 742, 742, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا سَأَلَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَتُصَلِّي الْمَرْأَةُ فِي دِرْعٍ وَخِمَارٍ لَيْسَ عَلَيْهَا إِزَارٌ؟ قَالَ: "إِذَا كَانَ الدِّرْعُ سَابِغًا يُغَطِّي ظُهُورَ قَدَمَيْهَا". (د)', 'ഉമ്മുസലമ(റ): മഹതി നബി(സ)യോട് ചോദിച്ചു: സ്ത്രീക്ക് തുണിയില്ലാതെ മുഴു വസ്ത്രവും മുഖമക്കനയും ധരിച്ച് നമസ്കരിക്കാമോ? നബി(സ) പറഞ്ഞു: "മുഴു വസ്ത്രം രണ്ട് കാൽ പാദവും മറക്കുന്നതാണങ്കിൽ. (നിസ്കരിക്കാം)" (ദ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 124', array['د']::text[], array['ദ']::text[], null, null, 742, 742, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَقَدْ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الْفَجْرَ فَيَشْهَدُ مَعَهُ نِسَاءٌ مِنَ الْمُؤْمِنَاتِ مُتَلَفِّعَاتٍ فِي مُرُوطِهِنَّ ثُمَّ يَرْجِعْنَ إِلَى بُيُوتِهِنَّ مَا يَعْرِفُهُنَّ أَحَدٌ. (خ)', 'ആഇശ(റ): റസൂൽ(സ) സുബ്ഹ് നിസ്കരിക്കുമ്പോൾ സത്യവിശ്വാസിനികളായ സ്ത്രീകൾ വസ്ത്രം മൂടിപ്പുതച്ചുകൊണ്ട് അതിൽ പങ്കെടുക്കാറുണ്ടായിരുന്നു. അവർ സ്വന്തം വീടുകളിലേക്ക് തിരിച്ചു പോകുമ്പോൾ അവരെ ആർക്കും തിരിച്ചറിയുമായിരുന്നില്ല. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 125', array['خ']::text[], array['ബു']::text[], null, null, 742, 743, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ أَسْبَلَ إِزَارَهُ فِي صَلَاتِهِ خُيَلَاءَ فَلَيْسَ مِنَ اللهِ فِي حِلٍّ وَلَا حَرَامٍ". (د,ن)', 'ഇബ്നുമസ്ഊദ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആർ തന്റെ വസ്ത്രം നിസ്കാരത്തിൽ അഹന്തയോടെ നിലത്ത് വലിച്ചിഴക്കുന്നുവോ അവന് അല്ലാഹുവിൽ നിന്നുള്ള പാപമോചനവും നരക മോചനവും ലഭിക്കില്ല." (ദ,ന)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 126', array['د','ن']::text[], array['ദ','ന']::text[], null, null, 743, 743, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا رَجُلٌ يُصَلِّي مُسْبِلًا إِزَارَهُ إِذْ قَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اذْهَبْ فَتَوَضَّأْ". فَذَهَبَ فَتَوَضَّأَ ثُمَّ جَاءَ، ثُمَّ قَالَ: "اذْهَبْ فَتَوَضَّأْ". فَذَهَبَ فَتَوَضَّأَ ثُمَّ جَاءَ، فَقَالَ لَهُ رَجُلٌ: يَا رَسُولَ اللهِ، مَا لَكَ أَمَرْتَهُ أَنْ يَتَوَضَّأَ، ثُمَّ سَكَتَّ عَنْهُ؟ فَقَالَ: "إِنَّهُ كَانَ يُصَلِّي وَهُوَ مُسْبِلٌ إِزَارَهُ، وَإِنَّ اللهَ تَعَالَى لَا يَقْبَلُ صَلَاةَ رَجُلٍ مُسْبِلٍ إِزَارَهُ". (د)', 'അബൂഹുറൈറ(റ): ഒരാൾ തന്റെ വസ്ത്രം നിലത്തിഴച്ച് നിസ്കരിക്കുമ്പോൾ പ്രവാചകൻ(സ) അയാളോട് പറഞ്ഞു: "പോയി വുദു ചെയ്തു വരൂ." അയാൾ പോയി വുദു ചെയ്തു വന്നു. പ്രവാചകൻ(സ) വീണ്ടും പറഞ്ഞു: "നീ പോയി വുദു ചെയ്തു വരൂ." അയാൾ വീണ്ടും വുദു ചെയ്തു വന്നു. അപ്പോൾ ഒരാൾ ചോദിച്ചു: താങ്കളെന്താണ് പ്രവാചകരെ അയാളോട് അപ്രകാരം കൽപിക്കുകയല്ലാതെ മറ്റൊന്നും പറയാത്തത്? പ്രവാചകൻ(സ) പറഞ്ഞു: "അയാൾ തന്റെ വസ്ത്രം വലിച്ചിഴച്ചു കൊണ്ടാണ് നിസ്കരിച്ചത്. വസ്ത്രം വലിച്ചിഴക്കുന്നവന്റെ നിസ്കാരം അല്ലാഹു സ്വീകരിക്കുകയില്ല." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 127', array['د']::text[], array['ദ']::text[], null, null, 743, 743, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا قُرِّبَ الْعَشَاءُ وَحَضَرَتِ الصَّلَاةُ فَابْدَءُوا بِهِ قَبْلَ أَنْ تُصَلُّوا صَلَاةَ الْمَغْرِبِ، وَلَا تَعْجَلُوا عَنْ عَشَائِكُمْ". (م)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഭക്ഷണം തയ്യാറായിരിക്കെ നിസ്കാര സമയമായാൽ മഗ്രിബ് നിസ്കരിക്കുന്നതിനു മുമ്പു തന്നെ ഭക്ഷണം കഴിക്കുക, ഭക്ഷണം മാറ്റി നിർത്തി നിസ്കാരത്തിൽ ധൃതി കാണിക്കരുത്." (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 128', array['م']::text[], array['മു']::text[], null, null, 743, 743, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا سُئِلَتْ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَا كَانَ النَّبِيُّ يَصْنَعُ فِي بَيْتِهِ قَالَتْ: كَانَ يَكُونُ فِي مِهْنَةِ أَهْلِهِ – تَعْنِي خِدْمَةَ أَهْلِهِ – فَإِذَا حَضَرَتِ الصَّلَاةُ خَرَجَ إِلَى الصَّلَاةِ. (خ)', 'ആയിശ(റ): പ്രവാചക(സ)ന്റെ വീട്ടിലെ ചര്യയെ കുറിച്ച് മഹതിയോട് ചോദിക്കപ്പെട്ടു: മഹതി പറഞ്ഞു: റസൂൽ(സ) തന്റെ ഭാര്യയെ ജോലിയിൽ സഹായിച്ചു കൊണ്ടിരിക്കെ നിസ്കാര സമയമായാൽ നിസ്കാരത്തിനായി പുറപ്പെടും. (ബു)', 'عَائِشَةَ', 'ആയിശ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 129', array['خ']::text[], array['ബു']::text[], null, null, 743, 743, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ مَالِكِ بْنِ الْحُوَيْرِثِ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنِّي لَأُصَلِّي بِكُمْ وَمَا أُرِيدُ الصَّلَاةَ أُصَلِّي كَيْفَ رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي. (خ)', 'മാലിക്ബ്നു ഹുവൈരിസ്(റ): ശരിക്കും നിസ്കരിക്കാൻ ഉദ്ദേശ്യമില്ലാതെയാണ് നിങ്ങളുമായി ഞാൻ നിസ്കരിക്കുന്നത്. നബി(സ) എപ്രകാരം നിസ്കരിക്കുന്നതാണ് ഞാൻ കണ്ടെതെന്ന് നിങ്ങളെ കാണിച്ചു തരാനാണ് ഞാൻ നിസ്കരിക്കുന്നത്. (ബു)', 'مَالِكِ بْنِ الْحُوَيْرِثِ', 'മാലിക്ബ്നു ഹുവൈരിസ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 130', array['خ']::text[], array['ബു']::text[], null, null, 743, 744, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ قَالَ: هَبَطْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ ثَنِيَّةِ أَذَاخِرَ فَحَضَرَتِ الصَّلَاةُ – يَعْنِي فَصَلَّى إِلَى جِدَارٍ فَاتَّخَذَهُ قِبْلَةً وَنَحْنُ خَلْفَهُ، فَجَاءَتْ بَهِمَةٌ تَمُرُّ بَيْنَ يَدَيْهِ، فَمَا زَالَ يُدَارِئُهَا حَتَّى لَصَقَ بَطْنُهُ بِالْجِدَارِ وَمَرَّتْ مِنْ وَرَائِهِ. (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഞങ്ങൾ പ്രവാചക(സ)നോടൊപ്പം (മക്കയുടേയും മദീനയുടേയും ഇടക്കുള്ള) ''സനിയ്യത്തു അദാഖിർ'' എന്ന സ്ഥലത്തിറങ്ങി. അപ്പോൾ നിസ്കാര സമയമായിരുന്നു. ഒരു ചുമരിനു നേരെ നിന്നു നബി(സ) നിസ്കരിച്ചു. ഞങ്ങൾ പിന്നിൽ നിന്നു. മൃഗങ്ങൾ മുന്നിലൂടെ നടന്നപ്പോൾ റസൂൽ(സ) അവയെ തടഞ്ഞിരുന്നു. നബി(സ)യുടെ വയർ ചുമരിൽ ഉരയുവോളം. പിന്നീട് അവ ചുമരിന് പിന്നിലൂടെ നടന്നു. (ദ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 131', array['د']::text[], array['ദ']::text[], null, null, 744, 744, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي، فَذَهَبَ جَدْيٌ يَمُرُّ بَيْنَ يَدَيْهِ فَجَعَلَ يَتَّقِيهِ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) നിസ്കരിക്കുമ്പോൾ ഒരു ആട്ടിൻ കുട്ടി മുന്നിലൂടെ നടന്നു. അപ്പോൾ നബി(സ) അതിനെ തടഞ്ഞു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 132', array['د']::text[], array['ദ']::text[], null, null, 744, 744, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صَلَّى صَلَاتَنَا، وَاسْتَقْبَلَ قِبْلَتَنَا، وَأَكَلَ ذَبِيحَتَنَا فَذَلِكَ الْمُسْلِمُ الَّذِي لَهُ ذِمَّةُ اللهِ وَذِمَّةُ رَسُولِهِ، فَلَا تُخْفِرُوا اللهَ فِي ذِمَّتِهِ". (خ)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആർ നമ്മുടെ നിസ്കാരം നിസ്കരിക്കുകയും, നമ്മുടെ ഖിബ്ലയെ അഭിമുഖീകരിക്കുകയും, നാം അറുത്തത് ഭക്ഷിക്കുകയും ചെയ്യുന്നുവോ അവനാണ് മുസ്ലിം. അവന് അല്ലാഹുവിന്റെയും റസൂലിന്റേയും സംരക്ഷണമുണ്ട്. സംരക്ഷണ വിഷയത്തിൽ അല്ലാഹുവിനെ നിങ്ങൾ ചതിക്കരുത്." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 133', array['خ']::text[], array['ബു']::text[], null, null, 744, 744, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ سُئِلَ عَنْ رَجُلٍ طَافَ بِالْبَيْتِ الْعُمْرَةَ وَلَمْ يَطُفْ بَيْنَ الصَّفَا وَالْمَرْوَةِ أَيَأْتِي امْرَأَتَهُ؟ فَقَالَ: قَدِمَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَطَافَ بِالْبَيْتِ سَبْعًا وَصَلَّى خَلْفَ الْمَقَامِ رَكْعَتَيْنِ، وَطَافَ بَيْنَ الصَّفَا وَالْمَرْوَةِ، وَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللهِ أُسْوَةٌ حَسَنَةٌ. (خ)', 'ഇബ്നുഉമർ(റ): ഉംറ വേളയിൽ കഅ്ബയെ ത്വവാഫ് ചെയ്യുകയും എന്നാൽ സ്വഫാ മർവയിൽ ഓടാതിരിക്കുകയും ചെയ്ത ഒരാളെകുറിച്ച് അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: അയാൾ തന്റെ ഭാര്യയുമായി ബന്ധപ്പെടുന്നത് അനുവദനീയമോ? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ) കഅ്ബയെ ഏഴ് തവണ ത്വവാഫ് ചെയ്തു, ''മഖൊമു ഇബ്റാഹീമിൽ'' രണ്ട് റകഅത്ത് നിസ്കരിച്ചു. സ്വഫാ മർവക്കിടയിൽ ത്വവാഫ് നടത്തി. നിങ്ങൾക്ക് അല്ലാഹുവിന്റെ ദൂതരിൽ ഉത്തമ മാതൃകയുണ്ട്. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 134', array['خ']::text[], array['ബു']::text[], null, null, 744, 744, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمَّا دَخَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْبَيْتَ، دَعَا فِي نَوَاحِيهِ كُلِّهَا وَلَمْ يُصَلِّ حَتَّى خَرَجَ مِنْهُ، فَلَمَّا خَرَجَ رَكَعَ رَكْعَتَيْنِ فِي قِبَلِ الْكَعْبَةِ وَقَالَ: هَذِهِ الْقِبْلَةُ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): പ്രവാചകൻ(സ) കഅ്ബയിൽ പ്രവേശിച്ചപ്പോൾ അതിന്റെ എല്ലാ ഭാഗത്തേക്കും തിരിഞ്ഞ് പ്രാർത്ഥിച്ചു. അവിടെ നിന്ന് പുറത്ത് വരുന്നത് വരെ നിസ്കരിച്ചില്ല. പുറത്ത് വന്നപ്പോൾ കഅ്ബക്ക് നേരെ തിരിഞ്ഞ് രണ്ട് റകഅത്ത് നിസ്കരിച്ചു. എന്നിട്ട് പറഞ്ഞു: "ഇതാണ് ഖിബ്ല." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 135', array['خ']::text[], array['ബു']::text[], null, null, 744, 745, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّى عَلَى رَاحِلَتِهِ حَيْثُ تَوَجَّهَتْ بِهِ، فَإِذَا أَرَادَ فَرِيضَةً نَزَلَ فَاسْتَقْبَلَ الْقِبْلَةَ. (خ)', 'ജാബിർ(റ): നബി(സ) തന്റെ വാഹനപ്പുറത്ത് നിന്ന് അത് തിരിഞ്ഞിരിക്കുന്ന ഭാഗത്തേക്ക് തിരിഞ്ഞ് നിസ്കരിക്കുമായിരുന്നു. ഫർള് നിസ്കരിക്കാനുദ്ദേശിച്ചാൽ വാഹനപ്പുറത്ത് നിന്നിറങ്ങി ഖിബ്ലക്ക് അഭിമുഖമായി നിൽക്കും. (ബു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 136', array['خ']::text[], array['ബു']::text[], null, null, 745, 745, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: وَافَقْتُ رَبِّي فِي ثَلَاثٍ، قُلْتُ: يَا رَسُولَ اللهِ، لَوِ اتَّخَذْنَا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى، فَنَزَلَتْ: {وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى} وَآيَةُ الْحِجَابِ، قُلْتُ: يَا رَسُولَ اللهِ، لَوْ أَمَرْتَ نِسَاءَكَ أَنْ يَحْتَجِبْنَ فَإِنَّهُ يُكَلِّمُهُنَّ الْبَرُّ وَالْفَاجِرُ، فَنَزَلَتْ آيَةُ الْحِجَابِ، وَاجْتَمَعَ نِسَاءُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْغَيْرَةِ عَلَيْهِ، فَقُلْتُ لَهُنَّ: {عَسَى رَبُّهُ إِنْ طَلَّقَكُنَّ أَنْ يُبْدِلَهُ أَزْوَاجًا خَيْرًا مِنْكُنَّ} [التحريم: ٥] فَنَزَلَتْ هَذِهِ الْآيَةُ. (خ)', 'ഉമർ(റ): എന്റെ റബ്ബ് എന്നോട് മൂന്ന് സന്ദർഭത്തിൽ യോജിച്ചു: ഞാൻ ചോദിച്ചു: പ്രവാചകരെ, മഖാമു ഇബ്റാഹീം നമുക്ക് നിസ്കാര സ്ഥലമാക്കിക്കൂടെ? അപ്പോഴാണ് ''നിങ്ങൾ മഖാമു ഇബ്റാഹീം നിസ്കാര സ്ഥലമാക്കുക.'' എന്ന ആയത്തിറങ്ങുന്നത്. അതു പോലെ ''ഹിജാബി''ന്റെ ആയത്തും, ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരെ, അങ്ങയുടെ ഭാര്യമാരോട് ''ഹിജാബ്'' സ്വീകരിക്കാൻ കൽപിച്ചിരുന്നങ്കിൽ, അവരോട് നല്ലവരും മോശപ്പെട്ടരും സംസാരിക്കുന്നുണ്ടല്ലോ! അപ്പോഴാണ് മൂടുപടത്തിന്റെ ആയത്തിറങ്ങുന്നത്. പ്രവാചകർ(സ)യോട് പ്രതിഷേധിക്കാൻ പത്നിമാർ ഒത്ത് കൂടി. ഞാൻ അവരോട് സംസാരിച്ചു. അപ്പോൾ ഞാൻ അവരോട് പറഞ്ഞു: ''അവിടുന്ന് ((പ്രവാചകൻ(സ)) നിങ്ങളെ വിവാഹമോചനം ചെയ്യുകയാണെങ്കിൽ, നിങ്ങളേക്കാൾ ഉത്തമരായ പത്നിമാരെ അവിടുത്തെ നാഥൻ പകരം നൽകിയേക്കാം.'' (തഹ്രീം:5) അപ്പോൾ ആ ആയത്ത് അവതരിച്ചു. (ബു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 137', array['خ']::text[], array['ബു']::text[], 'التحريم: ٥', null, 745, 745, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا قَدِمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ صَلَّى نَحْوَ بَيْتِ الْمَقْدِسِ سِتَّةَ عَشَرَ أَوْ سَبْعَةَ عَشَرَ شَهْرًا، وَكَانَ يُحِبُّ أَنْ يُوَجَّهَ إِلَى الْكَعْبَةِ فَأَنْزَلَ اللهُ تَعَالَى: {قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا... } [البقرة: ١٤٤] فَوُجِّهَ نَحْوَ الْكَعْبَةِ، وَصَلَّى مَعَهُ رَجُلٌ الْعَصْرَ، ثُمَّ خَرَجَ فَمَرَّ عَلَى قَوْمٍ مِنَ الْأَنْصَارِ فَقَالَ: هُوَ يَشْهَدُ أَنَّهُ صَلَّى مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَأَنَّهُ قَدْ وُجِّهَ إِلَى الْكَعْبَةِ فَانْحَرَفُوا وَهُمْ رُكُوعٌ فِي صَلَاةِ الْعَصْرِ. حَسَنٌ صَحِيحٌ. (ق,ت,ن,جه)', 'ബറാഉബ്നുആസിബ്(റ): നബി(സ) മദീനയിലെത്തിയപ്പോൾ പതിനാറോ, പതിനേഴോ മാസം ബൈത്തുൽ മുഖദ്ദിസിന്റെ നേരെ തിരിഞ്ഞാണ് നിസ്കരിച്ചിരുന്നത്. പ്രവാചകൻ(സ) കഅ്ബയിലേക്ക് തിരിയാൻ ആഗ്രഹിച്ചിരുന്നു. അപ്പോഴാണ്: ''താങ്കൾ ആകാശത്തേക്ക് മുഖം തിരിക്കുന്നത് നാം കാണുന്നു. താങ്കൾ തൃപ്തിപ്പെടുന്ന ഖിബ്ലയിലേക്ക് നാം നിങ്ങളെ തിരിക്കും, അതിനാൽ മസ്ജിദുൽ ഹറമിലേക്ക് മുഖം തിരിക്കുക.'' (അൽബഖറ: 144) എന്ന ആയത്ത് അവതരിക്കുന്നത്. അങ്ങനെ കഅ്ബയുടെ നേരെ മുഖം തിരിച്ചു. നബി(സ)യോടൊപ്പം ഒരാളും അസർ നിസ്കരിച്ചു. ശേഷം അയാൾ അൻസ്വാരികളുടെ അടുത്തേക്ക് ചെന്നു. അവർ ബൈത്തുൽ മുഖദ്ദിസിന്റെ നേരെ തിരിഞ്ഞ് നിസ്കരിക്കുകയായിരുന്നു (റുകൂഇൽ). അദ്ദേഹം അവരോട് പറഞ്ഞു: ഞാൻ റസൂലിന്റെകൂടെ നിസ്കരിച്ചാണ് വരുന്നത്, റസൂൽ(സ) കഅ്ബയുടെ ഭാഗത്തേക്ക് തിരിക്കപ്പെട്ടിരുന്നു. അപ്പോൾ അവർ അസർ നിസ്കാരത്തിലെ റുകൂഇലായിരിക്കെ തന്നെ കഅ്ബയിലേക്ക് തിരിഞ്ഞു. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ബു,മു,തു,ന,ജ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നുആസിബ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 138', array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], 'البقرة: ١٤٤', null, 745, 746, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنِ ابْنِ عُمَرَ قَالَ: كَانُوا رُكُوعًا فِي صَلَاةِ الصُّبْحِ. حَسَنٌ صَحِيحٌ. (ق,ت)', 'ഇബ്നുഉമർ(റ): അവർ സുബ്ഹ് നിസ്കാരത്തിലെ റുകൂഇലായിരുന്നു. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (ബു,മു,തു)', 'ابْنِ عُمَرَ قَالَ', 'ഇബ്നുഉമർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 139', array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 746, 746, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ قِبْلَةٌ". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "കിഴക്കിനും, പടിഞ്ഞാറിനും ഇടയിലുള്ളത് ഖിബ്ലയാകുന്നു." (തു,ജ)', 'أَبِي هُرَيْرَةَ قَالَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 140', array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 746, 746, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا فَرَغَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ طَوَافِ الْبَيْتِ أَتَى مَقَامَ إِبْرَاهِيمَ، فَقَالَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ: يَا رَسُولَ اللهِ، هَذَا مَقَامُ أَبِينَا إِبْرَاهِيمَ، الَّذِي قَالَ اللهُ: {وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى} [البقرة: ١٢٥] (د,ت,ن,جه)', 'ജാബിർ(റ): നബി(സ) ത്വവാഫിൽ നിന്ന് വിരമിച്ചപ്പോൾ മഖാമു ഇബ്റാഹീമിന്റെ അടുത്തെത്തി. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, ഇത് നമ്മുടെ പിതാവ് ഇബ്റാഹീം (പ്രാർത്ഥനക്ക് വേണ്ടി) നിന്ന സ്ഥലമാണ്. അതിനെ കുറിച്ച് അല്ലാഹു പറഞ്ഞു: ''ഇബ്റാഹീം (പ്രാർത്ഥനക്ക് വേണ്ടി) നിന്ന സ്ഥലം നിങ്ങളും പ്രാർത്ഥനാവേദിയായി സ്വീകരിക്കുക.'' (ദ,തു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 141', array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], 'البقرة: ١٢٥', null, 746, 746, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: بَيْنَمَا النَّاسُ بِقُبَاءٍ فِي صَلَاةِ الصُّبْحِ، جَاءَهُمْ آت فَقَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ أُنْزِلَ عَلَيْهِ اللَّيْلَةَ قُرْآنٌ، وَقَدْ أُمِرَ أَنْ يَسْتَقْبِلَ الْقِبْلَةَ، فَاسْتَقْبِلُوهَا وَكَانَتْ وُجُوهُهُمْ إِلَى الشَّامِ، فَاسْتَدَارُوا إِلَى الْكَعْبَةِ. (ن)', 'ഇബ്നുഉമർ(റ): ജനങ്ങൾ ''ഖുബാഇ''ൽ സുബ്ഹ് നിസ്കരത്തിലായിരിക്കെ അവരിലേക്ക് ഒരാൾ വന്ന് പറഞ്ഞു: നിശ്ചയം, നബി(സ)ക്ക് ഇന്നലെ രാത്രി ഖുർആൻ അവതരിച്ചിട്ടുണ്ട്. അവിടത്തോട് ഖിബ്ലയിലേക്ക് മുന്നിടാൻ കൽപിക്കപ്പെട്ടിരിക്കുന്നു. അപ്പോൾ അവർ കഅ്ബയിലേക്ക് മുന്നിട്ടു. അവർ ശാമിന്റെ ഭാഗത്തേക്കാണ് തിരിഞ്ഞിരുന്നത്. പിന്നീടവർ കഅ്ബയുടെ നേരെ തിരിഞ്ഞുനിന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 142', array['ن']::text[], array['ന']::text[], null, null, 746, 746, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي عَلَى رَاحِلَتِهِ فِي السَّفَرِ حَيْثُمَا تَوَجَّهَتْ، وَكَانَ ابْنُ عُمَرَ يَفْعَلُ ذَلِكَ. (ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) തന്റെ വാഹനം എങ്ങോട്ടാണോ തിരിഞ്ഞത് അങ്ങോട്ട് തിരിഞ്ഞാണ് നിസ്കരിച്ചിരുന്നത്. ഇബ്നു ഉമറും അപ്രകാരം ചെയ്തിരുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 143', array['ن']::text[], array['ന']::text[], null, null, 746, 746, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّى عَلَى الرَّاحِلَةِ قِبَلَ أَيِّ وَجْهٍ تَوَجَّهَ بِهِ، وَيُوتِرُ عَلَيْهَا غَيْرَ أَنَّهُ لَا يُصَلِّي عَلَيْهَا الْمَكْتُوبَةَ. (ق,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) തന്റെ വാഹനം തിരിയുന്നിടത്തേക്ക് തിരിഞ്ഞ് വാഹനപ്പുറത്ത് നിസ്കരിച്ചിരുന്നു. അതിൽ വിത്റും നിർവ്വഹിച്ചു. എന്നാൽ ഫർള് അപ്രകാരം നിർവ്വഹിച്ചിരുന്നില്ല. (ബു,മു,തു,ന)', 'ابْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 144', array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 746, 747, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ عَامِرِ بْنِ رَبِيعَةَ رَضِيَ اللهُ عَنْهُمَا عَنْ أَبِيهِ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ فِي لَيْلَةٍ مُظْلِمَةٍ، فَلَمْ نَدْرِ أَيْنَ الْقِبْلَةُ، فَصَلَّى كُلُّ رَجُلٍ مِنَّا عَلَى حِيَالِهِ، فَلَمَّا أَصْبَحْنَا ذَكَرْنَا ذَلِكَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَنَزَلَ {أَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللهِ} [البقرة: ١١٥] (ت,جه)', 'ആമിറുബ്നു റബീഅ(റ): ഞങ്ങൾ ഒരു ഇരുണ്ട രാത്രി പ്രവാചക(സ)നോടൊപ്പം യാത്രയിലായിരുന്നു. ഖിബ്ല എവിടെയാണെന്ന് ഞങ്ങൾ അറിഞ്ഞിരുന്നില്ല. ഞങ്ങൾ ഓരോരുത്തരും തങ്ങൾ മുന്നിടുന്ന ഭാഗത്തേക്ക് തിരിഞ്ഞു നിന്ന് നിസ്കരിച്ചു. പ്രഭാതമായപ്പോൾ ഞങ്ങൾ പ്രവാചകനോട് സംഭവം വിശദീകരിച്ചു; അപ്പോൾ ''നിങ്ങൾ എങ്ങോട്ട് തിരിഞ്ഞാലും അവിടെ അല്ലാഹുവിന്റെ മുഖമുണ്ട്.'' (അൽബഖറ:115) എന്ന ആയത്ത് അവതരിക്കപ്പെട്ടു. (തു,ജ)', 'عَامِرِ بْنِ رَبِيعَةَ', 'ആമിറുബ്നു റബീഅ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 145', array['ت','جه']::text[], array['തു','ജ']::text[], 'البقرة: ١١٥', null, 747, 747, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُمَا قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ رَافِعُو أَيْدِينَا فِي الصَّلَاةِ فَقَالَ: "مَابَالُهُمْ رَافِعِينَ أَيْدِيَهُمْ فِي الصَّلَاةِ، كَأَنَّهَا أَذْنَابُ الْخَيْلِ الشُّمُسِ؟ اسْكُنُوا فِي الصَّلَاةِ". (م,ن)', 'ജാബിറുബ്നു സമുറ(റ): ഞങ്ങൾ നിസ്കാരത്തിൽ കൈ ഉയർത്തിയിരിക്കെ പ്രവാചകൻ(സ) ഞങ്ങളിലേക്ക് വന്നു. അപ്പോൾ ചോദിച്ചു: "നിസ്കാരത്തിൽ കൈ ഉയർത്തിയവരുടെ അവസ്ഥയെന്താണ്? മോട്ട് കാണിക്കുന്ന കുതിരയുടെ വാലു പോലെ? നിങ്ങൾ നിസ്കാരത്തിൽ അടക്കം പാലിക്കുക." (മു,ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 146', array['م','ن']::text[], array['മു','ന']::text[], null, null, 747, 747, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا نُصَلِّي خَلْفَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَنُسَلِّمُ بِأَيْدِينَا، فَقَالَ: "مَابَالُ هَؤُلَاءِ يُسَلِّمُونَ بِأَيْدِيهِمْ كَأَنَّهَا أَذْنَابُ خَيْلٍ شُمُسٍ؟ أَمَا يَكْفِي أَحَدَهُمْ أَنْ يَضَعَ يَدَهُ عَلَى فَخِذِهِ، ثُمَّ يَقُولَ: السَّلَامُ عَلَيْكُمْ، السَّلَامُ عَلَيْكُمْ". (م,ن)', 'ജാബിറുബ്നു സമുറ(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ പിന്നിൽ നിസ്കരിക്കെ കൈകൾ കൊണ്ട് സലാം പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "കുസൃതിയുള്ള കുതിരയുടെ വാൽ പോലെ, കൈകൾ ഉപയോഗിച്ച് സലാം പറയുന്ന ജനതയുടെ അവസ്ഥയെന്ത്? അവർക്ക് കൈ, തുടയിൽ (അടക്കി) വെച്ച് കൂടെ?, (നിസ്കാര ശേഷം) ശേഷം അസ്സലാമു അലൈകും, അസ്സലാമു അലൈക്കും എന്ന് പറയാമല്ലോ!" (മു,ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 147', array['م','ن']::text[], array['മു','ന']::text[], null, null, 747, 747, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنِ ابْنِ عُمَرَ عَنْ صُهَيْبٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَرَرْتُ بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُصَلِّي، فَسَلَّمْتُ عَلَيْهِ، فَرَدَّ إِلَيَّ إِشَارَةً بِأُصْبُعِهِ. حَسَنٌ صَحِيحٌ (د,ت,ن)', 'സ്വുഹൈബ്(റ)വിൽ നിന്ന് ഇബ്നുഉമർ(റ): റസൂൽ(സ) നിസ്കരിക്കുമ്പോൾ സുഹൈബ്(റ) നബി(സ)യുടെ അരികിലൂടെ പോയി. അദ്ദേഹം സലാം പറഞ്ഞു. വിരലുപയോഗിച്ച് സൂചന നൽകിയാണ് നബി(സ) സലാം മടക്കിയത്. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ദ,തു,ന)', 'ابْنِ عُمَرَ عَنْ صُهَيْبٍ', 'സ്വുഹൈബ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 148', array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 747, 747, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا نُسَلِّمُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي الصَّلَاةِ، فَيَرُدُّ عَلَيْنَا، فَلَمَّا رَجَعْنَا مِنْ عِنْدِ النَّجَاشِيِّ سَلَّمْنَا عَلَيْهِ فَلَمْ يَرُدَّ عَلَيْنَا، وَقَالَ: "إِنَّ فِي الصَّلَاةِ لَشُغْلًا". (ق,د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഞങ്ങൾ റസൂലി(സ)നോട് നിസ്കാരത്തിലായിരിക്കെ സലാം പറഞ്ഞിരുന്നു. നബി(സ) ഞങ്ങളോട് സലാം മടക്കുകയും ചെയ്തു. ''നജ്ജാശി'' (അബ്സീനിയയിലെ രാജാവ്)യുടെ അടുത്തു നിന്ന് മടങ്ങി വന്നപ്പോൾ പ്രവാചകർ(സ)യോട് ഞങ്ങൾ സലാം ചൊല്ലി, ഞങ്ങളോട് പ്രവാചകൻ(സ) സലാം മടക്കിയില്ല. പ്രവാചകൻ(സ) പറഞ്ഞു: "നിസ്കാരത്തിൽ അതിൽ മാത്രം വ്യാപൃതനാവുക." (ബൂ,മു,ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 149', array['ق','د','ن','جه']::text[], array['ബൂ','മു','ദ','ന','ജ']::text[], null, null, 748, 748, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نُسَلِّمُ فِي الصَّلَاةِ وَنَأْمُرُ بِحَاجَتِنَا فَقَدِمْتُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُصَلِّي فَسَلَّمْتُ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيَّ السَّلَامَ، فَأَخَذَنِي مَا قَدُمَ وَمَا حَدُثَ، فَلَمَّا قَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الصَّلَاةَ، قَالَ: "إِنَّ اللهَ يُحْدِثُ مِنْ أَمْرِهِ مَا يَشَاءُ، وَإِنَّ اللهَ جَلَّ وَعَزَّ قَدْ أَحْدَثَ مِنْ أَمْرِهِ: أَنْ لَا تَكَلَّمُوا فِي الصَّلَاةِ". فَرَدَّ عَلَيَّ السَّلَامَ. (د,ن)', 'അബ്ദുല്ല(റ): ഞങ്ങൾ നിസ്കാരത്തിൽ സലാം ചൊല്ലിയിരുന്നു. ഞങ്ങളുടെ ആവശ്യങ്ങൾ കൽപ്പിക്കുകയും ചെയ്യുമായിരുന്നു. ഞാൻ പ്രവാചകർ(സ)യുടെ അടുത്തേക്ക് അവിടുന്ന് നിസ്കാരത്തിലായിരിക്കെ കടന്നുചെന്ന് സലാം ചെല്ലി. അവിടുന്ന് എനിക്ക് സലാം മടക്കിയില്ല. കഴിഞ്ഞതും വരാനുള്ളതുമൊക്കെ എന്നെ അസ്വസ്ഥനാക്കി. റസൂൽ(സ) നിസ്കാരം കഴിഞ്ഞപ്പോൾ എന്നോട് പറഞ്ഞു: "അല്ലാഹു അവന്റെ കാര്യങ്ങളിൽ അവനുദ്ദേശിക്കുന്നത് പുതുക്കും. പ്രതാപവാനും യുക്തിമാനുമായ അല്ലാഹു അവന്റെ കാര്യം പുതുക്കിയിരിക്കുന്നു. നിങ്ങൾ നിസ്കാരത്തിൽ സംസാരിക്കരുത്." ശേഷം എന്നോട് സലാം മടക്കി. (ദ,ന)', 'عَبْدِ اللهِ', 'അബ്ദുല്ല(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 150', array['د','ن']::text[], array['ദ','ന']::text[], null, null, 748, 748, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعَثَنِي لِحَاجَةٍ، ثُمَّ أَدْرَكْتُهُ وَهُوَ يَسِيرُ – قَالَ قُتَيْبَةُ: يُصَلِّي فَسَلَّمْتُ عَلَيْهِ فَأَشَارَ إِلَيَّ، فَلَمَّا فَرَغَ دَعَانِي، فَقَالَ: "إِنَّكَ سَلَّمْتَ آنِفًا وَأَنَا أُصَلِّي". وَهُوَ مُوَجِّهٌ حِينَئِذٍ قِبَلَ الْمَشْرِقِ. (م,ن,جه)', 'ജാബിർ(റ): അല്ലാഹുവിന്റെ ദൂതർ(സ) എന്നെ ഒരു ആവശ്യത്തിനയച്ചു. പിന്നീട് നബി(സ) യാത്രയിൽ (തന്റെ വാഹനപ്പുറത്തിരുന്ന്) നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടു. ഞാൻ അവിടത്തോട് സലാം ചൊല്ലി. അപ്പോൾ എന്നോട് ആഗ്യം കാണിച്ചു. നമസ്കാരം കഴിഞ്ഞപ്പോൾ എന്നെ വിളിച്ച് പറഞ്ഞു: "നീ സലാം ചൊല്ലിയത് ഞാൻ നിസ്കരിക്കുന്ന അവസരത്തിലാണ്." നബി(സ) അപ്പോൾ കിഴക്കോട്ടാണ് തിരിഞ്ഞിരുന്നത്. (മു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 151', array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 748, 748, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا يَقُولُ: خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى قُبَاءٍ يُصَلِّي فِيهِ، قَالَ: فَجَاءَتْهُ الْأَنْصَارُ، فَسَلَّمُوا عَلَيْهِ، وَهُوَ يُصَلِّي. قَالَ: فَقُلْتُ لِبِلَالٍ: كَيْفَ رَأَيْتَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَرُدُّ عَلَيْهِمْ حِينَ كَانُوا يُسَلِّمُونَ عَلَيْهِ وَهُوَ يُصَلِّي؟ قَالَ: يَقُولُ هَكَذَا: وَبَسَطَ كَفَّهُ، وَجَعَلَ بَطْنَهُ أَسْفَلَ، وَجَعَلَ ظَهْرَهُ إِلَى فَوْق. (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) ഖുബായിലേക്ക് നിസ്കരിക്കാനായി പുറപ്പെട്ടു. അപ്പോൾ അൻസാറുകൾ നിസ്കാരത്തിനിടക്ക് വന്ന് സലാം പറഞ്ഞു. ഞാൻ ബിലാൽ(റ)വോട് ചോദിച്ചു. അവർ സലാം പറഞ്ഞപ്പോൾ റസൂൽ(സ) അവരോട് എപ്രകാരമാണ് പ്രതികരിച്ചത്? അദ്ദേഹം പറഞ്ഞു: അവിടുന്ന് തന്റെ മുൻകൈ അതിന്റെ പള്ള ഭാഗം അടിയിലും പുറം ഭാഗം മേലെയുമാക്കി പരത്തിപ്പിടിച്ചു. (ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 152', array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 748, 748, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا غِرَارٍ فِي صَلَاةٍ وَلَا تَسْلِيمٍ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിസ്കാരത്തിലോ, സലാം പറയുന്നതിലോ യാതൊരു കുറവും വരുത്തരുത്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 153', array['د']::text[], array['ദ']::text[], null, null, 749, 749, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَرْسَلَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى بَنِي الْمُصْطَلِقِ، فَأَتَيْتُهُ وَهُوَ يُصَلِّي عَلَى بَعِيرِهِ فَكَلَّمْتُهُ، فَقَالَ لِي بِيَدِهِ هَكَذَا، ثُمَّ كَلَّمْتُهُ، فَقَالَ لِي هَكَذَا فَأَوْمَأَ زُهَيْرٌ أَيْضًا بِيَدِهِ نَحْوَ الْأَرْضِ وَأَنَا أَسْمَعُهُ يَقْرَأُ يُومِئُ بِرَأْسِهِ، فَلَمَّا فَرَغَ قَالَ: "مَا فَعَلْتَ فِي الَّذِي أَرْسَلْتُكَ؟ فَإِنَّهُ لَمْ يَمْنَعْنِي أَنْ أُكَلِّمَكَ إِلَّا أَنِّي كُنْتُ أُصَلِّي". (م,د,ت,ن,جه)', 'ജാബിർ(റ): എന്നെ നബി(സ) ബനുൽ മുസ്തലിഖിലേക്ക് അയച്ചു. നബി(സ) ഒട്ടകപ്പുറത്ത് നിന്ന് നിസ്കരിച്ചുകൊണ്ടിരിക്കെ ഞാൻ നബി(സ)യുടെ അടുത്തേക്ക് വന്ന് സംസാരിച്ചു. അവിടുന്ന് കൈ കൊണ്ട് ഇപ്രകാരം കാണിച്ചു. ഞാൻ വീണ്ടും സംസാരിച്ചപ്പോൾ കൈ കൊണ്ട് ഇപ്രകാരം കാണിച്ചു. നബി(സ)യുടെ പാരായണവും തല കൊണ്ട് ആഗ്യം കാണിക്കുന്നതും ഞാൻ കാണുന്നുണ്ടായിരുന്നു. ശേഷം എന്നോട് ചോദിച്ചു: "നിന്നെ അയച്ച കാര്യത്തിൽ നീ എന്താണ് ചെയതത്? നിന്നോട് സംസാരിക്കുന്നതിൽ നിന്ന് എന്നെ തടഞ്ഞത് ഞാൻ നിസ്കരിക്കുകയായിരുന്നു എന്നതാണ്." (മു,ദ,തു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 154', array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 749, 749, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَتَيْتُهُ وَهُوَ يَسِيرُ مُشَرِّقًا أَوْ مُغَرِّبًا، فَسَلَّمْتُ عَلَيْهِ فَأَشَارَ بِيَدِهِ، ثُمَّ سَلَّمْتُ عَلَيْهِ فَأَشَارَ بِيَدِهِ، فَانْصَرَفْتُ، فَنَادَانِي: "يَا جَابِرُ" فَنَادَانِي النَّاسُ: "يَا جَابِرُ" فَأَتَيْتُهُ فَقُلْتُ: يَا رَسُولَ اللهِ إِنِّي سَلَّمْتُ عَلَيْكَ فَلَمْ تَرُدَّ عَلَيَّ. قَالَ: "إِنِّي كُنْتُ أُصَلِّي". (ن)', 'ജാബിർ(റ): റസൂൽ(സ) എന്നെ ഒരു സ്ഥലത്തേക്ക് അയച്ചു. പ്രവാചകൻ(സ) കിഴക്കോട്ടോ, പടിഞ്ഞാറോട്ടോ യാത്ര ചെയ്യുമ്പോൾ ഞാനങ്ങോട്ട് ചെന്നു. സലാം പറഞ്ഞപ്പോൾ നബി(സ) കൈ കൊണ്ട് ആംഗ്യം കാണിച്ചു. വീണ്ടും സലാം പറഞ്ഞപ്പോൾ പിന്നെയും ആംഗ്യം കാണിച്ചു. അപ്പോൾ ഞാൻ തിരിച്ചു പോയി. നബി(സ) എന്നെ ''ജാബിർ'' എന്ന് വിളിച്ചു. ജനങ്ങൾ അറിയിച്ച പ്രകാരം ഞാൻ റസൂലി(സ)ന്റെ അടുത്ത് ചെന്ന് പറഞ്ഞു: റസൂലേ, ഞാൻ താങ്കൾക്ക് സലാം പറഞ്ഞിരുന്നു. പക്ഷേ, അങ്ങ് മടക്കിയില്ല. റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ നിസ്കരിക്കുകയായിരുന്നു." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 155', array['ن']::text[], array['ന']::text[], null, null, 749, 749, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ جَابِرِ بْنِ عَبْدِاللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: بَعَثَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي حَاجَةٍ لَهُ فَانْطَلَقْتُ ثُمَّ رَجَعْتُ، وَقَدْ قَضَيْتُهَا فَأَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَلَّمْتُ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيَّ فَوَقَعَ فِي قَلْبِي مَا اللهُ أَعْلَمُ بِهِ فَقُلْتُ فِي نَفْسِي لَعَلَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَجَدَ عَلَيَّ أَنِّي أَبْطَأْتُ، ثُمَّ سَلَّمْتُ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيَّ، فَوَقَعَ فِي قَلْبِي أَشَدُّ مِنَ الْمَرَّةِ الْأُولَى ثُمَّ سَلَّمْتُ عَلَيْهِ فَرَدَّ عَلَيَّ فَقَالَ: "إِنَّمَا مَنَعَنِي أَنْ أَرُدَّ عَلَيْكَ أَنِّي كُنْتُ أُصَلِّي". وَكَانَ عَلَى رَاحِلَتِهِ مُتَوَجِّهًا إِلَى غَيْرِ الْقِبْلَةِ. (خ)', 'ജാബിർ(റ): എന്നെ തിരുമേനി(സ) ഒരിടത്തേക്ക് ഒരാവശ്യാർത്ഥം അയച്ചു. അക്കാര്യം നിർവ്വഹിച്ച് തിരുമേനി(സ)യുടെ അടുക്കൽ ചെന്നു തിരുമേനി(സ)ക്ക് ''സലാം'' ചൊല്ലി, തിരുമേനി(സ) സലാം മടക്കിയില്ല. എന്റെ മനസ്സിനെ അതു വല്ലാതെ വേദനിപ്പിച്ചു. ആ വേദനയുടെ അഗാധത അല്ലാഹുവിനേ അറിയുകയുള്ളു. തിരിച്ചെത്താൻ താമസിച്ചതുകൊണ്ട് തിരുമേനി(സ) കോപിച്ചിട്ടുണ്ടായിരിക്കാമെന്ന് ഞാനെന്റെ മനസ്സിൽ സങ്കൽപിച്ചു. പിന്നേയും തിരുമേനി(സ)ക്ക് ഞാൻ സലാം ചൊല്ലിനോക്കി. അപ്പോഴും തിരുമേനി(സ) സലാമിന് മറുപടി നൽകിയില്ല. അന്നേരം ആദ്യത്തെ പ്രാവശ്യത്തേക്കാൾ എനിക്ക് മനോവേദനയുണ്ടായി. പിന്നേയും തിരുമേനി(സ)ക്ക് ഞാൻ സലാംചൊല്ലി നോക്കി. അപ്പോൾ എന്റെ സലാമിന് തിരുമേനി(സ) മറുപടി നൽകി. തിരുമേനി(സ) അരുളി: "ഞാൻ നിസ്കരിക്കുകയായിരുന്നു, അതുകൊണ്ടാണ് നിങ്ങളുടെ സലാമിന് മറുപടി നൽകാൻ കഴിയാതിരുന്നത്." അന്നേരം തിരുമേനി(സ) തന്റെ വാഹനത്തിലിരുന്ന് ഖിബ്ലക്ക് അഭിമുഖമല്ലാതെയാണ് നിസ്കരിച്ചിരുന്നത്. (ബു)', 'جَابِرِ بْنِ عَبْدِاللهِ', 'ജാബിർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 156', array['خ']::text[], array['ബു']::text[], null, null, 749, 749, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ أَحَدُنَا يُكَلِّمُ الرَّجُلَ إِلَى جَنْبِهِ فِي الصَّلَاةِ، فَنَزَلَتْ: {وَقُومُوا لِلَّهِ قَانِتِينَ} [البقرة:٢٣٨] فَأُمِرْنَا بِالسُّكُوتِ وَنُهِينَا عَنِ الْكَلَامِ. (ق,د,ت,ن,جه)', 'സൈദുബ്നു അർഖം(റ): പ്രവാചക(സ)ന്റെ അടുത്തുള്ള ഒരാളോട് ഞങ്ങളിലൊരാൾ നിസ്കാരത്തിൽ സംസാരിച്ചു. അപ്പോൾ "നിങ്ങൾ അല്ലാഹുവിന്ന് വിധേയമായി നിൽക്കുക." എന്ന ആയത്തിറങ്ങി. അങ്ങിനെ ഞങ്ങൾ നിശ്ശബ്ദത പാലിക്കാൻ കൽപ്പിക്കപ്പെടുകയും സംസാരിക്കുന്നതിൽ നിന്ന് വിലക്കപ്പെടുകയും ചെയ്തു. (ബു,മു,ദ,തു,ന,ജ)', 'زَيْدِ بْنِ أَرْقَمَ', 'സൈദുബ്നു അർഖം(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 157', array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], 'البقرة:٢٣٨', null, 750, 750, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى الصَّلَاةِ، وَقُمْنَا مَعَهُ، فَقَالَ أَعْرَابِيٌّ – وَهُوَ فِي الصَّلَاةِ –: اللَّهُمَّ ارْحَمْنِي وَمُحَمَّدًا، وَلَا تَرْحَمْ مَعَنَا أَحَدًا. فَلَمَّا سَلَّمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِلْأَعْرَابِيِّ: "لَقَدْ تَحَجَّرْتَ وَاسِعًا". يُرِيدُ رَحْمَةَ اللهِ عَزَّ وَجَلَّ. (د,ت,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) നിസ്കരിക്കാനായി എഴുന്നേറ്റു. കൂടെ ഞങ്ങളും എഴുന്നേറ്റു. നബി(സ) നിസ്കാരത്തിലായിരിക്കെ ഒരു അഅ്റാബി പറഞ്ഞു: അല്ലാഹുവേ, എനിക്കും മുഹമ്മദിനും അനുഗ്രഹം ചെയ്യേണമേ. ഞങ്ങളോടൊപ്പം ആർക്കും കരുണയേകരുത്. നബി(സ) സലാം വീട്ടിയപ്പോൾ അഅ്റാബിയോട് പറഞ്ഞു: "വളരെ വിശാലമായ ഒരു കാര്യം നീ സങ്കുചിതമാക്കിയിരിക്കുന്നുവല്ലോ." നബി(സ) ഉദ്ദേശിച്ചത് അല്ലാഹുവിന്റെ അനുഗ്രഹത്തെയായിരുന്നു. (ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 158', array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 750, 750, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ يَقُولُ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَزَالُ اللهُ عَزَّ وَجَلَّ مُقْبِلًا عَلَى الْعَبْدِ فِي صَلَاتِهِ مَا لَمْ يَلْتَفِتْ، فَإِذَا صَرَفَ وَجْهَهُ انْصَرَفَ عَنْهُ". (د,ن)', 'അബുദർറ്(റ): നബി(സ) പറഞ്ഞു: "ഒരടിമ നിസ്കാരത്തിലായിരിക്കെ അവൻ തിരിഞ്ഞുകളയുന്നത് വരെ അല്ലാഹു അവന്റെ നേരെ തിരിയും. അവൻ മുഖം തിരിച്ചാൽ അല്ലാഹു അവനിൽ നിന്നും മുഖം തിരിക്കും." (ദ,ന)', 'أَبِي ذَرٍّ', 'അബുദർറ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 159', array['د','ن']::text[], array['ദ','ന']::text[], null, null, 750, 750, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ سَهْلِ بْنِ الْحَنْظَلِيَّةِ رَضِيَ اللهُ عَنْهُ قَالَ: ثُوِّبَ بِالصَّلَاةِ يَعْنِي صَلَاةَ الصُّبْحِ – فَجَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي وَهُوَ يَلْتَفِتُ إِلَى الشِّعْبِ. قَالَ أَبُو دَاوُدَ: وَكَانَ أَرْسَلَ فَارِسًا إِلَى الشِّعْبِ مِنَ اللَّيْلِ يَحْرُسُ. (د)', 'സഹ്ല്ബിനു ഹൻദലിയ്യ(റ): സുബ്ഹ് നിസ്കാരത്തിൽ ഇഖാമത്ത് വിളിക്കപ്പെട്ടു. അപ്പോൾ താഴ്വരയിലേക്ക് തിരിഞ്ഞു നോക്കിക്കൊണ്ട് നബി(സ) നിസ്കരിച്ചു. അബൂദാവൂദ് പറഞ്ഞു: കുതിരപ്പടയാളിയെ രാത്രി കാവലിനായി ആ താഴ്വരയിൽ നബി(സ) നിയോഗിച്ചിരുന്നു. (ദ)', 'سَهْلِ بْنِ الْحَنْظَلِيَّةِ', 'സഹ്ല്ബിനു ഹൻദലിയ്യ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 160', array['د']::text[], array['ദ']::text[], null, null, 750, 750, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَأَلْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْالْتِفَاتِ فِي الصَّلَاةِ؟ قَالَ: "هُوَ اخْتِلَاسٌ يَخْتَلِسُهُ الشَّيْطَانُ مِنْ صَلَاةِ الْعَبْدِ". (خ,د,ن)', 'ആഇശാ(റ): നിസ്കാരത്തിൽ തിരിഞ്ഞു നോക്കുന്നതിനെക്കുറിച്ച് ഞാൻ തിരുമേനി(സ)യോട് ചോദിച്ചു. തിരുമേനി(സ) അരുളി: "നിസ്കാരത്തിൽനിന്ന് പിശാച് തട്ടിയെടുത്തുകൊണ്ട് പോകുന്ന ഒരംശമാണത്." (ബു,ദ,ന)', 'عَائِشَةَ', 'ആഇശാ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 161', array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 750, 750, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: اشْتَكَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَصَلَّيْنَا وَرَاءَهُ وَهُوَ قَاعِدٌ، وَأَبُو بَكْرٍ يُكَبِّرُ يُسْمِعُ النَّاسَ تَكْبِيرَهُ، فَالْتَفَتَ إِلَيْنَا فَرَآنَا قِيَامًا، فَأَشَارَ إِلَيْنَا فَقَعَدْنَا، فَصَلَّيْنَا بِصَلَاتِهِ قُعُودًا، فَلَمَّا سَلَّمَ قَالَ: "إِنْ كُنْتُمْ آنِفًا تَفْعَلُونَ فِعْلَ فَارِسَ وَالرُّومِ، يَقُومُونَ عَلَى مُلُوكِهِمْ وَهُمْ قُعُودٌ، فَلَا تَفْعَلُوا، ائْتَمُّوا بِأَئِمَّتِكُمْ: إِنْ صَلَّى قَائِمًا فَصَلُّوا قِيَامًا، وَإِنْ صَلَّى قَاعِدًا فَصَلُّوا قُعُودًا". (ن)', 'ജാബിർ(റ): രോഗം വന്നപ്പോൾ ഇരുന്നുകൊണ്ട് നിസ്കരിക്കുകയായിരുന്ന റസൂൽ(സ)യുടെ പിന്നിൽ ഞങ്ങൾ നിസ്കരിച്ചു. അപ്പോൾ അബൂബക്കർ(റ) തക്ബീർ ചൊല്ലി ജനങ്ങളെ കേൾപ്പിച്ചു. നബി(സ) ഞങ്ങളിലേക്ക് തിരിഞ്ഞു നോക്കിയപ്പോൾ ഞങ്ങളെ നിൽക്കുന്നതായി കണ്ടു. അപ്പോൾ ഇരിക്കുവാനായി ഞങ്ങളോട് ആംഗ്യം കാണിച്ചു. അപ്പോൾ ഞങ്ങൾ അവിടത്തോടൊപ്പം ഇരുന്ന് നിസ്കരിച്ചു. സലാം വീട്ടിയതിന് ശേഷം പറഞ്ഞു: "പേർഷ്യക്കാരും, റോമക്കാരും ചെയ്യുന്നത് പോലെയാണ് നിങ്ങളിപ്പോൾ ചെയ്തു കൊണ്ടിരുന്നത്. അവർ തങ്ങളുടെ രാജാക്കന്മാർ ഇരിക്കെ എഴുന്നേറ്റ് നിൽക്കും. നിങ്ങൾ അപ്രകാരം ചെയ്യരുത്. നിങ്ങൾ നിങ്ങളുടെ നേതാക്കളെ പിന്തുടരുക. അവർ നിന്ന് നിസ്കരിക്കുമ്പോൾ നിങ്ങളും നിന്ന് നിസ്കരിക്കുക, ഇരുന്ന് നിസ്കരിക്കുമ്പോൾ നിങ്ങളും ഇരുന്ന് നിസ്കരിക്കുക." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 162', array['ن']::text[], array['ന']::text[], null, null, 751, 751, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَلْتَفِتُ فِي صَلَاتِهِ يَمِينًا وَشِمَالًا، وَلَا يَلْوِي عُنُقَهُ خَلْفَ ظَهْرِهِ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) നിസ്കരിക്കുമ്പോൾ ഇടത്തോട്ടും, വലത്തോട്ടും തിരിഞ്ഞിരുന്നു. അവിടുത്തെ കഴുത്ത് പിന്നോട്ട് തിരിഞ്ഞിരുന്നില്ല. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 163', array['ن']::text[], array['ന']::text[], null, null, 751, 751, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ جَرِيرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَنَظَرَ إِلَى الْقَمَرِ لَيْلَةً فَقَالَ: إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ كَمَا تَرَوْنَ هَذَا الْقَمَرَ لَا تُضَامُّونَ فِي رُؤْيَتِهِ فَإِنِ اسْتَطَعْتُمْ أَنْ لَا تُغْلَبُوا عَلَى صَلَاةٍ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا فَافْعَلُوا، ثُمَّ قَرَأَ: {وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ}. (خ)', 'ജരീർ(റ): ഞങ്ങൾ പ്രവാചകൻ(സ)യോടൊന്നിച്ചായിരിക്കെ, ചന്ദ്രനെ നോക്കിക്കൊണ്ട് അവിടുന്ന് പറഞ്ഞു: "നിശ്ചയം ഈ ചന്ദ്രനെ നിങ്ങൾ കാണുന്നതു പോലെ നിങ്ങളുടെ നാഥനെ നിങ്ങൾ വഴിയെ ദർശിക്കും. ആ ദർശനത്തിൽ യാതൊരു (സംശയവും) അവ്യക്തതയും ഉണ്ടായിരിക്കുകയില്ല. അതു കൊണ്ട് സൂര്യോദയത്തിന് മുമ്പും, സൂര്യാസ്തമയത്തിന് മുമ്പും ഉള്ള നിസ്കാരം നിർവ്വഹിക്കാൻ കഴിഞ്ഞെങ്കിൽ അതു നിങ്ങൾ നിർവ്വഹിച്ചു കൊള്ളുക". ഇങ്ങനെ പറഞ്ഞ ശേഷം ''നിന്റെ നാഥന്റെ മഹത്വത്തെയും പരിശുദ്ധിയെയും സൂര്യോദയത്തിനു മുമ്പും സൂര്യാസ്തമയത്തിനു മുമ്പും പ്രകീർത്തിച്ചു കൊള്ളുക'' എന്ന ഖുർആൻ വാക്യം തിരുമേനി(സ) എടുത്തുദ്ധരിച്ചു. (ബു)', 'جَرِيرٍ', 'ജരീർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 164', array['خ']::text[], array['ബു']::text[], null, 'സംശയവും', 751, 751, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَسْجِدَ فَرَأَى فِيهِ نَاسًا يُصَلُّونَ، رَافِعِي أَيْدِيهِمْ إِلَى السَّمَاءِ، فَقَالَ: "لَيَنْتَهِيَنَّ رِجَالٌ يَشْخَصُونَ أَبْصَارَهُمْ إِلَى السَّمَاءِ فِي الصَّلَاةِ، أَوْلَا تَرْجِعُ إِلَيْهِمْ أَبْصَارُهُمْ". (م,د,ن,جه)', 'ജാബിറുബ്നു സമുറ(റ): റസൂൽ(സ) പള്ളിയിൽ പ്രവേശിച്ചപ്പോൾ അവിടെ കുറച്ചാളുകൾ ആകാശേത്തേക്ക് കൈകളുയർത്തി നിസ്കരിക്കുന്നത് കണ്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിസ്കാരത്തിൽ കണ്ണുകൾ ആകാശത്തിലേക്കുയർത്തുന്ന ആളുകൾ അതിൽനിന്ന് പിന്തിരിയുക തന്നെവേണം. ഇല്ലെങ്കിൽ അവരുടെ കണ്ണുകൾ അവരിലേക്ക് മടങ്ങാതിരിക്കട്ടെ." (മു,ദ,ന,ജ)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 165', array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 751, 751, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا بَالُ أَقْوَامٍ يَرْفَعُونَ أَبْصَارَهُمْ فِي صَلَاتِهِمْ". فَاشْتَدَّ قَوْلُهُ فِي ذَلِكَ، فَقَالَ: "لَيَنْتَهُنَّ عَنْ ذَلِكَ أَوْ لَتُخْطَفَنَّ أَبْصَارُهُمْ". (ق,د,ن,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിസ്കാരത്തിൽ കണ്ണുകൾ ഉയർത്തുന്നവരുടെ അവസ്ഥയെന്ത്?" പിന്നീട് കടുത്ത സ്വരത്തിൽ പറഞ്ഞു: "അവർ അതിൽ നിന്നും പിന്മാറണം. ഇല്ലെങ്കിൽ അവരുടെ കണ്ണുകൾ റാഞ്ചിയെടുക്കപ്പെടട്ടെ." (ബു,മു,ദ,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 166', array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 752, 752, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ خَبَّابٍ رَضِيَ اللهُ عَنْهُ قِيلَ لَهُ: أَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ؟ قَالَ: نَعَمْ، قِيلَ لَهُ: بِمَ كُنْتُمْ تَعْرِفُونَ ذَاكَ؟ قَالَ: بِاضْطِرَابِ لِحْيَتِهِ. (خ)', 'ഖബ്ബാബ്(റ): അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: റസൂൽ(സ) ളുഹ്റിലും അസ്റിലും ഖുർആൻ പാരായണം ചെയ്തിരുന്നോ? അദ്ദേഹം പറഞ്ഞു: അതെ, അദ്ദേഹത്തോട് ചോദിച്ചു: അതെങ്ങനെയാണ് നിങ്ങൾ അറിഞ്ഞിരുന്നത്? അദ്ദേഹം പറഞ്ഞു: നബി(സ) യുടെ താടിയുടെ ഇളക്കത്താൽ ഞങ്ങളത് അറിഞ്ഞിരുന്നു. (ബു)', 'خَبَّابٍ', 'ഖബ്ബാബ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 167', array['خ']::text[], array['ബു']::text[], null, null, 752, 752, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ: أَنَّ رَجُلًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَدَّثَهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا كَانَ أَحَدُكُمْ فِي الصَّلَاةِ فَلَا يَرْفَعْ بَصَرَهُ إِلَى السَّمَاءِ، أَنْ يُلْتَمَعَ بَصَرُهُ". (ن)', 'ഉബൈദുല്ലാഹിബ്നു അബ്ദുല്ലാ(റ): നബി(സ)യുടെ അനുചരരിൽ പെട്ട ഒരാൾ പറഞ്ഞു: നബി(സ) പറയുന്നത് (അദ്ദേഹം) കേട്ടു: "നിങ്ങളിലാരെങ്കിലും നിസ്കാരത്തിലായിരിക്കെ ദൃഷ്ടികൾ ആകാശത്തേക്ക് ഉയർത്തരുത്. കാരണം അവന്റെ കണ്ണ് റാഞ്ചപ്പെട്ടേക്കാം." (ന)', 'عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ', 'ഉബൈദുല്ലാഹിബ്നു അബ്ദുല്ലാ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 168', array['ن']::text[], array['ന']::text[], null, null, 752, 752, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَزَادَ أَوْ نَقَصَ، فَقِيلَ لَهُ: يَا رَسُولَ اللهِ، أَزِيدَ فِي الصَّلَاةِ شَيْءٌ؟ قَالَ: "إِنَّمَا أَنَا بَشَرٌ، أَنْسَى كَمَا تَنْسَوْنَ. فَإِذَا نَسِيَ أَحَدُكُمْ فَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ". ثُمَّ تَحَوَّلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَجَدَ سَجْدَتَيْنِ. (م,د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) നിസ്കരിച്ചപ്പോൾ കൂടുകയോ കുറയുകയോ ചെയ്തു. അപ്പോൾ തിരുനബി(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരെ, നിസ്ക്കാരത്തിൽ വല്ലതും വർദ്ധിപ്പിച്ചിട്ടുണ്ടോ? അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "ഞാനും നിങ്ങളെപ്പോലെ ഒരു മനുഷ്യനാണ്; നിങ്ങൾക്ക് മറവി സംഭവിക്കുന്ന പോലെ ഞാനും മറക്കുന്നു. നിങ്ങളിലാരെങ്കിലും മറന്നാൽ ഇരുന്നേടത്തുനിന്ന് തന്നെ രണ്ട് സുജൂദ് നിർവ്വഹിക്കുക." ശേഷം നബി(സ) അൽപം മാറിക്കൊണ്ട് രണ്ട് സുജൂദ് നിർവ്വഹിച്ചു. (മു,ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 169', array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 752, 752, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ أَنَّهُ سُئِلَ: أَحَدُنَا يُصَلِّي فَلَا يَدْرِي كَمْ صَلَّى، فَقَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا صَلَّى أَحَدُكُمْ فَلَمْ يَدْرِ كَمْ صَلَّى، فَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ". (د,ت)', 'അബൂസഈദിൽ ഖുദ്രി(റ): അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: ഞങ്ങളിലൊരാൾ നിസ്കരിക്കുകയും, എത്രയാണ് നിസ്കരിച്ചതെന്ന് അറിയാതിരിക്കുകയും ചെയ്താൽ എന്ത് ചെയ്യണം? അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ട്: "നിങ്ങളിലൊരാൾ നിസ്കരിക്കുകയും എത്രയാണ് നിസ്കരിച്ചതെന്ന് അറിയാതിരിക്കുകയും ചെയ്താൽ അവൻ ഇരുന്നേടത്ത് നിന്ന് തന്നെ രണ്ട് സുജൂദ് ചെയ്യട്ടെ." (ദ,തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 170', array['د','ت']::text[], array['ദ','തു']::text[], null, null, 752, 752, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ انْصَرَفَ مِنَ الرَّكْعَتَيْنِ مِنْ صَلَاةِ الْمَكْتُوبَةِ، فَقَالَ لَهُ رَجُلٌ: أَقْصِرَتِ الصَّلَاةُ يَا رَسُولَ اللهِ أَمْ نَسِيتَ؟ قَالَ: "كُلُّ ذَلِكَ لَمْ أَفْعَلْ". فَقَالَ النَّاسُ: قَدْ فَعَلْتَ ذَلِكَ يَا رَسُولَ اللهِ. فَرَكَعَ رَكْعَتَيْنِ أُخْرَيَيْنِ، ثُمَّ انْصَرَفَ، وَلَمْ يَسْجُدْ سَجْدَتَيِ السَّهْوِ. وَفِي رِوَايَةٍ: ثُمَّ سَجَدَ سَجْدَتَيْنِ وَهُوَ جَالِسٌ بَعْدَ التَّسْلِيمِ. وَفِي رِوَايَةٍ: ثُمَّ سَجَدَ سَجْدَتَيِ السَّهْوِ بَعْدَ مَا سَلَّمَ. (م,د,ن)', 'അബൂഹുറൈറ(റ): നിശ്ചയം, റസൂൽ(സ) ഫർള് നിസ്കാരത്തിൽ നിന്ന് രണ്ട് റകഅത്ത് നിർവ്വഹിച്ചശേഷം വിരമിച്ചു. അപ്പോൾ ഒരാൾ തിരുമേനി(സ)യോട് ചോദിച്ചു: പ്രവാചകരെ; താങ്കൾ നിസ്ക്കാരം ചുരുക്കിയോ, അതോ മറന്നോ? അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "അത് രണ്ടും ഞാൻ ചെയ്തിട്ടില്ല." അപ്പോൾ ജനങ്ങൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, താങ്കൾ അങ്ങിനെ ചെയ്തിട്ടുണ്ട്. അപ്പോൾ പ്രവാചകൻ(സ) എഴുന്നേറ്റ് രണ്ട് റകഅത്ത് കൂടി നിർവ്വഹിച്ചു. പിന്നീട് വിരമിച്ചു. സഹ്വിന്റെ സുജൂദ് നിർവ്വഹിച്ചില്ല. മറ്റൊരു റിപ്പോർട്ടിൽ: തിരുമേനി(സ) സലാം വീട്ടിയ ശേഷം ഇരുന്നുകൊണ്ട് രണ്ട് സുജൂദുകൾ നിർവ്വഹിച്ചു. മറ്റൊരു നിവേദനം: സലാം വീട്ടിയ ശേഷം അവിടുന്ന് മറവിയുടെ രണ്ട് സുജൂദുകൾ ചെയ്തു. (മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 171', array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 752, 753, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=181), 1, 'وَفِي رِوَايَةٍ: ثُمَّ سَجَدَ سَجْدَتَيْنِ وَهُوَ جَالِسٌ بَعْدَ التَّسْلِيمِ.', 'മറ്റൊരു നിവേദനിൽ: തിരുമേനി(സ) സലാം വീട്ടിയ ശേഷം ഇരുന്നുകൊണ്ട് രണ്ട് സുജൂദുകൾ നിർവ്വഹിച്ചു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=181), 2, 'وَفِي رِوَايَةٍ: ثُمَّ سَجَدَ سَجْدَتَيِ السَّهْوِ بَعْدَ مَا سَلَّمَ. (م,د,ن)', 'മറ്റൊരു നിവേദനം: സലാം വീട്ടിയ ശേഷം അവിടുന്ന് മറവിയുടെ രണ്ട് സുജൂദുകൾ ചെയ്തു. (മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ رَكْعَتَيْنِ، فَقِيلَ لَهُ: نَقَصَتِ الصَّلَاةُ؟ فَصَلَّى رَكْعَتَيْنِ، ثُمَّ سَلَّمَ ثُمَّ سَجَدَ سَجْدَتَيْنِ. (خ,د,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ളുഹ്ർ നിസ്കരിച്ചു രണ്ട് റകഅത്ത് കഴിഞ്ഞപ്പോൾ സലാം വീട്ടി. തിരുമേനി(സ)യോട് ഒരാൾ ചോദിച്ചു: പ്രവാചകരെ, താങ്കൾ നിസ്കാരം ചുരുക്കിയോ? അപ്പോൾ തിരുമേനി(സ) രണ്ട് റക്അത്ത് കൂടി നിർവ്വഹിച്ച് സലാം വീട്ടിയ ശേഷം രണ്ട് സുജൂദ് ചെയ്തു. (ബു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 172', array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 753, 753, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِحْدَى صَلَاتَيِ الْعَشِيِّ رَكْعَتَيْنِ، ثُمَّ سَلَّمَ، ثُمَّ قَامَ إِلَى خَشَبَةٍ كَانَتْ فِي الْمَسْجِدِ يَسْتَنِدُ إِلَيْهَا، فَخَرَجَ سَرَعَانُ النَّاسِ يَقُولُونَ: قَصُرَتِ الصَّلَاةُ. وَفِي الْقَوْمِ أَبُو بَكْرٍ وَعُمَرُ، فَهَابَاهُ أَنْ يَقُولَا لَهُ شَيْئًا، وَفِي الْقَوْمِ رَجُلٌ طَوِيلُ الْيَدَيْنِ، يُسَمَّى: ذَا الْيَدَيْنِ. فَقَالَ: يَا رَسُولَ اللهِ، أَقَصُرَتِ الصَّلَاةُ أَمْ نَسِيتَ؟ فَقَالَ: "لَمْ تَقْصُرْ وَلَمْ أَنْسَ". قَالَ: فَإِنَّمَا صَلَّيْتَ رَكْعَتَيْنِ فَقَالَ: "أَكَمَا يَقُولُ ذُو الْيَدَيْنِ؟" فَقَالُوا: نَعَمْ، فَقَامَ فَصَلَّى رَكْعَتَيْنِ ثُمَّ سَلَّمَ، ثُمَّ سَجَدَ سَجْدَتَيْنِ ثُمَّ سَلَّمَ. (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ഞങ്ങളുമായി രാത്രിയിലെ ഒരു നിസ്കാരം രണ്ട് റക്അത്ത് നിർവ്വഹിച്ചു. എന്നിട്ട് സലാം വീട്ടി. ശേഷം പള്ളിയിലെ മരത്തൂണിലേക്ക് അവിടെ ഇരിക്കാൻ പോയി. ജനങ്ങളും പെട്ടെന്ന് പുറത്തേക്കുവന്നു. പെട്ടെന്ന് പുറത്തു പോയവർ പറയുന്നുണ്ടായിരുന്നു: നിസ്കാരം ചുരുക്കപ്പെട്ടിട്ടുണ്ട്. അവരിൽ അബൂബക്കർ(റ)വം ഉമർ(റ)വും ഉണ്ടായിരുന്നു. അവർ നബി(സ)യോട് എന്തെങ്കിലും പറയാൻ ഭയന്നു. അക്കൂട്ടത്തിൽ കൈകൾ നീളമുള്ള ഒരാൾ ഉണ്ടായിരുന്നു.''ദുൽ യദൈനി'' എന്ന് വിളിക്കപ്പെടുന്ന അദ്ദേഹം ചോദിച്ചു. അല്ലാഹുവിന്റെ ദൂതരെ, നിസ്കാരം ചുരുങ്ങിയതാണോ, അതോ അങ്ങ് മറന്നതാണോ? പ്രവാചകൻ(സ) പറഞ്ഞു: "നിസ്കാരം ചുരുങ്ങിയിട്ടുമില്ല, ഞാൻ മറന്നിട്ടുമില്ല." ദുൽയദൈനി പറഞ്ഞു: എന്നിട്ട് താങ്കളെന്താണ് രണ്ട് റക്അത്ത് നിസ്കരിച്ചത്? പ്രവാചകൻ(സ) ചോദിച്ചു: "ദുൽയദൈനി പറഞ്ഞതുപോലെ തന്നെയാണോ?" അവർ പറഞ്ഞു: അതെ. അപ്പോൾ പ്രവാചകൻ(സ) എഴുന്നേറ്റ് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. എന്നിട്ട് സലാം വീട്ടി. പിന്നീട് രണ്ട് സുജൂദ് ചെയ്തു. ശേഷം സലാം വീട്ടി. (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 173', array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 753, 753, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ عِمْرَانَ بْنِ الْحُصَيْنِ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَلَّمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي ثَلَاثِ رَكَعَاتٍ مِنَ الْعَصْرِ، ثُمَّ قَامَ فَدَخَلَ الْحُجْرَةَ، فَقَامَ الْخِرْبَاقُ رَجُلٌ بَسِيطُ الْيَدَيْنِ – فَنَادَى: يَا رَسُولَ اللهِ، أَقَصُرَتِ الصَّلَاةُ؟ فَخَرَجَ مُغْضَبًا يَجُرُّ إِزَارَهُ، فَسَأَلَ فَأُخْبِرَ، فَصَلَّى تِلْكَ الرَّكْعَةَ الَّتِي كَانَ تَرَكَ ثُمَّ سَلَّمَ، ثُمَّ سَجَدَ سَجْدَتَيْنِ ثُمَّ سَلَّمَ. (م,د,ت,ن,جه)', 'ഇംറാനുബ്നുൽ ഹുസൈൻ(റ): അസ്വർ നിസ്കാരത്തിൽ റസൂൽ(സ) മൂന്ന് റക്അത്തിന് ശേഷം സലാം വീട്ടി. പിന്നീട് എഴുന്നേറ്റ് മുറിയിൽ പ്രവേശിച്ചു. അപ്പോൾ നീണ്ട കൈകളുള്ള ഖിർബാക്ക് എഴുന്നേറ്റ് വന്ന് വിളിച്ചു ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരെ, നിസ്കാരം ചുരുക്കപ്പെട്ടിട്ടുണ്ടോ? അപ്പോൾ ദേഷ്യത്തോടെ തന്റെ വിരിയും വലിച്ചുകൊണ്ട് പ്രവാചകൻ(സ) പുറത്ത് വന്നു. കാര്യം അന്വേഷിച്ചു. വിഷയം പറഞ്ഞപ്പോൾ നബി(സ) വിട്ടുപോയ റക്അത്ത് നിസ്കരിച്ച ശേഷം സലാം വീട്ടി. എന്നിട്ട് രണ്ട് സുജൂദ് ചെയ്തു, വീണ്ടും സലാം വീട്ടി. (മു,ദ,തു,ന,ജ)', 'عِمْرَانَ بْنِ الْحُصَيْنِ', 'ഇംറാനുബ്നുൽ ഹുസൈൻ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 174', array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 753, 754, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ مُعَاوِيَةَ بْنِ حُدَيْجٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى يَوْمًا، فَسَلَّمَ وَقَدْ بَقِيَتْ مِنَ الصَّلَاةِ رَكْعَةٌ، فَأَدْرَكَهُ رَجُلٌ، فَقَالَ: نَسِيتَ مِنَ الصَّلَاةِ رَكْعَةً. فَرَجَعَ فَدَخَلَ الْمَسْجِدَ، وَأَمَرَ بِلَالًا فَأَقَامَ الصَّلَاةَ، فَصَلَّى لِلنَّاسِ رَكْعَةً، فَأَخْبَرْتُ بِذَلِكَ النَّاسَ، فَقَالُوا لِي: أَتَعْرِفُ الرَّجُلَ؟ قُلْتُ:لَا، إِلَّا أَنْ أَرَاهُ، فَمَرَّ بِي، فَقُلْتُ: هَذَا هُوَ، قَالُوا: هَذَا طَلْحَةُ بْنُ عُبَيْدِ اللهِ. (د,ن)', 'മുആവിയത്തുബ്നു ഹുദൈജ്(റ): റസൂൽ(സ) തന്റെ നിസ്കാരത്തിൽ ഒരു റക്അത്ത് ബാക്കിയിരിക്കെ സലാം വീട്ടി. അപ്പോൾ അത് ഒരാൾ ഓർമ്മിപ്പിച്ചു. അയാൾ പറഞ്ഞു; താങ്കൾ നിസ്കാരത്തിൽ ഒരു റക്അത്ത് മറന്നിരിക്കുന്നു. അങ്ങിനെ തിരിച്ചു വന്ന് പള്ളിയിലെത്തി, ബിലാലിനോട് ഇഖാമത്ത് കൊടുക്കാൻ കൽപിച്ചു. എന്നിട്ട് ജനങ്ങൾക്കൊപ്പം ഒരു റക്അത്ത് നിസ്കരിച്ചു. അത് ഞാൻ ജനങ്ങളോട് പറഞ്ഞു. അവർ ചോദിച്ചു: ആ മനുഷ്യനെ അറിയുമോ? ഞാൻ പറഞ്ഞു: കണ്ടാലല്ലാതെ അറിയില്ല. അങ്ങനെ അദ്ദേഹം എന്റെ അടുത്തു കൂടെ നടന്നപ്പോൾ ഞാൻ പറഞ്ഞു: ഇതാ ഇയാളാണ്, അവർ പറഞ്ഞു: ഇത് ത്വൽഹത്തുബ്നു ഉബൈദുല്ല(റ)യാണ്. (ദ,ന)', 'مُعَاوِيَةَ بْنِ حُدَيْجٍ', 'മുആവിയത്തുബ്നു ഹുദൈജ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 175', array['د','ن']::text[], array['ദ','ന']::text[], null, null, 754, 754, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنِ ابْنِ بُحَيْنَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى صَلَاةً، أَظُنُّ أَنَّهَا الظُّهْرُ، فَلَمَّا كَانَ فِي الثَّانِيَةِ قَامَ قَبْلَ أَنْ يَجْلِسَ، فَلَمَّا كَانَ قَبْلَ أَنْ يُسَلِّمَ سَجَدَ سَجْدَتَيْنِ. وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَامَ فِي ثِنْتَيْنِ مِنَ الظُّهْرِ، نَسِيَ الْجُلُوسَ، حَتَّى إِذَا فَرَغَ مِنْ صَلَاتِهِ إِلَّا أَنْ يُسَلِّمَ سَجَدَ سَجْدَتَيِ السَّهْوِ وَسَلَّمَ. (ق,د,ت,ن,جه)', 'ഇബ്നുബുഹൈന(റ): നബി(സ) നിസ്കാരം നിർവ്വഹിക്കുകയായിരുന്നു. ളുഹ്റാണെന്നാണ് ഞാൻ കരുതുന്നത്. രണ്ടാമത്തെ റക്അത്തിൽ ഇരിക്കുന്നതിന് മുമ്പെ എഴുന്നേറ്റു. പിന്നീട് സലാം വീട്ടുന്നതിന് മുമ്പെ രണ്ട് സുജൂദ് ചെയ്തു. മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) ളുഹ്റിൽ രണ്ട് റക്അത്ത് കഴിഞ്ഞ് ഇരിക്കാൻ മറന്ന് എഴുന്നേറ്റു. നിസ്കാരത്തിൽ സലാം വീട്ടുന്നതിന് മുമ്പ് മറവിയുടെ രണ്ട് സുജൂദ് നിർവ്വഹിച്ചു. ശേഷം സലാം വീട്ടി. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ بُحَيْنَةَ', 'ഇബ്നുബുഹൈന(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 176', array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 754, 754, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=186), 1, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَامَ فِي ثِنْتَيْنِ مِنَ الظُّهْرِ، نَسِيَ الْجُلُوسَ، حَتَّى إِذَا فَرَغَ مِنْ صَلَاتِهِ إِلَّا أَنْ يُسَلِّمَ سَجَدَ سَجْدَتَيِ السَّهْوِ وَسَلَّمَ. (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) ളുഹ്റിൽ രണ്ട് റക്അത്ത് കഴിഞ്ഞ് ഇരിക്കാൻ മറന്ന് എഴുന്നേറ്റു. നിസ്കാരത്തിൽ സലാം വീട്ടുന്നതിന് മുമ്പ് മറവിയുടെ രണ്ട് സുജൂദ് നിർവ്വഹിച്ചു. ശേഷം സലാം വീട്ടി. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا شَكَّ أَحَدُكُمْ فِي الثِّنْتَيْنِ وَالْوَاحِدَةِ فَلْيَجْعَلْهَا وَاحِدَةً، وَإِذَا شَكَّ فِي الثِّنْتَيْنِ وَالثَّلَاثِ فَلْيَجْعَلْهَا ثِنْتَيْنِ، وَإِذَا شَكَّ فِي الثَّلَاثِ وَالْأَرْبَعِ فَلْيَجْعَلْهَا ثَلَاثًا، ثُمَّ لِيُتِمَّ مَا بَقِيَ مِنْ صَلَاتِهِ حَتَّى يَكُونَ الْوَهْمُ فِي الزِّيَادَةِ، ثُمَّ يَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ قَبْلَ أَنْ يُسَلِّمَ". (ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): അബ്ദുറഹ്മാനുബ്നു ഔഫ്(റ) പറയുന്നു, റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിങ്ങളിലൊരാൾക്ക് ഒരു റക്അതാണോ അതോ രണ്ടാണോ നിർവ്വഹിച്ചത് എന്ന് സംശയമുണ്ടായാൽ ഒന്ന് സ്വീകരിക്കട്ടെ, രണ്ടോ മൂന്നോ എന്ന് സംശയമുണ്ടായാൽ രണ്ട് സ്വീകരിക്കട്ടെ, മൂന്നോ നാലോ എന്ന് സംശയമുണ്ടായാൽ മൂന്ന് സ്വീകരിക്കട്ടെ. പിന്നീട് വർദ്ധിച്ചതിനെ കുറിച്ചുള്ള സംശയം ഉണ്ടായിരിക്കെ നിസ്കാരത്തിൽ ബാക്കിയുള്ളത് പൂർത്തിയാക്കട്ടെ. എന്നിട്ട് സലാം വീട്ടുന്നതിന്നു മുമ്പുള്ള ഇരുത്തത്തിൽ രണ്ട് സുജൂദ് നിർവ്വഹിക്കട്ടെ." (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 177', array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 754, 755, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا شَكَّ أَحَدُكُمْ فِي صَلَاتِهِ فَلْيُلْغِ الشَّكَّ وَلْيَبْنِ عَلَى الْيَقِينِ، فَإِذَا اسْتَيْقَنَ التَّمَامَ سَجَدَ سَجْدَتَيْنِ، فَإِنْ كَانَتْ صَلَاتُهُ تَامَّةً كَانَتِ الرَّكْعَةُ نَافِلَةً، وَإِنْ كَانَتْ نَاقِصَةً كَانَتِ الرَّكْعَةُ لِتَمَامِ صَلَاتِهِ، وَكَانَتِ السَّجْدَتَانِ رَغْمَ أَنْفِ الشَّيْطَانِ". (م,د,ن,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാർക്കെങ്കിലും നിസ്കാരത്തിൽ സംശയമുണ്ടായാൽ സംശയം ഒഴിവാക്കുകയും ഉറപ്പുള്ളതിനെ അവലംഭിക്കുകയും ചെയ്യുക. പൂർത്തിയായി എന്ന് ഉറപ്പായാൽ രണ്ട് സുജൂദ് ചെയ്യുക. അയാളുടെ നിസ്കാരം പൂർണ്ണമായിരുന്നു എങ്കിൽ പിന്നീടുള്ള റക്അത്ത് ഐഛികമായിരിക്കും. ഇനി കുറവായിരുന്നെങ്കിൽ ആ റക്അത്ത് അയാളുടെ നിസ്കാരം പൂർണ്ണമാക്കും. പിശാചിന്റെ ബാധയിൽ നിന്നുള്ള പിൻതിരിയലാണ് രണ്ട് സുജൂദുകൾ." (മു,ദ,ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 178', array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 755, 755, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاةً لَا نَدْرِي: أَزَادَ أَوْ نَقَصَ، فَسَأَلَ فَحَدَّثْنَاهُ فَثَنَى رِجْلَهُ وَاسْتَقْبَلَ الْقِبْلَةَ وَسَجَدَ سَجْدَتَيْنِ، ثُمَّ سَلَّمَ. ثُمَّ أَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ: "لَوْ حَدَثَ فِي الصَّلَاةِ شَيْءٌ لَأَنْبَأْتُكُمُوهُ، وَإِنَّمَا أَنَا بَشَرٌ أَنْسَى كَمَا تَنْسَوْنَ، فَإِذَا نَسِيتُ فَذَكِّرُونِي. وَأَيُّكُمْ مَا شَكَّ فِي الصَّلَاةِ فَلْيَتَحَرَّ أَقْرَبَ ذَلِكَ مِنَ الصَّوَابِ، فَيُتِمَّ عَلَيْهِ وَيُسَلِّمَ وَيَسْجُدَ سَجْدَتَيْنِ". (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) ഒരു നിസ്കാരത്തിൽ കൂട്ടിയോ, കുറച്ചോ എന്ന് ഞങ്ങൾക്ക് സംശയമായി. പ്രവാചകൻ(സ) ചോദിച്ചപ്പോൾ ഞങ്ങളത് പറഞ്ഞു കൊടുത്തു. ഉടനെ നബി(സ) കാൽ മടക്കി ഖിബ്ലയെ അഭിമുഖീകരിച്ചു കൊണ്ട് രണ്ട് സുജൂദുകൾ നിർവ്വഹിച്ചു. പിന്നീട് സലാം വീട്ടി. പിന്നീട് ഞങ്ങളെ അഭിമുഖീകരിച്ചുകൊണ്ട് പറഞ്ഞു: "നിസ്കാരത്തിൽ വല്ലതും സംഭവിച്ചാൽ ഞാനത് നിങ്ങൾക്ക് അറിയിച്ചു തരും. ഞാനും മനുഷ്യനാണ്, നിങ്ങൾ മറക്കും പോലെ ഞാനും മറക്കും. ഞാൻ മറന്നാൽ എന്നെ ഉണർത്തുക. നിങ്ങളിൽ ആർക്കെങ്കിലും നിസ്കാരത്തിൽ സംശയം ഉണ്ടായാൽ ശരിയാവാൻ കൂടുതൽ സാധ്യതയുള്ളത് ഉറപ്പിക്കുക. പിന്നീട് പൂർത്തിയാക്കിയ ശേഷം സലാം വീട്ടി രണ്ട് സുജൂദ് ചെയ്യുക." (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 179', array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 755, 755, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا شَكَّ أَحَدُكُمْ فِي الصَّلَاةِ فَلْيَتَحَرَّ الصَّوَابَ، ثُمَّ يَسْجُدْ سَجْدَتَيْنِ". (ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾക്ക് തന്റെ നിസ്കാരത്തിൽ സംശയമുണ്ടായാൽ ശരിയാവാൻ സാധ്യതയുള്ളത് ഉറപ്പിക്കുക. ശേഷം രണ്ട് സുജൂദ് ചെയ്യുക." (ന,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 180', array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 755, 755, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ عَطَاءِ بْنِ يَسَارٍ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا شَكَّ أَحَدُكُمْ فِي صَلَاتِهِ فَلَمْ يَدْرِ كَمْ صَلَّى: أَثَلَاثًا أَمْ أَرْبَعًا، فَلْيُصَلِّي رَكْعَةً وَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ قَبْلَ التَّسْلِيمِ، فَإِنْ كَانَتِ الرَّكْعَةُ الَّتِي صَلَّى خَامِسَةً شَفَعَهَا بِهَاتَيْنِ، السَّجْدَتَيْنِ وَإِنْ كَانَتْ رَابِعَةً فَالسَّجْدَتَانِ تَرْغِيمٌ لِلشَّيْطَانِ". (د)', 'അത്വാഉബ്നു യസാർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാർക്കെങ്കിലും നിസ്കാരത്തിൽ സംശയമുണ്ടാവുകയും, എത്രയാണ് നിസ്കരിച്ചതെന്ന് അറിയാതിരിക്കുകയും ചെയ്താൽ, അഥവാ (നാലു റക്അത്തുള്ളത്) മൂന്നോ നാലോ എന്ന് സംശയിച്ചാൽ ഒരു റക്അത്ത് കൂടി നിർവ്വഹിക്കുക, എന്നിട്ട് സലാം വീട്ടുന്നതിന് മുമ്പായി രണ്ട് സുജൂദുകൾ നിർവ്വഹിക്കുക. അയാളുടെ ആ റക്അത്ത് അഞ്ചാമത്തേതാകുമെങ്കിൽ രണ്ട് സുജൂദുകൾ അതിനെ പൊറുക്കുന്നു. അത് നാലാമത്തേതാണങ്കിൽ സുജൂദുകൾ പിശാചിൽ നിന്നുള്ള വിമോചനമാണ്." (ദ)', 'عَطَاءِ بْنِ يَسَارٍ', 'അത്വാഉബ്നു യസാർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 181', array['د']::text[], array['ദ']::text[], null, null, 755, 756, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ زَيْدِ بْنِ أَسْلَمَ قَالَ: إِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا شَكَّ أَحَدُكُمْ فِي صَلَاتِهِ، فَإِنِ اسْتَيْقَنَ أَنْ قَدْ صَلَّى ثَلَاثًا فَلْيَقُمْ فَلْيُتِمَّ رَكْعَةً بِسُجُودِهَا، ثُمَّ يَجْلِسْ فَيَتَشَهَّدْ، فَإِذَا فَرَغَ فَلَمْ يَبْقَ إِلَّا أَنْ يُسَلِّمَ فَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ، ثُمَّ لِيُسَلِّمْ". (د)', 'സൈദുബ്നു അസ്ലം(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ ആർക്കെങ്കിലും തന്റെ നിസ്കാരത്തിൽ സംശയമുണ്ടായാൽ താൻ നിസ്കരിച്ചത് മൂന്നാണെന്ന് അയാൾക്കുറപ്പായാൽ ഒരു റക്അത്ത് അതിന്റെ സുജൂദുകൾ അടക്കം അയാൾ പൂർത്തീകരിക്കട്ടെ. പിന്നീട് ഇരുന്ന് തശഹ്ഹുദ് നിർവ്വഹിക്കട്ടെ, അത് കഴിഞ്ഞ് നിസ്ക്കാരം അവസാനിപ്പിക്കാൻ സലാം വീട്ടൽ മാത്രം അവശേഷിക്കുമ്പോൾ രണ്ട് സുജൂദുകൾ നിർവ്വഹിച്ച് സലാം വീട്ടട്ടെ." (ദ)', 'زَيْدِ بْنِ أَسْلَمَ قَالَ', 'സൈദുബ്നു അസ്ലം(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 182', array['د']::text[], array['ദ']::text[], null, null, 756, 756, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ قَالَ: لَمْ يَسْجُدْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَئِذٍ قَبْلَ السَّلَامِ وَلَا بَعْدَهُ. (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ആ ദിവസം സലാം വീട്ടുന്നതിന് മുമ്പോ ശേഷമോ സുജൂദ് ചെയ്തിട്ടില്ല. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 183', array['ن']::text[], array['ന']::text[], null, null, 756, 756, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ عَبْدِ اللهِ بْنِ جَعْفَرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ شَكَّ فِي صَلَاتِهِ فَلْيَسْجُدْ سَجْدَتَيْنِ بَعْدَ مَا يُسَلِّمُ". وَفِي رِوَايَةٍ: "بَعْدَ التَّسْلِيمِ". وَفِي رِوَايَةٍ: "وَهُوَ جَالِسٌ". (ن)', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആർക്കെങ്കിലും തന്റെ നിസ്കാരത്തിൽ സംശയം തോന്നിയാൽ അയാൾ സലാം വീട്ടിയ ശേഷം രണ്ട് സുജൂദുകൾ നിർവ്വക്കട്ടെ." മറ്റൊരു നിവേദനം: സലാമിനു ശേഷം. മറ്റൊരു നിവേദനം: ഇരുന്നുകൊണ്ട്. (ന)', 'عَبْدِ اللهِ بْنِ جَعْفَرٍ', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 184', array['ن']::text[], array['ന']::text[], null, null, 756, 756, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=194), 1, 'وَفِي رِوَايَةٍ: "بَعْدَ التَّسْلِيمِ".', 'മറ്റൊരു നിവേദനം: സലാമിനു ശേഷം.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=194), 2, 'وَفِي رِوَايَةٍ: "وَهُوَ جَالِسٌ". (ن)', 'മറ്റൊരു നിവേദനം: ഇരുന്നുകൊണ്ട്. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ أَحَدَكُمْ إِذَا قَامَ يُصَلِّي جَاءَهُ الشَّيْطَانُ فَلَبَسَ عَلَيْهِ صَلَاتَهُ، حَتَّى لَا يَدْرِيَ كَمْ صَلَّى، فَإِذَا وَجَدَ أَحَدُكُمْ ذَلِكَ فَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ നിസ്കാരത്തിന് നിന്നാൽ പിശാച് വന്ന് സംശയമുണ്ടാക്കും, അങ്ങിനെ എത്ര നിസ്കരിച്ചു എന്ന് അറിയാതാവും. നിങ്ങളിലാർക്കെങ്കിലും അങ്ങിനെ സംഭവിച്ചാൽ ഇരുന്നിടത്ത്നിന്ന് തന്നെ രണ്ട് സുജൂദ് നിർവ്വഹിക്കട്ടെ." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 185', array['ن']::text[], array['ന']::text[], null, null, 756, 756, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا نُودِيَ لِلصَّلَاةِ أَدْبَرَ الشَّيْطَانُ لَهُ ضُرَاطٌ، فَإِذَا قُضِيَ التَّثْوِيبُ أَقْبَلَ حَتَّى يَخْطِرَ بَيْنَ الْمَرْءِ وَقَلْبِهِ، حَتَّى لَا يَدْرِيَ كَمْ صَلَّى، فَإِذَا رَأَى أَحَدُكُمْ ذَلِكَ فَلْيَسْجُدْ سَجْدَتَيْنِ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിസ്കാരത്തിന് വിളിക്കപ്പെട്ടാൽ പിശാച് കീഴ്വായ്പുറത്ത് വിട്ട്കൊണ്ട് പിൻതിരിഞ്ഞോടും. ശേഷം ഇഖാമത് വിളിക്കപ്പെട്ടാൽ ഒരാൾക്കും അയാളുടെ മനസ്സിനും ഇടയിൽ മറ സൃഷ്ടിച്ചു കൊണ്ട് തിരിച്ച് വരും, അയാൾ എത്രയാണ് നിസ്കരിച്ചതെന്ന് അറിയാത്ത അവസ്ഥയുണ്ടാകുന്നു, അങ്ങനെ ആർക്കെങ്കിലും അനുഭവപ്പെട്ടാൽ അവർ രണ്ട് സുജൂദ് ചെയ്യട്ടെ." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 186', array['ن']::text[], array['ന']::text[], null, null, 756, 756, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا كُنْتَ فِي صَلَاةٍ فَشَكَكْتَ فِي ثَلَاثٍ أَوْ أَرْبَعٍ وَأَكْبَرُ ظَنِّكَ عَلَى أَرْبَعٍ تَشَهَّدْتَ ثُمَّ سَجَدْتَ سَجْدَتَيْنِ وَأَنْتَ جَالِسٌ قَبْلَ أَنْ تُسَلِّمَ، ثُمَّ تَشَهَّدْتَ أَيْضًا، ثُمَّ تُسَلِّمُ". (د,ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നീ നിസ്കാരത്തിലായിരിക്കെ മൂന്നോ നാലോ നിസ്കരിച്ചത് എന്ന് സംശയമുണ്ടാവുകയും, നാല് കൂടുതൽ ഉറപ്പുള്ളതാവുകയും ചെയ്താൽ തശഹഹുദിന് ശേഷം രണ്ട് സുജൂദ് ചെയ്യുക, സലാം വീട്ടുന്നതിന് മുമ്പ് വീണ്ടും തശഹഹുദ് ചൊല്ലിയ ശേഷം സലാം വീട്ടുക." (ദ,ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 187', array['د','ن']::text[], array['ദ','ന']::text[], null, null, 757, 757, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا صَلَّى أَحَدُكُمْ فَلَمْ يَدْرِ زَادَ أَمْ نَقَصَ، فَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ قَاعِدٌ، فَإِذَا أَتَاهُ الشَّيْطَانُ فَقَالَ: إِنَّكَ قَدْ أَحْدَثْتَ، فَلْيَقُلْ: كَذَبْتَ، إِلَّا مَا وَجَدَ رِيحًا بِأَنْفِهِ أَوْ صَوْتًا بِأُذُنِهِ". (د,ت,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ നിസ്കരിക്കുകയും, കുറഞ്ഞോ കൂടിയോ എന്ന് അറിയാതിരിക്കുകയും ചെയ്താൽ അയാൾ ഇരുത്തത്തിലായിരിക്കെ തന്നെ രണ്ട് സുജൂദുകൾ നിർവ്വഹിക്കട്ടെ, അയാളുടെ അടുത്ത് പിശാച് വന്നിരുന്ന് ഇപ്രകാരം പറയും: "നീ അശുദ്ധിയിലായിരിക്കുന്നു. അപ്പോൾ നീ പറയുക: നീ കളവാണ് പറഞ്ഞത്. നിന്റെ മൂക്കിൽ അതിന്റെ വാസന എത്തിയിട്ടില്ലെങ്കിൽ, അല്ലെങ്കിൽ നിന്റെ ചെവിയിൽ ശബ്ദം എത്തിയിട്ടില്ലെങ്കിൽ." (ദ,തു,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 188', array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 757, 757, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ عَبْدِ اللهِ بْنِ بُحَيْنَةَ الْأَسْدِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَامَ فِي صَلَاةِ الظُّهْرِ وَعَلَيْهِ جُلُوسٌ، فَلَمَّا أَتَمَّ صَلَاتَهُ سَجَدَ سَجْدَتَيْنِ، يُكَبِّرُ فِي كُلِّ سَجْدَةٍ وَهُوَ جَالِسٌ قَبْلَ أَنْ يُسَلِّمَ، وَسَجَدَهُمَا النَّاسُ مَعَهُ، مَكَانَ مَا نَسِيَ مِنَ الْجُلُوسِ. حسن صحيح. (ق,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു ബുഹൈഹെനതുൽ അസദി(റ): റസൂൽ(സ) ളുഹ്ർ നിസ്കരിക്കുമ്പോൾ ഇടയിൽ ഇരിക്കാതെ (മറന്ന്) എഴുന്നേറ്റു. ഇടയിലിരുത്തം മറന്നതിന് പകരമായി നമസ്കാരം കഴിഞ്ഞപ്പോൾ രണ്ട് സുജൂദുകൾ ചെയ്തു. ഓരോ സുജൂദിനും തക്ബീർ ചൊല്ലി. സലാം വീട്ടുന്നതിന് മുമ്പ് ഇരുന്നായിരുന്നു അത്. ജനങ്ങളും നബി(സ)യോടപ്പം സുജൂദ് ചെയ്തു. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ബു,മു,തു,ന)', 'عَبْدِ اللهِ بْنِ بُحَيْنَةَ الْأَسْدِيِّ', 'അബ്ദുല്ലാഹിബ്നു ബുഹൈഹെനതുൽ അസദി(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 189', array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 757, 757, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى الظُّهْرَ خَمْسًا، فَقِيلَ لَهُ: أَزِيدَ فِي الصَّلَاةِ؟ فَسَجَدَ سَجْدَتَيْنِ بَعْدَ مَا سَلَّمَ. حسن صحيح. (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) ളുഹ്ർ അഞ്ച് റക്അത്ത് നിർവ്വഹിച്ചു. അങ്ങ് നിസ്കാരം വർദ്ധിപ്പിച്ചിട്ടുണ്ടോ? എന്ന് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ സലാം വീട്ടിയ ശേഷം രണ്ട് സുജൂദ് ചെയ്തു. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 190', array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 757, 757, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَجَدَ سَجْدَتَيِ السَّهْوِ بَعْدَ الْكَلَامِ. وَفِي رِوَايَةٍ: سَجَدَهُمَا بَعْدَ السَّلَامِ. حسن صحيح. (ق,ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): സംസാരിച്ചതിന് ശേഷമാണ് നബി(സ) മറവിയുടെ രണ്ട് സുജൂദ് ചെയ്തത്. മറ്റൊരു നിവേദനത്തിൽ: സലാമിന് ശേഷം രണ്ട് സുജൂദ് ചെയ്തു. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ബു,മു,തു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 191', array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 757, 758, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=30 and h.hadith_no=201), 1, 'وَفِي رِوَايَةٍ: سَجَدَهُمَا بَعْدَ السَّلَامِ. حسن صحيح. (ق,ت)', 'മറ്റൊരു നിവേദനത്തിൽ: സലാമിന് ശേഷം രണ്ട് സുജൂദ് ചെയ്തു. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ബു,മു,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ عَلْقَمَةَ: أَنَّ ابْنَ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ سَجَدَ سَجْدَتَيِ السَّهْوِ بَعْدَ السَّلَامِ، وَذَكَرَ أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَعَلَ ذَلِكَ. (جه)', 'അൽഖമ(റ): ഇബ്നു മസ്ഊദ്(റ) സഹ്വിന്റെ സുജൂദ് നിർവ്വഹിച്ചത് സലാം വീട്ടിയതിന് ശേഷമായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: നബി(സ) അപ്രകാരമാണ് ചെയ്തത്. (ജ)', 'عَلْقَمَةَ', 'അൽഖമ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 192', array['جه']::text[], array['ജ']::text[], null, null, 758, 758, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا قَامَ الْإِمَامُ فِي الرَّكْعَتَيْنِ: فَإِنْ ذَكَرَ قَبْلَ أَنْ يَسْتَوِيَ قَائِمًا فَلْيَجْلِسْ، فَإِنِ اسْتَوَى قَائِمًا فَلَا يَجْلِسْ، وَيَسْجُدْ سَجْدَتَيِ السَّهْوِ". (د,ت,ن,جه)', 'മുഗീറത്തുബ്നു ശുഅ്ബ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇമാം രണ്ട് റക്അത്ത് കഴിഞ്ഞ് (ഇടയിലിരിക്കാൻ മറന്ന്) എഴുന്നേറ്റാൽ പൂർണ്ണമായി നിർത്തത്തിലേക്ക് എത്തുന്നതിന് മുമ്പ് ഓർമ്മ വന്നാൽ (ഇടയിലുള്ള ഇരുത്തം) അപ്പോൾ ഇരിക്കട്ടെ, പൂർണ്ണമായി നിന്ന് കഴിഞ്ഞാൽ പിന്നീട് ഇരിക്കരുത്. അയാൾ സഹ്വിന്റെ രണ്ട് സുജൂദ് ചെയ്യുകയാണ് വേണ്ടത്." (ദ,തു,ന,ജ)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറത്തുബ്നു ശുഅ്ബ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 193', array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 758, 758, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ عَبْدِ اللهِ بْنِ بُحَيْنَةَ قَالَ: صَلَّى لَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَيْنِ، ثُمَّ قَامَ فَلَمْ يَجْلِسْ، فَقَامَ النَّاسُ مَعَهُ، فَلَمَّا قَضَى صَلَاتَهُ وَنَظَرْنَا تَسْلِيمَهُ، كَبَّرَ فَسَجَدَ سَجْدَتَيْنِ وَهُوَ جَالِسٌ قَبْلَ التَّسْلِيمِ، ثُمَّ سَلَّمَ. (ق,ن)', 'അബ്ദുല്ലാഹിബ്നു ബുഹൈന(റ): നബി(സ) ഞങ്ങൾക്കിമാമായി രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. പിന്നെ ഇരിക്കാതെ എഴുന്നേറ്റു നിന്നു. കൂടെ ജനങ്ങളും എഴുന്നേറ്റു. നിസ്കാരം കഴിഞ്ഞ് സലാം വീട്ടുമെന്നു ഞങ്ങൾ പ്രതീക്ഷിച്ചിരിക്കെ നബി(സ) തക്ബീർ ചൊല്ലി സലാം വീട്ടുന്നതിനു മുമ്പായി ഇരുത്തത്തിലായിരിക്കെ രണ്ട് സുജൂദ് ചെയ്തു. പിന്നെ സലാം വീട്ടി. (ബു,മു,ന)', 'عَبْدِ اللهِ بْنِ بُحَيْنَةَ قَالَ', 'അബ്ദുല്ലാഹിബ്നു ബുഹൈന(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 194', array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 758, 758, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ زِيَادِ بْنِ عِلَاقَةَ قَالَ: صَلَّى بِنَا الْمُغِيرَةُ بْنُ شُعْبَةَ رَضِيَ اللهُ عَنْهُ فَنَهَضَ فِي الرَّكْعَتَيْنِ، قُلْنَا: سُبْحَانَ اللهِ، قَالَ: سُبْحَانَ اللهِ، وَمَضَى، فَلَمَّا أَتَمَّ صَلَاتَهُ وَسَلَّمَ سَجَدَ سَجْدَتَيِ السَّهْوِ، فَلَمَّا انْصَرَفَ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ كَمَا صَنَعْتُ. (د,ت)', 'സിയാദ്ബ്നു അലാഖ(റ): മുഗീറത്തുബ്നു ശുഅ്ബ(റ) ഞങ്ങളെയുമായി നിസ്കരിച്ചു; രണ്ട് റക്അത്ത് കഴിഞ്ഞപ്പോൾ അദ്ദേഹം എഴുന്നേറ്റു. ഞങ്ങൾ ''സുബ്ഹാനല്ലാഹ്'' എന്ന് പറഞ്ഞു. അദ്ദേഹവും ''സുബ്ഹാനല്ലാഹ്'' എന്ന് പറഞ്ഞു. എന്നിട്ട് നിസ്കാരം തുടർന്നു. നിസ്കാരം പൂർത്തിയായ ശേഷം സലാം പറഞ്ഞ് സഹ്വിന്റെ രണ്ട് സുജുദ് ചെയ്തു. നിസ്കാരം കഴിഞ്ഞപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ഇപ്രകാരം ചെയ്യുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ദ,തു)', 'زِيَادِ بْنِ عِلَاقَةَ قَالَ', 'സിയാദ്ബ്നു അലാഖ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 195', array['د','ت']::text[], array['ദ','തു']::text[], null, null, 758, 758, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لِكُلِّ سَهْوٍ سَجْدَتَانِ بَعْدَ مَا يُسَلِّمُ". (د,جه)', 'സൗബാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "എല്ലാ മറവിക്കും സലാം വീട്ടിയ ശേഷം രണ്ട് സുജൂദുകളുണ്ട്." (ദ,ജ)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 196', array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 758, 758, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الشَّيْطَانَ يَأْتِي أَحَدَكُمْ فِي صَلَاتِهِ فَيَدْخُلُ بَيْنَهُ وَبَيْنَ نَفْسِهِ حَتَّى لَا يَدْرِيَ زَادَ أَوْ نَقَصَ، فَإِذَا كَانَ ذَلِكَ فَلْيَسْجُدْ سَجْدَتَيْنِ قَبْلَ أَنْ يُسَلِّمَ، ثُمَّ يُسَلِّمُ". (د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിസ്കാരത്തിൽ പിശാച് ഒരാളുടെ അടുത്ത് വരും, കുറഞ്ഞോ, കൂടിയോ എന്ന് അയാൾക്ക് അറിയാൻ കഴിയാത്ത വിധത്തിൽ അയാളുടേയും മനസ്സിന്റേയും ഇടയിൽ അത് പ്രവേശിക്കും. അപ്രകാരം സംഭവിച്ചാൽ സലാം വീട്ടുന്നതിന് മുമ്പ് രണ്ട് സുജൂദുകൾ നിർവ്വഹിക്കുക, ശേഷം സലാം വീട്ടണം." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 197', array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 759, 759, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ مِنَ الْجَفَاءِ أَنْ يُكْثِرَ الرَّجُلُ مَسْحَ جَبْهَتِهِ قَبْلَ الْفَرَاغِ مِنْ صَلَاتِهِ". [ز: في إسناده راو متفق على ضعفه] (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിസ്കാരത്തിൽ നിന്ന് വിരമിക്കുന്നതിന് മുമ്പ് നെറ്റിത്തടം തടവൽ വർദ്ധിപ്പിക്കൽ ഒഴിവാക്കേണ്ടതിൽ പെട്ടതാണ്." (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനാണെന്ന് ഐക്യകണ്ടേന പറയപ്പെട്ട റാവിയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 198', array['جه']::text[], array['ജ']::text[], 'ز: في إسناده راو متفق على ضعفه', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനാണെന്ന് ഐക്യകണ്ടേന പറയപ്പെട്ട റാവിയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 759, 759, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُفَقِّعْ أَصَابِعَكَ وَأَنْتَ فِي الصَّلَاةِ". (جه)', 'അലി(റ): റസൂൽ(സ) പറഞ്ഞു: "നിസ്കാരത്തിലായിരിക്കെ നീ നിന്റെ വിരൽ ഒടിക്കരുത്." (ജ)', 'عَلِيٍّ', 'അലി(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 199', array['جه']::text[], array['ജ']::text[], null, null, 759, 759, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُغْطَى الرَّجُلُ فَاهُ فِي الصَّلَاةِ. (جه)', 'അബൂഹുറൈറ(റ): നിസ്കാരത്തിൽ ഒരാൾ തന്റെ വായ മൂടുന്നത് നബി(സ) നിരോധിച്ചിരിക്കുന്നു. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 200', array['جه']::text[], array['ജ']::text[], null, null, 759, 759, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنْ كَعْبِ بْنِ عُجْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلًا قَدْ شَبَّكَ أَصَابِعَهُ فِي الصَّلَاةِ، فَفَرَّجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَصَابِعِهِ. (ت,جه)', 'കഅ്ബുബ്നു ഉജ്റ(റ): ഒരാൾ നിസ്കാരത്തിൽ തന്റെ വിരലുകൾ കോർത്തു വെച്ചത് നബി(സ) കണ്ടു. അപ്പോൾ നബി(സ) അതിനെ പരസ്പരം അകത്തി. (തു,ജ)', 'كَعْبِ بْنِ عُجْرَةَ', 'കഅ്ബുബ്നു ഉജ്റ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 201', array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 759, 759, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 212, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا تَثَاءَبَ أَحَدُكُمْ فَلْيَضَعْ يَدَهُ عَلَى فِيهِ، وَلَا يَعْوِي، فَإِنَّ الشَّيْطَانَ يَضْحَكُ مِنْهُ". [ز:في إسناده راو متفق على ضعفه] (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും കോട്ടുവായിട്ടാൽ അയാൾ കൈ വായമേൽ വെക്കട്ടെ, ഓരിയിടരുത്. കാരണം പിശാച് അത് കേൾക്കുമ്പോൾ ചിരിക്കും." (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനാണെന്ന് ഐക്യകണ്ടേന പറയപ്പെട്ട റാവിയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 202', array['جه']::text[], array['ജ']::text[], 'ز:في إسناده راو متفق على ضعفه', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനാണെന്ന് ഐക്യകണ്ടേന പറയപ്പെട്ട റാവിയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 759, 759, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 213, 'عَنْ عَبْدِ اللهِ بْنِ يَزِيدَ الْخَطْمِيِّ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْبُزَاقُ وَالْمُخَاطُ وَالْحَيْضُ وَالنُّعَاسُ فِي الصَّلَاةِ مِنَ الشَّيْطَانِ". [ز: في إسناده راو متفق على ضعفه] (جه)', 'അബ്ദുല്ലാഹിബ്നു യസീദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിസ്കാരത്തിൽ കാർക്കിച്ചു തുപ്പലും, മൂക്ക് ചീറ്റലും, ആർത്തവവും, തൂങ്ങി ഉറക്കവും പിശാചിൽ നിന്നുള്ളതാണ്." (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനാണെന്ന് ഐക്യകണ്ടേന പറയപ്പെട്ട റാവിയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'عَبْدِ اللهِ بْنِ يَزِيدَ الْخَطْمِيِّ', 'അബ്ദുല്ലാഹിബ്നു യസീദ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 203', array['جه']::text[], array['ജ']::text[], 'ز: في إسناده راو متفق على ضعفه', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനാണെന്ന് ഐക്യകണ്ടേന പറയപ്പെട്ട റാവിയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 759, 759, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 214, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "وَاللهِ إِنِّي لَأَسْمَعُ بُكَاءَ الصَّبِيِّ وَأَنَا فِي الصَّلَاةِ فَأُخَفِّفُ، مَخَافَةَ أَنْ تُفْتَنَ أُمُّهُ". حسن صحيح (ق,ت,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവാണെ, ഞാൻ നിസ്കാരത്തിലായിരിക്കെ കുട്ടികളുടെ കരച്ചിൽ കേട്ടാൽ അവരുടെ മാതാക്കൾ അശ്രദ്ധയിലാകുമെന്ന ഭയത്താൽ ഞാൻ നിസ്കാരം ലഘൂകരിക്കും." (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ബു,മു,തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 204', array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 760, 760, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 215, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنِّي لَأَقُومُ فِي الصَّلَاةِ أُرِيدُ أَنْ أُطَوِّلَ فِيهَا، فَأَسْمَعُ بُكَاءَ الصَّبِيِّ فَأَتَجَوَّزُ فِي صَلَاتِي كَرَاهِيَةَ أَنْ أَشُقَّ عَلَى أُمِّهِ". (خ)', 'അബൂഖതാദ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ നിസ്കാരത്തിൽ നിന്നപ്പോൾ അത് ദീർഘിപ്പിക്കാൻ ഉദ്ദ്യേശിച്ചു. അപ്പോൾ ഒരു കുട്ടിയുടെ കരച്ചിൽ കേട്ടു. അതിന്റെ മാതാവിന് പ്രയാസമുണ്ടാവുന്നത് ഭയന്ന് ഞാൻ നിസ്കാരം ലഘൂകരിച്ചു." (ബു)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 205', array['خ']::text[], array['ബു']::text[], null, null, 760, 760, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 216, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ خَلْفَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا كَبَّرَ رَفَعَ يَدَيْهِ أَسْفَلَ مِنْ أُذُنَيْهِ، فَلَمَّا قَرَأَ: {غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ} قَالَ: "آمِينَ". فَسَمِعْتُهُ وَأَنَا خَلْفَهُ، قَالَ: فَسَمِعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلًا يَقُولُ: الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ. فَلَمَّا سَلَّمَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ صَلَاتِهِ قَالَ: "مَنْ صَاحِبُ الْكَلِمَةِ فِي الصَّلَاةِ". فَقَالَ الرَّجُلُ: أَنَا يَا رَسُولَ اللهِ، وَمَا أَرَدْتُ بِهَا بَأْسًا. قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَقَدِ ابْتَدَرَهَا اثْنَا عَشَرَ مَلَكًا، فَمَا نَهْنَهَهَا شَيْءٌ دُونَ الْعَرْشِ". (ن)', 'വാഇലുബ്നു ഹുജ്ർ(റ): ഞാൻ തിരുമേനി(സ)ക്കു പിന്നിൽ നിസ്കരിച്ചു. അവിടുന്ന് തക്ബീർ ചൊല്ലിയപ്പോൾ തന്റെ ഇരുകൈകളും ചെവിക്കു താഴെവരെ ഉയർത്തി. ''ഗൈരിൽ മഗ്ളൂബി അലൈഹിം വലള്ളാല്ലീൻ'' എന്നു ചൊല്ലിയശേഷം ''ആമീൻ'' എന്നു ചൊല്ലി. ഞാൻ തിരുമേനിയുടെ പിന്നിലായിരിക്കെ അതു (''ആമീൻ'' ചൊല്ലുന്നതു) കേട്ടു. അന്നേരം ഒരാൾ ''അല്ലാഹുവിന്നാകുന്നു സർവ്വസ്തുതിയും, ധാരാളം സ്തുതി, ഉത്കൃഷ്ടവും അനുഗ്രഹപൂർണവുമായ സ്തുതി'' എന്ന് പറയുന്നത് തിരുമേനി(സ) കേട്ടു. നിസ്കാരം കഴിഞ്ഞപ്പോൾ തിരുമേനി(സ) ചോദിച്ചു: ആരാണ് നിസ്കാരത്തിൽ സംസാരിച്ചത്? ആ വ്യക്തി പറഞ്ഞു: ഞാനാണ്, ദൈവദൂതരേ, ഞാനതുകൊണ്ട് നല്ലതല്ലാതെ ഉദ്ദേശിച്ചിട്ടില്ല. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: അതെടുക്കുവാൻ വേണ്ടി പന്ത്രണ്ടു മാലാഖമാർ മൽസരിക്കുകയുണ്ടായി. അതിനെ അല്ലാഹുവിന്റെ സിംഹാസനമല്ലാതെ മറ്റൊന്നും തടഞ്ഞിട്ടില്ല. (ന)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹുജ്ർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 206', array['ن']::text[], array['ന']::text[], null, null, 760, 760, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 217, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اقْتُلُوا الْأَسْوَدَيْنِ فِي الصَّلَاةِ: الْحَيَّةَ وَالْعَقْرَبَ". (د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിസ്കാരത്തിൽ രണ്ട് ഉപദ്രവകാരികളെ കണ്ടാൽ നിങ്ങൾ കൊന്നു കളയുക. പാമ്പും തേളുമാണത്." (ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 207', array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 760, 760, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 218, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، وَالْبَابُ عَلَيْهِ مُغْلَقٌ، فَجِئْتُ فَاسْتَفْتَحْتُ، ثُمَّ رَجَعَ إِلَى مُصَلَّاهُ، وَذَكَرَ أَنَّ الْبَابَ كَانَ فِي الْقِبْلَةِ. (د,ت,ن)', 'ആഇശ(റ) പറഞ്ഞു: "വാതിലടച്ചിട്ടു കൊണ്ട് നബി(സ) നിസ്കരിക്കുകയായിരുന്നു. അപ്പോൾ ഞാൻ ചെന്ന് വാതിൽ തുറക്കാൻ ആവശ്യപ്പെട്ടപ്പോൾ നബി(സ) നടന്നു വന്ന് എനിക്ക് വേണ്ടി തുറന്നു തന്നു. പിന്നീട് നിസ്കാര സ്ഥലത്തേക്ക് തന്നെ മടങ്ങി. വാതിൽ ഖിബ്ലയുടെ ഭാഗത്തായിരുന്നു. (ദ,തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 208', array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 760, 760, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 219, 'عَنْ عَمَّارِ بْنِ يَاسِرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ الرَّجُلَ لَيَنْصَرِفُ وَمَا كُتِبَ لَهُ إِلَّا عُشْرُ صَلَاتِهِ، تُسْعُهَا، ثُمُنُهَا، سُبْعُهَا، سُدْسُهَا، خُمْسُهَا، رُبْعُهَا، ثُلُثُهَا، نِصْفُهَا". (د,ن)', 'അമ്മാറുബാനുയാസിർ(റ): പ്രവാചകൻ(സ) ഇപ്രകാരം പറയുന്നതു ഞാൻ കേട്ടു: "ഒരാൾ നിസ്കരിച്ചു കഴിയുമ്പോൾ അവന് (അല്ലാഹുവിന്റെ അടുക്കൽ അതിന്റെ പ്രതിഫലത്തിന്റെ) പത്തിൽ ഒന്നോ, ഒമ്പതിൽ ഒന്നോ, എട്ടിൽ ഒന്നോ, ഏഴിൽ ഒന്നോ, നാലിൽ ഒന്നോ, അഞ്ചിൽ ഒന്നോ, നാലിൽ ഒന്നോ, മൂന്നിൽ ഒന്നോ, രണ്ടിൽ ഒന്നോ മാത്രമല്ലാതെ രേഖപ്പെടുത്തപ്പെടുകയില്ല (എന്ന അവസ്ഥയുണ്ടായേക്കാം)." (ദ,ന)', 'عَمَّارِ بْنِ يَاسِرٍ', 'അമ്മാറുബാനുയാസിർ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 209', array['د','ن']::text[], array['ദ','ന']::text[], null, null, 761, 761, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 220, 'عَنْ كَعْبِ بْنِ عُجْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا تَوَضَّأَ أَحَدُكُمْ فَأَحْسَنَ وُضُوءَهُ، ثُمَّ خَرَجَ عَامِدًا إِلَى الْمَسْجِدِ، فَلَا يُشَبِّكَنَّ بَيْنَ أَصَابِعِهِ، فَإِنَّهُ فِي صَلَاةٍ". (د,ت,جه)', 'കഅ്ബിബ്നു ഉജ്റ(റ): റസൂൽ(സ) പറഞ്ഞു: "വല്ലവനും വുദൂ ചെയ്യുകയും വുദൂ നന്നാക്കുകയും, എന്നിട്ട് പള്ളിയെ ലക്ഷ്യമാക്കി പുറപ്പെടുകയും ചെയ്താൽ അവൻ കൈ വിരലുകൾ കോർത്ത് പിടിക്കരുത്, കാരണം അയാൾ നിസ്കാരത്തിൽ ആണ്." (ദ,തു,ജ)', 'كَعْبِ بْنِ عُجْرَةَ', 'കഅ്ബിബ്നു ഉജ്റ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 210', array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 761, 761, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 221, 'عَنْ رِفَاعَةَ بْنِ رَافِعٍ الزُّرَقِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ خَلْفَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَعَطَسْتُ، فَقُلْتُ الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ مُبَارَكًا عَلَيْهِ كَمَا يُحِبُّ رَبُّنَا وَيَرْضَى، فَلَمَّا صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ انْصَرَفَ، فَقَالَ: "مَنِ الْمُتَكَلِّمُ فِي الصَّلَاةِ؟" فَلَمْ يَتَكَلَّمْ أَحَدٌ، ثُمَّ قَالَهَا الثَّانِيَةَ: "مَنِ الْمُتَكَلِّمُ فِي الصَّلَاةِ؟" فَلَمْ يَتَكَلَّمْ أَحَدٌ، ثُمَّ قَالَهَا الثَّالِثَةَ: "مَنِ الْمُتَكَلِّمُ فِي الصَّلَاةِ؟" فَقَالَ رِفَاعَةُ بْنُ رَافِعٍ ابْنُ عَفْرَاءَ: أَنَا يَا رَسُولَ اللهِ، قَالَ: "كَيْفَ قُلْتَ؟" قَالَ: قُلْتُ الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ مُبَارَكًا عَلَيْهِ كَمَا يُحِبُّ رَبُّنَا وَيَرْضَى، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِي نَفْسِي بِيَدِهِ، لَقَدِ ابْتَدَرَهَا بِضْعَةٌ وَثَلَاثُونَ مَلَكًا أَيُّهُمْ يَصْعَدُ بِهَا" حديث. حسن. (د,ت,ن)', 'റിഫാഅത്തു ബ്നു റാഫിഉസ്സുറഖി(റ): ഞാൻ റസൂലി(സ)ന്റെ പിന്നിൽ നിന്ന് നിസ്കരിച്ചു. അങ്ങനെ ഞാൻ തുമ്മിയപ്പോൾ ഇപ്രകാരം പറഞ്ഞു: ''അല്ലാഹുവിന്ന് ധാരാളം സ്തുതി, എല്ലാ ഉത്തമവും പരിശുദ്ധവുമായ സ്തുതി. ഞങ്ങളുടെ നാഥൻ ഇഷ്ടപ്പെടുകയും തൃപ്തിപ്പെടുകയും ചെയ്യും പോലെ.'' അങ്ങനെ റസൂൽ(സ) നിസ്കരിച്ചുകഴിഞ്ഞപ്പോൾ ചോദിച്ചു: "ആരാണ് നമസ്കാരത്തിൽ സംസാരിച്ചത്." ആരും മറുപടി പറഞ്ഞില്ല. രണ്ടാമതും ചോദിച്ചു: "ആരാണ് നിസ്കാരത്തിൽ സംസാരിച്ചത്." ഒരാളും മറുപടി പറഞ്ഞില്ല. മൂന്നാമതും അതേ ചോദ്യം ആവർത്തിച്ചു. അപ്പോൾ രിഫാഅത്തുബ്നു റാഫിഅ്(റ) പറഞ്ഞു: ഞാനാണ് പ്രവാചകരെ. നബി(സ) ചോദിച്ചു: "എന്താണ് നീ ചൊല്ലിയത്?" ഞാൻ പറഞ്ഞു: ''അല്ലാഹുവിന്ന് ധാരാളം സ്തുതി, എല്ലാ ഉത്തമവും പരിശുദ്ധവുമായ സ്തുതി. ഞങ്ങളുടെ നാഥൻ ഇഷ്ടപ്പെടുകയും തൃപ്തിപ്പെടുകയും ചെയ്യും പോലെ.'' അപ്പോൾ നബി(സ) പറഞ്ഞു: "എന്റെ ആത്മാവ് ഉടമപ്പെടുത്തിയവൻ തന്നെ സത്യം, മുപ്പതിലധികം മലക്കുകൾ അതുമായി മുന്നോട്ടുവന്നു, ആരാണ് അതിനെ ഉയർത്തുക എന്ന കാര്യത്തിൽ മത്സരിച്ച്കൊണ്ട്." (ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു). (ദ,തു,ന)', 'رِفَاعَةَ بْنِ رَافِعٍ الزُّرَقِيِّ', 'റിഫാഅത്തു ബ്നു റാഫിഉസ്സുറഖി(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 211', array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 761, 761, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 222, 'عَنِ الْمُطَّلِبِ بْنِ أَبِي وَدَاعَةَ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ طَافَ بِالْبَيْتِ سَبْعًا، ثُمَّ صَلَّى رَكْعَتَيْنِ بِحَذَائِهِ فِي حَاشِيَةِ الْمَقَامِ، وَلَيْسَ بَيْنَهُ وَبَيْنَ الطُّوَّافِ أَحَدٌ. (ن)', 'മുത്തലിബുബ്നു അബൂവദാഅ(റ): നബി(സ) ഏഴു പ്രാവശ്യം കഅ്ബഃ ത്വവാഫ് ചെയ്യുന്നത് ഞാൻ കണ്ടു. പിന്നെ കഅ്ബക്കഭിമുഖമായി മഖാമു ഇബ്രാഹീമിന്റെ ഭാഗത്തു നിന്ന് നിസ്കരിച്ചു. നബി(സ)ക്കും ത്വവാഫ് ചെയ്യുന്നവർക്കുമിടയിൽ ആരുമുണ്ടായിരുന്നില്ല. (ന)', 'الْمُطَّلِبِ بْنِ أَبِي وَدَاعَةَ قَالَ', 'മുത്തലിബുബ്നു അബൂവദാഅ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 212', array['ن']::text[], array['ന']::text[], null, null, 762, 762, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 223, 'عَنْ أَبِي مَرْثَدٍ الْغَنَوِيِّ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُصَلُّوا إِلَى الْقُبُورِ، وَلَا تَجْلِسُوا عَلَيْهَا". (م,ن)', 'അബൂമർസദുൽ ഗനവി(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഖബ്റിലേക്കു തിരിഞ്ഞ് നിസ്കരിക്കുകയോ ഖബ്റിനു മുകളിൽ ഇരിക്കുകയോ ചെയ്യരുത്." (മു,ന)', 'أَبِي مَرْثَدٍ الْغَنَوِيِّ قَالَ', 'അബൂമർസദുൽ ഗനവി(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 213', array['م','ن']::text[], array['മു','ന']::text[], null, null, 762, 762, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 224, 'عَنْ عَمْرِو بْنِ سَلَمَةَ قَالَ: لَمَّا رَجَعَ قَوْمِي مِنْ عِنْدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالُوا: إِنَّهُ قَالَ: "لِيَؤُمَّكُمْ أَكْثَرُكُمْ قِرَاءَةً لِلْقُرْآنِ". قَالَ: فَدَعَوْنِي، فَعَلَّمُونِي الرُّكُوعَ وَالسُّجُودَ، فَكُنْتُ أُصَلِّي بِهِمْ، وَكَانَتْ عَلَيَّ بُرْدَةٌ مَفْتُوقَةٌ، فَكَانُوا يَقُولُونَ لِأَبِي: أَلَا تُغَطِّي عَنَّا اسْتَ ابْنِكَ. (ن)', 'അംറുബ്നു സലമ(റ): നബി(സ)യുടെ അടുത്തു നിന്ന് എന്റെ സമുദായം (ഗോത്രം) മടങ്ങിയപ്പോൾ അവർ പറഞ്ഞു: നബി(സ) പറഞ്ഞത്: "നിങ്ങളിൽ നന്നായി ഖുർആൻ പാരായണം ചെയ്യാനറിയുന്നവൻ ഇമാം നിൽക്കട്ടെ" എന്നാണ്. അദ്ദേഹം പറഞ്ഞു: അവർ എന്നെ വിളിച്ച് റുകൂളും സുജൂദും പഠിപ്പിച്ചുതന്നു. ഞാൻ അവർക്കിമാമായി നിസ്കരിക്കുകയായിരുന്നു. എന്റെ ദേഹത്ത് ഒരു പുതപ്പ് ചുരുട്ടി ഇട്ടിരുന്നു. അവർ എന്റെ പിതാവിനോട് പറഞ്ഞു: താങ്കളുടെ മകന്റെ ആസനം താങ്കൾക്കൊന്ന് മറച്ചുകൂടെ. (ന)', 'عَمْرِو بْنِ سَلَمَةَ قَالَ', 'അംറുബ്നു സലമ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 214', array['ن']::text[], array['ന']::text[], null, null, 762, 762, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 225, 'عَنِ ابْنِ عَبَّاسٍ قَالَ: أُمِرَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَسْجُدَ عَلَى سَبْعَةِ أَعْظُمٍ، وَنُهِيَ أَنْ يَكُفَّ الشَّعْرَ وَالثِّيَابَ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഏഴ് അവയവങ്ങളിൽ സുജൂദ് ചെയ്യാൻ കൽപിക്കപ്പെട്ടു. മുടിയോ വസ്ത്രമോ പിടിക്കുന്നത് വിരോധിക്കപ്പെടുകയും ചെയ്തു. (ന)', 'ابْنِ عَبَّاسٍ قَالَ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 215', array['ن']::text[], array['ന']::text[], null, null, 762, 762, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 226, 'عَنْ مُعَاذِ بْنِ عَبْدِ اللهِ الْجُهَنِيِّ: أَنَّ رَجُلًا مِنْ جُهَيْنَةَ أَخْبَرَهُ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الصُّبْحِ: {إِذَا زُلْزِلَتِ الْأَرْضُ} فِي الرَّكْعَتَيْنِ كِلْتَيْهِمَا، فَلَا أَدْرِي: أَنَسِيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمْ قَرَأَ ذَلِكَ عَمْدًا. (د)', 'മുആദുബ്നു അബ്ദുല്ലാഹിൽ ജുഹനീ(റ): പ്രവാചകൻ(സ) സുബ്ഹിലെ രണ്ടു റക്അത്തിലും ''ഇദാ സുൽസിലത്തിൽ അർളു .......'' ഓതി. തിരുമേനി(സ) അത് (രണ്ടു റക്അത്തിലും) പാരായണം ചെയ്തത് മറന്നുകൊണ്ടാണോ അതോ ബോധപൂർവ്വമാണോ എന്നത് എനിക്കറിയില്ല. (ദ)', 'مُعَاذِ بْنِ عَبْدِ اللهِ الْجُهَنِيِّ', 'മുആദുബ്നു അബ്ദുല്ലാഹിൽ ജുഹനീ(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 216', array['د']::text[], array['ദ']::text[], null, null, 763, 763, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 227, 'عَنْ مُعَاوِيَةَ بْنِ الْحَكَمِ السُّلَمِيِّ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، إِنَّا حَدِيثُ عَهْدٍ بِجَاهِلِيَّةٍ، فَجَاءَ اللهُ بِالْإِسْلَامِ، وَإِنَّ رِجَالًا مِنَّا يَتَطَيَّرُونَ. قَالَ: "ذَاكَ شَيْءٌ يَجِدُونَهُ فِي صُدُورِهِمْ فَلَا يَصُدَّنَّهُمْ" وَرِجَالٌ مِنَّا يَأْتُونَ الْكُهَّانَ، قَالَ: "فَلَا تَأْتُوهُمْ". قَالَ: يَا رَسُولَ اللهِ، وَرِجَالٌ مِنَّا يَخُطُّونَ، قَالَ: "كَانَ نَبِيٌّ مِنَ الْأَنْبِيَاءِ يَخُطُّ، فَمَنْ وَافَقَ خَطَّهُ فَذَاكَ". قَالَ: وَبَيْنَا أَنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الصَّلَاةِ، إِذْ عَطَسَ رَجُلٌ مِنَ الْقَوْمِ فَقُلْتُ: يَرْحَمُكَ اللهُ، فَحَدَّقَنِي الْقَوْمُ بِأَبْصَارِهِمْ، فَقُلْتُ: وَا ثُكْلَ أُمِّيَاهْ مَا لَكُمْ تَنْظُرُونَ إِلَيَّ؟ قَالَ: فَضَرَبَ الْقَوْمُ بِأَيْدِيهِمْ عَلَى أَفْخَاذِهِمْ، فَلَمَّا رَأَيْتُهُمْ يُسَكِّتُونِي لَكِنِّي سَكَتُّ، فَلَمَّا انْصَرَفَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَعَانِي بِأَبِي وَأُمِّي، هُوَ مَا ضَرَبَنِي وَلَا كَهَرَنِي وَلَا سَبَّنِي، مَا رَأَيْتُ مُعَلِّمًا قَبْلَهُ وَلَا بَعْدَهُ أَحْسَنَ تَعْلِيمًا مِنْهُ، قَالَ: "إِنَّ صَلَاتَنَا هَذِهِ لَا يَصْلُحُ فِيهَا شَيْءٌ مِنْ كَلَامِ النَّاسِ، إِنَّمَا هُوَ التَّسْبِيحُ وَالتَّكْبِيرُ وَتِلَاوَةُ الْقُرْآنِ". قَالَ: ثُمَّ اطَّلَعْتُ إِلَى غُنَيْمَةٍ لِي تَرْعَاهَا جَارِيَةٌ لِي فِي قِبَلِ أُحُدٍ وَالْجَوَّانِيَّةِ، وَإِنِّي اطَّلَعْتُ فَوَجَدْتُ الذِّئْبَ قَدْ ذَهَبَ مِنْهَا بِشَاةٍ، وَأَنَا رَجُلٌ مِنْ بَنِي آدَمَ آسَفُ كَمَا يَأْسَفُونَ، فَصَكَكْتُهَا صَكَّةً، ثُمَّ انْصَرَفْتُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرْتُهُ، فَعَظُمَ ذَلِكَ عَلَيَّ، فَقُلْتُ: يَا رَسُولَ اللهِ، أَفَلَا أُعْتِقُهَا؟ قَالَ: "ادْعُهَا". فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَيْنَ اللهُ عَزَّ وَجَلَّ؟". قَالَتْ: فِي السَّمَاءِ، قَالَ: "فَمَنْ أَنَا؟". قَالَتْ: أَنْتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "إِنَّهَا مُؤْمِنَةٌ فَأَعْتِقْهَا". (م,د)', 'മുആവിയതുബ്നു ഹകമിസ്സലമി(റ): ഞാൻ നബി(സ)യോട് പറഞ്ഞു: പ്രവാചകരെ, ജാഹിലിയ്യാ കാലഘട്ടവുമായി അടുത്തയാളുകളാണ് ഞങ്ങൾ. അപ്പോഴാണ് അല്ലാഹു ഇസ്ലാമുമായി വന്നത്. ഞങ്ങളിൽ പലരും പക്ഷി ലക്ഷണം നോക്കുന്നവരാണ്. നബി(സ) പറഞ്ഞു: "അതവർക്ക് മനസ്സിൽ തോന്നുന്ന കാര്യമാണ്. അത് അവരെ തടയുകയില്ല (ഒരു തിന്മയിൽ നിന്നും)." ഞാൻ പറഞ്ഞു: ഞങ്ങളിൽ പലരും ജ്യോത്സ്യരെ സമീപിക്കാറുണ്ട്. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അവരുടെയടുത്ത് പോവരുത്." ഞാൻ പറഞ്ഞു: പ്രവാചകരെ, ഞങ്ങളിൽ പലരും വരക്കാറുണ്ട്. നബി(സ) പറഞ്ഞു: "പ്രവാചകന്മാരിൽ ഒരാൾ വരച്ചിരുന്നു. ആരുടെയെങ്കിലും രേഖ (ആ വരയുമായി) യോജിച്ചു വന്നാൽ ശരിയായി." അങ്ങനെ ഞാൻ നബി(സ)യോടൊപ്പം നിസ്കരിക്കവെ ഒരാൾ തുമ്മിയപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹു നിനക്ക് കരുണ ചൊരിയട്ടെ. ആളുകളെല്ലാം എന്നെ തുറിച്ചു നോക്കി. ഞാൻ ചോദിച്ചു: നിങ്ങളെന്താണ് എന്നെ നോക്കുന്നത്? അപ്പോൾ ആളുകൾ തുടയിൽ അടിച്ചു കൊണ്ട് എന്നെ അടക്കാൻ ശ്രമിച്ചു. ഞാൻ അടങ്ങിയിരുന്നു. നിസ്കാര ശേഷം നബി(സ) എന്നെ വിളിച്ചു. എന്റെ ഉമ്മയും ഉപ്പയുമാണേ, അവിടുന്ന് എന്നെ അടിക്കുകയോ, മോശമായി നോക്കുകയോ ചീത്ത പറയുകയോ ചെയ്തില്ല. അതിനു മുമ്പും ശേഷവും ഇത്രയും നല്ല ഒരധ്യാപകനെ ഞാൻ കണ്ടിട്ടില്ല. നബി(സ) പറഞ്ഞു: "നമ്മുടെ ഈ നിസ്കാരത്തിൽ ഒരു സംസാരവും നല്ലതല്ല. കാരണം നിസ്കാരം തസ്ബീഹും, തക്ബീറും, ഖുർആൻ പാരായണവുമാണ്." എന്റെ ഒരടിമ സ്ത്രീ ഉഹ്ദിന്റെയും ജവ്വാനിയ്യയുടെയും ഭാഗത്തായി എന്റെ ആടുകളെ മേച്ചിരുന്നു. അതിൽനിന്ന് ഒരു ആട്ടിൻ കുട്ടിയെ ചെന്നായ പിടിച്ചുകൊണ്ടുപോയത് ഞാൻ കാണാനിടയായി. ഞാനും മനുഷ്യരിലൊരാളാണ്. അവരെപ്പോലെ ഞാനും ദേഷ്യപ്പെടും. ഞാൻ അവൾക്കൊരു അടി കൊടുത്തു. പിന്നെ നബി(സ)യുടെ അടുത്തു ചെന്ന് വിവരം പറഞ്ഞു. നബി(സ) ഈ വിവരം ഗൗരവമായെടുത്തു. ഞാൻ ചോദിച്ചു: എന്നാൽ ഞാനവളെ മോചിപ്പിക്കട്ടെയോ. നബി(സ) പറഞ്ഞു: "അവളെ വിളിക്കൂ!" നബി(സ) അവളോട് ചോദിച്ചു: "അല്ലാഹു എവിടെയാണ്?" അവൾ പറഞ്ഞു: ആകാശത്ത്. നബി(സ) ചോദിച്ചു: "ഞാനാരാണ്?" അവൾ പറഞ്ഞു: താങ്കൾ അല്ലാഹുവിന്റെ ദൂതനാണ്. നബി(സ) പറഞ്ഞു: "അവൾ സത്യ വിശാസിനിയാണ്. അവളെ മോചിപ്പിക്കൂ!" (മു,ദ)', 'مُعَاوِيَةَ بْنِ الْحَكَمِ السُّلَمِيِّ قَالَ', 'മുആവിയതുബ്നു ഹകമിസ്സലമി(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 217', array['م','د']::text[], array['മു','ദ']::text[], null, null, 763, 764, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 228, 'عَنْ مُعَاوِيَةَ بْنِ الْحَكَمِ السُّلَمِيِّ قَالَ: لَمَّا قَدِمْتُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلِمْتُ أُمُورًا مِنْ أُمُورِ الْإِسْلَامِ، فَكَانَ فِيمَا عَلِمْتُ أَنْ قَالَ لِي: "إِذَا عَطَسْتَ فَاحْمَدِ اللهَ، وَإِذَا عَطَسَ الْعَاطِسُ فَحَمِدَ اللهَ، فَقُلْ: يَرْحَمُكَ اللهُ". قَالَ: فَبَيْنَمَا أَنَا قَائِمٌ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الصَّلَاةِ، إِذْ عَطَسَ رَجُلٌ فَحَمِدَ اللهَ، فَقُلْتُ: يَرْحَمُكَ اللهُ رَافِعًا بِهَا صَوْتِي، فَرَمَانِي النَّاسُ بِأَبْصَارِهِمْ حَتَّى احْتَمَلَنِي ذَلِكَ فَقُلْتُ: مَا لَكُمْ تَنْظُرُونَ إِلَيَّ بِأَعْيُنٍ شُزْرٍ؟ قَالَ: فَسَبَّحُوا، فَلَمَّا قَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنِ الْمُتَكَلِّمُ؟". قِيلَ: هَذَا الْأَعْرَابِيُّ، فَدَعَانِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لِي: "إِنَّمَا الصَّلَاةُ لِقِرَاءَةِ الْقُرْآنِ وَذِكْرِ اللهِ جَلَّ وَعَزَّ، فَإِذَا كُنْتَ فِيهَا فَلْيَكُنْ ذَلِكَ شَأْنُكَ". فَمَا رَأَيْتُ مُعَلِّمًا، قَطُّ أَرْفَقَ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'മുആവിയതുബ്നു ഹകമിസ്സലമി(റ): ഞാൻ നബി(സ)യുടെ അടുത്ത് പോയപ്പോൾ ഇസ്ലാമിന്റെ പല കാര്യങ്ങളും അറിയാനിടയായി. നബി(സ) എന്നോട് പറഞ്ഞു: "നീ തുമ്മിയാൽ അല്ലാഹുവിനെ സ്തുതിക്കണം. ഒരാൾ തുമ്മുമ്പോൾ അല്ലാഹുവിനെ സ്തുതിച്ചാൽ അല്ലാഹു നിനക്ക് അനുഗ്രഹം ചെയ്യട്ടെ എന്ന് നീ പറയുക." അങ്ങനെ ഞാൻ നബി(സ)യോടൊപ്പം നിസ്കാരത്തിലായിരിക്കെ ഒരാൾ തുമ്മുകയും അല്ലാഹുവിനെ സ്തുതിക്കുകയും ചെയ്തു. ഞാൻ ഉച്ചത്തിൽ പറഞ്ഞു: അല്ലാഹു നിനക്ക് അനുഗ്രഹം ചെയ്യട്ടെ. അപ്പോൾ ജനങ്ങളെല്ലാം എന്നെ തുറിച്ചു നോക്കി. അതെനിക്ക് സഹിക്കാനായില്ല. ഞാൻ ചോദിച്ചു: നിങ്ങളെന്താണ് എന്നെ ഇങ്ങനെ ദേഷ്യപ്പെട്ട് നോക്കുന്നത്? അപ്പോൾ അവരെല്ലാം തസ്ബീഹ് ചൊല്ലി. നിസ്കാരശേഷം നബി(സ) ചോദിച്ചു: "ആരാണ് സംസാരിച്ചത്?" ''ഇതാ ഈ അഅ്റാബിയാണ്'' എന്ന് ഒരാൾ പറഞ്ഞു. അപ്പോൾ നബി(സ) എന്നെ വിളിച്ച് പറഞ്ഞു: "നിസ്കാരം ഖുർആൻ പാരായണത്തിനും അല്ലാഹുവിന് ദിക്ർ ചൊല്ലാനുമാണ്. നിസ്കാരത്തിൽ നീയും അപ്രകാരം ചെയ്യുക." നബി(സ)യെക്കാൾ മൃദുവായ ഒരദ്ധ്യാപകനെയും ഞാൻ തീരെ കണ്ടിട്ടില്ല. (ദ)', 'مُعَاوِيَةَ بْنِ الْحَكَمِ السُّلَمِيِّ قَالَ', 'മുആവിയതുബ്നു ഹകമിസ്സലമി(റ)', null, 'അച്ചടിയിലെ നമ്പർ: 218', array['د']::text[], array['ദ']::text[], null, null, 764, 764, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 229, 'حَدِيثُ ابْنِ مَسْعُودٍ فِي دُعَاءِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى قُرَيْشٍ يَوْمَ وَضَعُوا عَلَيْهِ السَّلَى....، وَقَالَ هُنَا فِي آخِرِهِ: ثُمَّ سُحِبُوا إِلَى الْقَلِيبِ، ثُمَّ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: وَأُتْبِعَ أَصْحَابُ الْقَلِيبِ لَعْنَةً. (خ)', 'തിരുമേനി(സ)യുടെ ശരീരത്തിൽ, ഖുറൈശികൾ, ഒട്ടകത്തിന്റെ മറുകുട്ടി കൊണ്ടുവന്നു ഇട്ട ദിവസം. അവർക്കെതിരായി തിരുമേനി(സ) പ്രാർത്ഥിച്ച സംഭവം വിവരിച്ചുകൊണ്ട് ഇബ്നുമസ്ഊദ്(റ) റിപ്പോർട്ട് ചെയ്ത ഹദീസിന്റെ അവസാനത്തിൽ പറയുന്നു: "പിന്നീട് ബദ്റിലെ കിണറ്റിലേക്ക് അവരെ വലിച്ചുകൊണ്ടുപോയി. തിരുമേനി അരുളി: "കിണറ്റിലിടപ്പെട്ടവർക്ക് തുടർച്ചയായി ശാപമേൽക്കട്ടെ." (ബു)', null, null, null, 'അച്ചടിയിലെ നമ്പർ: 219', array['خ']::text[], array['ബു']::text[], null, null, 764, 764, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=1 and b.book_no=30 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
